window.VOCAB_HAUSAUFGABEN = [{"id":"01-konjunktiv","no":1,"title":"Konjunktiv","title_en":"第二虚拟式（Konjunktiv II）和 wenn 从句 · weil、wegen、deswegen、denn","added":"2026-11-06","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 130","heading":"A  Wenn ich du wäre, würde ich …","heading_en":"如果我是你，我会……","exercises":[{"no":"1","tag":"Wiederholung A2, L8","instruction":"Evas Realität – Evas Wünsche. Ergänzen Sie: *würde – hätte – wäre*.","instruction_en":"伊娃的现实——伊娃的愿望。填空：würde – hätte – wäre。","box":["würde","hätte","wäre"],"example":[{"label":"a","lead":"Eva hat rote Haare.","text":"Sie **hätte** aber gern schwarze Haare."}],"items":[{"label":"b","lead":"Sie ist ein bisschen klein.","text":"Sie ___ aber gern grösser.","gaps":[["wäre"]],"solution":"Sie **wäre** aber gern grösser.","en":"不过她很想再高一点。","why":"*grösser sein*：*sein* 的愿望形式是 **wäre**。","source":"k2"},{"label":"c","lead":"Sie kann nicht Spanisch sprechen.","text":"Sie ___ aber gern gut Spanisch sprechen.","gaps":[["würde"]],"solution":"Sie **würde** aber gern gut Spanisch sprechen.","en":"不过她很想把西班牙语说好。","why":"句末有一个不定式（*sprechen*），所以愿望用 **würde** + 不定式。","source":"k2"},{"label":"d","lead":"Sie arbeitet in einem Reisebüro.","text":"Sie ___ aber lieber als Reiseführerin arbeiten.","gaps":[["würde"]],"solution":"Sie **würde** aber lieber als Reiseführerin arbeiten.","en":"不过她更想当导游。","why":"句末是不定式（*arbeiten*）→ **würde** + 不定式。*lieber* = 更愿意。","source":"k2"},{"label":"e","lead":"Sie hat eine sehr kleine Wohnung.","text":"Sie ___ aber gern eine grosse Wohnung.","gaps":[["hätte"]],"solution":"Sie **hätte** aber gern eine grosse Wohnung.","en":"不过她很想有一套大公寓。","why":"*eine Wohnung haben*：*haben* 的愿望形式是 **hätte**。这里不需要不定式。","source":"k2"}]},{"no":"2","tag":"A1","instruction":"Was denken die Personen?","instruction_en":"这些人在想什么？","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"把每张图片和方框里的一个短语配对。","box":["wäre ich pünktlich im Büro","würde ich jetzt im Garten sitzen","müsste ich nicht bei Regen Velo fahren"],"box_exact":true,"items":[{"label":"1","lead":"Immer muss ich arbeiten!","text":"Wenn ich nicht arbeiten müsste, ___.","gaps":[["würde ich jetzt im Garten sitzen"]],"solution":"Wenn ich nicht arbeiten müsste, **würde ich jetzt im Garten sitzen**.","en":"如果我不用工作，我现在就会坐在花园里。","why":"图 1 中他在工作，然后在躺椅上做梦。*wenn* 从句之后，主句以动词（*würde*）开头。","source":"kond"},{"label":"2","lead":"Warum habe ich kein Auto?","text":"Wenn ich ein Auto hätte, ___.","gaps":[["müsste ich nicht bei Regen Velo fahren"]],"solution":"Wenn ich ein Auto hätte, **müsste ich nicht bei Regen Velo fahren**.","en":"如果我有一辆车，我就不用冒雨骑自行车了。","why":"他在雨中骑车，有车就不用这样了。*müsste* 是 *müssen* 的第二虚拟式。*Velo* 是瑞士用语，即 *Fahrrad*（自行车）。","source":"kond"},{"label":"3","lead":"Der Bus hat schon wieder Verspätung!","text":"Wenn der Bus keine Verspätung hätte, ___.","gaps":[["wäre ich pünktlich im Büro"]],"solution":"Wenn der Bus keine Verspätung hätte, **wäre ich pünktlich im Büro**.","en":"如果公交车不晚点，我就能准时到办公室。","why":"公交车晚点，害她上班迟到。*wäre* 是 *sein* 的第二虚拟式。","source":"kond"}]},{"no":"2","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"改写 a 中的句子：先写主句，再写 wenn 从句。","example":[{"label":"1","text":"Ich würde **jetzt im Garten sitzen, wenn ich nicht arbeiten müsste.**"}],"items":[{"label":"2","text":"Ich müsste ___.","gaps":[["nicht bei Regen Velo fahren, wenn ich ein Auto hätte","bei Regen nicht Velo fahren, wenn ich ein Auto hätte"]],"solution":"Ich müsste **nicht bei Regen Velo fahren, wenn ich ein Auto hätte.**","en":"如果我有一辆车，我就不用冒雨骑自行车了。","why":"先写主句，再写 *wenn* 从句。在 *wenn* 从句中，动词（*hätte*）放在句末。","source":"wenn"},{"label":"3","text":"Ich wäre ___.","gaps":[["pünktlich im Büro, wenn der Bus keine Verspätung hätte"]],"solution":"Ich wäre **pünktlich im Büro, wenn der Bus keine Verspätung hätte.**","en":"如果公交车不晚点，我就能准时到办公室。","why":"同样的结构：主句，逗号，*wenn* …… 动词放在句末（*hätte*）。","source":"wenn"}]},{"no":"3","tag":"A1","instruction":"Ordnen Sie zu.","instruction_en":"用方框里的词填空。每个词只用一次；划掉的词已用在例句中。","box":["könnte","wäre","hätten","würde","könnte","würde","wäre","würde","würde","müsste"],"box_used":[0,3],"box_exact":true,"example":[{"label":"a","text":"Ich **könnte** viel leichter eine Arbeit finden, wenn ich in der Stadt leben **würde**."}],"items":[{"label":"b","text":"Ich ___ einige Dinge anders machen, wenn ich Chefin in unserer Firma ___.","gaps":[["würde","müsste"],["wäre"]],"solution":"Ich **würde** einige Dinge anders machen, wenn ich Chefin in unserer Firma **wäre**.","en":"如果我是我们公司的老板，有些事情我会换个做法。","why":"句末是 *machen* → **würde** + 不定式。*Chefin sein* → **wäre**，放在 *wenn* 从句的末尾。","source":"k2"},{"label":"c","text":"Wenn ich Marco ___, ___ ich unbedingt eine Ausbildung machen.","gaps":[["wäre"],["würde","müsste"]],"solution":"Wenn ich Marco **wäre**, **würde** ich unbedingt eine Ausbildung machen.","en":"如果我是马可，我一定会去接受职业培训。","why":"*Marco sein* → **wäre**（就像 *Wenn ich du wäre …*）。主句有不定式 *machen* → **würde**。","source":"k2"},{"label":"d","text":"Wenn ich frei entscheiden ___, ___ ich in einer kleinen Firma arbeiten.","gaps":[["könnte"],["würde"]],"solution":"Wenn ich frei entscheiden **könnte**, **würde** ich in einer kleinen Firma arbeiten.","en":"如果我能自由选择，我会在一家小公司工作。","why":"*frei entscheiden können* → **könnte**，放在 *wenn* 从句的末尾。主句有 *arbeiten* → **würde**。","source":"k2"},{"label":"e","text":"Wenn wir Kinder ___, ___ ich nur halbtags arbeiten.","gaps":[["hätten"],["müsste","würde"]],"solution":"Wenn wir Kinder **hätten**, **müsste** ich nur halbtags arbeiten.","en":"如果我们有孩子，我就只需要工作半天。","why":"*Kinder haben* 配 *wir* → **hätten**。方框里剩下的 **müsste** 用在最后一个空。","source":"k2","check":"在 b、c 和 e 中，*müsste* 和 *würde* 都是正确的德语（*Wenn wir Kinder hätten, würde ich nur halbtags arbeiten* 也同样正确）。方框只规定了哪三个空用 *würde*、哪一个空用 *müsste*；这份答案是最可能的分配方式。问问老师课本要的是哪一种。"}]}]},{"page":"AB 132","heading":"B  Ich muss mich beeilen wegen meiner Arbeit.","heading_en":"因为工作，我得抓紧时间。","exercises":[{"no":"9","tag":"B1","instruction":"Schreiben Sie die Antworten neu mit *weil*.","instruction_en":"用 weil 改写答句。","example":[{"label":"a","lead":"◆ Warum freust du dich denn so? ○ Wegen meiner guten Note in der Prüfung.","text":"Weil ich eine gute Note in der Prüfung habe."}],"items":[{"label":"b","lead":"◆ Warum ärgerst du dich denn so? ○ Wegen meiner unpünktlichen Freundin.","text":"Weil meine ___.","gaps":[["Freundin unpünktlich ist","Freundin immer unpünktlich ist","Freundin so unpünktlich ist","Freundin zu spät kommt","Freundin immer zu spät kommt"]],"solution":"Weil meine **Freundin unpünktlich ist.**","en":"因为我女朋友不守时。","why":"*wegen* + 名词变成 *weil* + 带动词的从句；动词（*ist*）放在句末。","source":"weil"},{"label":"c","lead":"◆ Warum geht ihr am Samstag nicht wandern? ○ Wegen des schlechten Wetters.","text":"","accept":["Weil das Wetter schlecht ist.","Weil das Wetter so schlecht ist."],"solution":"**Weil das Wetter schlecht ist.**","en":"因为天气不好。","why":"*des schlechten Wetters* → *das Wetter ist schlecht*；*weil* 之后动词放在句末。","source":"weil"},{"label":"d","lead":"◆ Warum bist du denn so nervös? ○ Wegen eines wichtigen Termins.","text":"","accept":["Weil ich einen wichtigen Termin habe.","Weil ich einen wichtigen Termin hab."],"solution":"**Weil ich einen wichtigen Termin habe.**","en":"因为我有一个重要的约会。","why":"*eines wichtigen Termins* → *ich habe einen wichtigen Termin*（*haben* 之后用第四格）；动词放在句末。","source":"weil"}]},{"no":"10","tag":"B2","instruction":"Ergänzen Sie: *wegen – weshalb – weil – deswegen – denn*.","instruction_en":"填空：wegen – weshalb – weil – deswegen – denn。一个词可以用多次。","box":["wegen","weshalb","weil","deswegen","denn"],"example":[{"label":"a","text":"Ich beginne bald eine Lehre als Hotelfachfrau. **Deswegen** lerne ich in den Ferien Deutsch."}],"items":[{"label":"b","text":"Ich verstehe ihn ___ seiner Aussprache nur schlecht.","gaps":[["wegen"]],"solution":"Ich verstehe ihn **wegen** seiner Aussprache nur schlecht.","en":"因为他的发音，我很难听懂他的话。","why":"后面跟的是名词（*seiner Aussprache*，第二格），不是从句 → 用介词 **wegen**。","source":"wegen"},{"label":"c","text":"Irgendwann möchte ich gern nach Italien reisen, ___ ich möchte gern das Meer sehen.","gaps":[["denn"]],"solution":"Irgendwann möchte ich gern nach Italien reisen, **denn** ich möchte gern das Meer sehen.","en":"总有一天我想去意大利旅行，因为我想看看大海。","why":"空格后的动词仍在第二位（*ich möchte*）→ **denn**。如果用 *weil*，动词要放到句末。","source":"denn"},{"label":"d","text":"Ich muss mein Hörverstehen verbessern, ___ schaue ich viele Filme an.","gaps":[["deswegen","deshalb"]],"solution":"Ich muss mein Hörverstehen verbessern, **deswegen** schaue ich viele Filme an.","en":"我得提高听力，所以我看很多电影。","why":"第二部分是结果，而且动词紧跟在空格后面（*schaue ich*）→ **deswegen**。","source":"deswegen"},{"label":"e","text":"Meine Kinder haben schnell Deutsch gelernt, ___ sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","gaps":[["weil"]],"solution":"Meine Kinder haben schnell Deutsch gelernt, **weil** sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","en":"我的孩子们德语学得很快，因为他们在幼儿园里总是和瑞士孩子在一起。","why":"动词在句末（*zusammen sind*）→ **weil**。","source":"weil"},{"label":"f","text":"___ schreibst du die Wörter auf Kärtchen?","gaps":[["Weshalb"]],"solution":"**Weshalb** schreibst du die Wörter auf Kärtchen?","en":"你为什么把单词写在小卡片上？","why":"这里需要一个疑问词：**Weshalb** 的意思是 *warum*（为什么）。"},{"label":"g","text":"Meine Schwester spricht schon fast fliessend Deutsch, ___ kann sie mir beim Deutschlernen helfen.","gaps":[["deswegen","deshalb"]],"solution":"Meine Schwester spricht schon fast fliessend Deutsch, **deswegen** kann sie mir beim Deutschlernen helfen.","en":"我姐姐的德语已经说得几乎很流利了，所以她可以帮我学德语。","why":"表示结果，而且动词紧跟在空格后面（*kann sie*）→ **deswegen**。","source":"deswegen"}]},{"no":"11","marker":"◇","tag":"B2","instruction":"Im Sprachkurs. Ergänzen Sie: *weil – wegen – deswegen*.","instruction_en":"在语言班上。填空：weil – wegen – deswegen。","box":["weil","wegen","deswegen"],"example":[{"label":"a","text":"Ich möchte einen Sprachkurs machen, **deswegen** bin ich jetzt hier."}],"items":[{"label":"b","text":"Die letzte Übung konnte ich nicht machen, ___ ich sie nicht verstanden habe.","gaps":[["weil"]],"solution":"Die letzte Übung konnte ich nicht machen, **weil** ich sie nicht verstanden habe.","en":"最后一道练习我没法做，因为我没看懂。","why":"动词在句末（*verstanden habe*）→ **weil**。","source":"weil"},{"label":"c","text":"Bei der Anmeldung war niemand da. ___ bin ich wieder nach Hause gegangen.","gaps":[["Deswegen","Deshalb"]],"solution":"Bei der Anmeldung war niemand da. **Deswegen** bin ich wieder nach Hause gegangen.","en":"报名处一个人也没有，所以我又回家了。","why":"这是一个说明结果的新句子，动词紧跟在空格后面（*bin ich*）→ **Deswegen**。","source":"deswegen"},{"label":"d","text":"Ich musste ___ meiner guten Noten zum Kursbeginn keinen Test machen.","gaps":[["wegen"]],"solution":"Ich musste **wegen** meiner guten Noten zum Kursbeginn keinen Test machen.","en":"因为我成绩好，开课时我不用参加测试。","why":"后面跟的是名词短语（*meiner guten Noten*，复数第二格）→ **wegen**。","source":"wegen"},{"label":"e","text":"Es gibt einen extra Sprachkurs, ___ sich sehr viele Teilnehmer angemeldet haben.","gaps":[["weil"]],"solution":"Es gibt einen extra Sprachkurs, **weil** sich sehr viele Teilnehmer angemeldet haben.","en":"因为报名的人很多，所以加开了一个语言班。","why":"动词在句末（*angemeldet haben*）→ **weil**。","source":"weil"},{"label":"f","text":"Ich konnte gestern ___ meiner Zahnschmerzen leider nicht in den Kurs kommen.","gaps":[["wegen"]],"solution":"Ich konnte gestern **wegen** meiner Zahnschmerzen leider nicht in den Kurs kommen.","en":"很遗憾，我昨天因为牙疼没能来上课。","why":"后面跟的是名词短语（*meiner Zahnschmerzen*，复数第二格）→ **wegen**。","source":"wegen"}]},{"no":"12","marker":"◆","tag":"B2","instruction":"Wer findet die besten Ausreden? Wählen Sie eine Situation und schreiben Sie.","instruction_en":"谁能找到最好的借口？选一个情境来写。参考答案只是其中一种可能。","phrases":["Ich habe/bin … Deswegen …","Leider habe/bin ich …, weil/denn …","Wegen …"],"example":[{"label":"a","text":"Leider konnte ich die Küche nicht aufräumen, …"}],"items":[{"label":"a","lead":"Ihre Frau hat Sie gebeten, die Küche aufzuräumen. Sie haben aber lieber einen Film angeschaut.","text":"","open":true,"solution":"Leider konnte ich die Küche nicht aufräumen, **weil** ich plötzlich starke Rückenschmerzen hatte. Ich musste mich hinlegen. **Deswegen** habe ich einen Film angeschaut.","en":"很遗憾，我没能收拾厨房，因为我突然腰背疼得厉害，只好躺下。所以我看了一部电影。","why":"用了 *weil*（动词在句末：*hatte*）和 *Deswegen*（动词紧跟其后：*habe ich*）。","source":"weil"},{"label":"b","lead":"Sie sind nicht an die Abschlussprüfung von Ihrem Sprachkurs gegangen.","text":"","open":true,"solution":"**Wegen** einer Grippe bin ich nicht an die Abschlussprüfung gegangen. Ich hatte hohes Fieber, **deswegen** bin ich im Bett geblieben.","en":"因为得了流感，我没去参加结业考试。我发高烧，所以一直躺在床上。","why":"用了 *wegen* + 第二格（*einer Grippe*）和 *deswegen* + 动词（*bin ich*）。","source":"wegen"},{"label":"c","lead":"Sie kommen zum Essen am 80. Geburtstag Ihrer Grossmutter zwei Stunden zu spät.","text":"","open":true,"solution":"Es tut mir so leid! Leider bin ich zu spät gekommen, **denn** auf der Autobahn war ein Unfall. **Wegen** des Staus habe ich zwei Stunden verloren.","en":"真是太抱歉了！很遗憾我来晚了，因为高速公路上出了车祸。因为堵车，我耽误了两个小时。","why":"*denn* 让动词保持在第二位（*war*）。*wegen des Staus*：*der Stau* 的第二格。","source":"denn"}]}]}],"sources":[{"id":"k2","title":"grammis：Konjunktiv II（第二虚拟式）","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis：Konditionalgefüge（条件句，包括用第二虚拟式表示的非真实条件句）","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"wenn","title":"grammis 连词词典：wenn（引导从句，动词放在句末）","url":"https://grammis.ids-mannheim.de/konnektoren/407100"},{"id":"weil","title":"grammis 连词词典：weil（引导从句，动词放在句末）","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"grammis 连词词典：denn（表示原因，动词保持在第二位）","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"grammis 连词词典：deswegen（表示结果；位于动词前或句中）","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wegen","title":"grammis：Wegen dem Regen oder wegen des Regens?（wegen 加第二格）","url":"https://grammis.ids-mannheim.de/fragen/67"}]},{"id":"02-mehrere-sprachen","no":2,"title":"In mehreren Sprachen zu Hause","title_en":"在多种语言中长大 · 阅读、论坛帖子、填字游戏、最喜欢的词","added":"2026-11-09","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 135","heading":"E  In mehreren Sprachen zu Hause","heading_en":"在多种语言中安家","exercises":[{"no":"17","tag":"E2","instruction":"Zwei oder drei Sprachen in einer Familie – kein Problem?","instruction_en":"一个家庭里说两三种语言——没问题吗？","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ergänzen Sie die Namen.","part_instruction_en":"谁说了什么？阅读三篇短文，写出说每句话的人的名字。","reading":[{"label":"A · Amira, 33","text":"Ich denke, das ist manchmal schwierig, aber es geht. Bei uns ist das so: Ich bin Ägypterin und mein Deutsch ist noch nicht so gut, weil ich erst seit zwei Jahren in der Schweiz lebe. Mein Mann ist Schweizer. Wir haben uns in Ägypten kennengelernt, weil er dort sechs Jahre für eine Schweizer Firma gearbeitet hat. Jetzt leben wir seit fast zwei Jahren in Basel. Unsere Kinder sprechen sehr gut Arabisch und jetzt auch schon ziemlich gut Schweizerdeutsch. Mein Mann hat zwar in Ägypten mit ihnen Schweizerdeutsch gesprochen, aber er war ja nicht so viel zu Hause und in der Familie haben wir immer Arabisch gesprochen. Darum können das die Kinder viel besser. Manchmal verwenden sie auch zwei Sprachen in einem Satz. Wenn sie ein Wort nicht auf Schweizerdeutsch wissen, dann sagen sie einfach ein arabisches mitten im deutschen Satz. Aber ich finde das okay. Bald kommen sie in die Schule und dann werden sie sowieso besser Schweizerdeutsch als Arabisch sprechen."},{"label":"B · Janusz, 22","text":"Ich bin Pole, und als ich sechs Jahre alt war, sind wir in die Schweiz umgezogen. Meine Schwester und ich sind natürlich gleich in eine öffentliche Schule gegangen und konnten nach einem Jahr fliessend Hochdeutsch sprechen. Für meine Eltern war es schwieriger, denn meine Mutter war Hausfrau und hatte nicht so viel Kontakt zu Schweizern. Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet. Wir wollten nicht, dass unsere Eltern oder unsere Grossmutter mit uns Polnisch sprechen, wenn andere Kinder zu Besuch waren oder sie uns von der Schule abgeholt haben. Ich glaube, alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen. Natürlich ist mein Polnisch nicht so gut wie mein Deutsch, aber ich verstehe alles und kann auch ziemlich gut Alltagsgespräche führen. Das ist genug für mich und ich freue mich, dass ich mich mit unseren polnischen Verwandten unterhalten kann. Ich finde, man sollte daraus nicht so ein Problem machen."},{"label":"C · Yara, 18","text":"Ich komme aus Syrien. Ich bin mit drei Sprachen aufgewachsen, denn mein Vater hat für eine internationale Firma gearbeitet und wir haben auch einige Jahre in der Türkei und in Russland gelebt. Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch. Allerdings kann ich Arabisch am besten, weil wir in der Familie immer Arabisch gesprochen haben, egal in welchem Land wir waren. Jetzt leben wir in in der Schweiz und ich lerne seit zwei Jahren Deutsch. Das kann ich noch nicht so gut. Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf. Ich möchte Übersetzerin werden und so muss ich die Sprachen nicht mehr lernen. Das ist doch super, oder?"}],"items":[{"label":"1","text":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: ___","gaps":[["Janusz"]],"solution":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: **Janusz**","en":"“孩子们想和朋友说同一种语言。”——Janusz","why":"Janusz（短文 B）：*alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen.*"},{"label":"2","text":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: ___","gaps":[["Yara"]],"solution":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: **Yara**","en":"“能把好几种语言都说得很好，这是好事，不是吗？”——Yara","why":"Yara（短文 C）：*Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf.*"},{"label":"3","text":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: ___","gaps":[["Amira"]],"solution":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: **Amira**","en":"“我的孩子们在两种语言之间切换。”——Amira","why":"Amira（短文 A）：*Manchmal verwenden sie auch zwei Sprachen in einem Satz.* 她是唯一谈到自己孩子的人。"}]},{"no":"17","part":"b","part_instruction":"Was ist richtig? Lesen Sie noch einmal und kreuzen Sie an.","part_instruction_en":"哪些是对的？再读一遍短文。在每个句子后面输入 *richtig*（对）或 *falsch*（错）；在课本里你只需勾出正确的句子。","items":[{"label":"1","text":"Amiras Kinder sprechen besser Arabisch als Deutsch. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Amiras Kinder sprechen besser Arabisch als Deutsch. → **richtig**","en":"Amira 的孩子们阿拉伯语说得比德语好。→ 对","why":"这家人在家里一直说阿拉伯语：*Darum können das die Kinder viel besser.*（这里说的德语指的是瑞士德语。）"},{"label":"2","text":"In Amiras Familie wird nur Deutsch gesprochen. → ___","gaps":[["falsch","f","nein"]],"solution":"In Amiras Familie wird nur Deutsch gesprochen. → **falsch**","en":"Amira 家里只说德语。→ 错","why":"正好相反：*in der Familie haben wir immer Arabisch gesprochen.*"},{"label":"3","text":"Janusz hat sechs Jahre Deutsch gelernt. → ___","gaps":[["falsch","f","nein"]],"solution":"Janusz hat sechs Jahre Deutsch gelernt. → **falsch**","en":"Janusz 学了六年德语。→ 错","why":"全家搬家时他六岁（*als ich sechs Jahre alt war*），一年后他就能说流利的标准德语了。"},{"label":"4","text":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → **richtig**","en":"Janusz 和他姐姐不想和父母说波兰语。→ 对","why":"*Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet.*"},{"label":"5","text":"Yara spricht drei Sprachen fliessend. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Yara spricht drei Sprachen fliessend. → **richtig**","en":"Yara 能流利地说三种语言。→ 对","why":"*Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch.* 德语是她的第四种语言，她现在还说得不好。"},{"label":"6","text":"Yara lernt jetzt bald auch Deutsch. → ___","gaps":[["falsch","f","nein"]],"solution":"Yara lernt jetzt bald auch Deutsch. → **falsch**","en":"Yara 很快也要开始学德语了。→ 错","why":"她不是很快（*bald*）才开始学：她已经学了两年德语了（*ich lerne seit zwei Jahren Deutsch*）。"}]}]},{"page":"AB 136","heading":"E  In mehreren Sprachen zu Hause","heading_en":"在多种语言中安家","exercises":[{"no":"18","tag":"E2 · Prüfung","instruction":"Einen Forumsbeitrag schreiben. Sie haben im Fernsehen eine Diskussionssendung zum Thema «Mehrsprachig aufwachsen» gesehen. Im Online-Forum der Sendung finden Sie folgende Meinung:","instruction_en":"写一篇论坛帖子。你看了一场关于在多种语言中长大的电视辩论。在节目的网上论坛里，你看到了这样一个观点：","reading":[{"label":"Online-Forum · 15.01. 16.55 Uhr · Sandra (52 Jahre)","text":"Also, ich kann den Gästen in Ihrer Sendung überhaupt nicht zustimmen. Ich finde, dass Kinder zuerst einmal eine Sprache richtig lernen sollen. Denn sonst können sie am Ende gar keine Sprache gut. Sie sprechen dann zwar zwei oder drei Sprachen ein bisschen, mischen sie aber und sprechen keine Sprache fliessend und auch keine wirklich gut."}],"part":"a","part_instruction":"Machen Sie Notizen.","part_instruction_en":"就四个问题做笔记。简短的笔记就够了，不用写完整的句子。参考笔记只是一种可能。","items":[{"label":"1","lead":"Kennen Sie eine Person, die mit zwei Sprachen aufwächst/aufgewachsen ist?","text":"","open":true,"solution":"Ja: der Sohn von meiner Nachbarin – Italienisch mit der Mutter, Schweizerdeutsch in der Schule","en":"是的：我女邻居的儿子——和妈妈说意大利语，在学校说瑞士德语","why":"只写笔记：一个名字或一个人，以及在哪里说哪种语言。"},{"label":"2","lead":"Was finden Sie gut?","text":"","open":true,"solution":"zwei Sprachen ohne Kurs lernen, Kontakt mit der Familie im Ausland, Vorteile im Beruf","en":"不上课就能学会两种语言、和国外的家人保持联系、工作上有优势","why":"收集两三个优点；在 b 中写 *Ich finde es sehr gut, dass …* 时要用到。"},{"label":"3","lead":"Was könnte schwierig sein?","text":"","open":true,"solution":"die Sprachen mischen, eine Sprache ist schwächer, viel Arbeit für die Eltern","en":"把语言混在一起、有一种语言比较弱、父母要花很多精力","why":"这些内容用在 b 中的 *Es könnte schwierig sein, dass …* 和 *Auf der anderen Seite …*。"},{"label":"4","lead":"Stimmen Sie Sandra zu?","text":"","open":true,"solution":"nein – Kinder lernen zwei Sprachen gut, wenn die Eltern viel mit ihnen sprechen","en":"不——如果父母经常和孩子说话，孩子能把两种语言都学好","why":"决定是或否，并给出一个理由：这就成了 *Ich stimme Sandra (nicht) zu, denn …*。"}]},{"no":"18","part":"b","part_instruction":"Schreiben Sie nun Ihre Meinung zum Thema (circa 80 Wörter).","part_instruction_en":"现在就这个话题写出你的看法（大约 80 个词）。使用 a 中的笔记和一些短语。","phrases":["Ich denke, dass …","Ich finde es sehr gut/wichtig, dass …","Am allerwichtigsten ist … Deswegen/Daher/Aus diesem Grund …","Es könnte schwierig sein, dass …","Auf der anderen Seite …","Ich stimme Sandra (nicht) zu, denn …","**LERNTIPP** Sie brauchen diese Sätze, wenn Sie Ihre Meinung ausdrücken wollen. Wiederholen Sie sie möglichst oft."],"items":[{"label":"b","text":"","open":true,"solution":"Ich stimme Sandra nicht zu, **denn** viele Kinder lernen zwei Sprachen ohne Probleme. Der Sohn von meiner Nachbarin wächst mit Italienisch und Deutsch auf. Mit seiner Mutter spricht er Italienisch, in der Schule Schweizerdeutsch. Ich finde es sehr gut, dass er so früh zwei Sprachen lernt. Es könnte schwierig sein, dass er die Sprachen manchmal mischt. Auf der anderen Seite ist das bei kleinen Kindern normal. Am allerwichtigsten ist, dass die Eltern viel mit dem Kind sprechen. **Deswegen** sollte jeder Elternteil seine eigene Sprache sprechen.","en":"我不同意 Sandra 的看法，因为很多孩子学两种语言都没有问题。我女邻居的儿子在意大利语和德语的环境中长大。他和妈妈说意大利语，在学校说瑞士德语。我觉得他这么早就学两种语言非常好。他有时会把语言混在一起，这可能是个难题。但另一方面，这对小孩子来说很正常。最重要的是父母要经常和孩子说话。所以父母双方都应该说自己的语言。","why":"大约 85 个词，用到了其中六个短语。*denn* 让动词保持在第二位（*lernen*）；*Deswegen* 之后紧跟动词（*sollte*）。","source":"deswegen"}]},{"no":"19","tag":"E3","instruction":"Lösen Sie das Rätsel.","instruction_en":"完成填字游戏。每个句子给出了所缺单词的首字母。这里没有显示格子：请输入完整的单词。在课本的格子里，Ä 占一格。","items":[{"label":"a","lead":"Unser Heimatland ist Spanien. Wir s… aus Spanien.","text":"___","gaps":[["stammen"]],"solution":"**stammen**","en":"我们的故乡是西班牙。我们来自西班牙。","why":"*aus einem Land stammen* = 来自某个国家（类似 *kommen aus*）。"},{"label":"b","lead":"Jolanda und Mike sehen sich sechs Monate nicht. Das ist eine lange T… .","text":"___","gaps":[["Trennung"]],"solution":"**Trennung**","en":"Jolanda 和 Mike 有六个月见不到面。这是一次长时间的分离。","why":"*die Trennung* = 分离，是 *sich trennen* 的名词形式。*eine lange* → 阴性名词。"},{"label":"c","lead":"Deutsch und Arabisch haben nicht die gleiche S… .","text":"___","gaps":[["Schrift"]],"solution":"**Schrift**","en":"德语和阿拉伯语用的不是同一种文字。","why":"*die Schrift* = 文字，即一种语言书写时用的字母。阿拉伯语用的是另一套字母。"},{"label":"d","lead":"Peter lebt jetzt in Amerika. Seit er dort lebt, hat er sich stark v… .","text":"___","gaps":[["verändert"]],"solution":"**verändert**","en":"Peter 现在住在美国。自从他住在那里，他变了很多。","why":"*sich verändern* = （人）发生变化。现在完成时：*hat sich verändert*。Ä 占一格。"},{"label":"e","lead":"Sie schreibt Bücher. Sie ist A… von Beruf.","text":"___","gaps":[["Autorin"]],"solution":"**Autorin**","en":"她写书。她的职业是作家。","why":"*Sie* → 加 *-in* 的阴性形式：*der Autor → die Autorin*。*sein … von Beruf* 之后不加冠词。"},{"label":"f","lead":"Die Kinder machen ihre Hausaufgaben nicht. Deshalb s… die Eltern mit ihnen.","text":"___","gaps":[["schimpfen"]],"solution":"**schimpfen**","en":"孩子们不做作业。所以父母骂他们。","why":"*mit jemandem schimpfen* = 责骂某人。复数主语 *die Eltern* → *schimpfen*。*Deshalb* 之后紧跟动词。"},{"label":"g","lead":"Sie arbeitet erst seit wenigen Monaten. Sie hat noch wenig E… in ihrem Beruf.","text":"___","gaps":[["Erfahrung"]],"solution":"**Erfahrung**","en":"她才工作了几个月。她在工作上的经验还很少。","why":"*die Erfahrung* = 经验。*wenig Erfahrung haben* = 经验很少。"},{"label":"h","lead":"Jetzt haben wir ein Chaos. Alles ist d… .","text":"___","gaps":[["durcheinander"]],"solution":"**durcheinander**","en":"现在一团糟。所有东西都乱七八糟的。","why":"*durcheinander sein* = 乱七八糟、混乱。写成一个词。"},{"label":"i","lead":"Für Ye-Jon tönen die Laute P und F gleich. Sie kann sie nicht u… .","text":"___","gaps":[["unterscheiden"]],"solution":"**unterscheiden**","en":"对 Ye-Jon 来说，P 和 F 这两个音听起来一样。她分辨不出来。","why":"*unterscheiden* = 分辨、区分。和 *kann* 连用时，不定式放在句末。*tönen* 是瑞士用语，即 *klingen*（听起来）。"},{"label":"j","lead":"Ich reise in den Ferien nach Griechenland, aber leider kann ich kein G… .","text":"___","gaps":[["Griechisch"]],"solution":"**Griechisch**","en":"假期我要去希腊旅行，可惜我一点希腊语也不会说。","why":"*Griechisch* = 希腊语，首字母大写。*kein Griechisch können* = 一点希腊语也不会。"},{"label":"k","lead":"Er isst nur Gemüse und Reis. Er isst a… Gemüse und Reis.","text":"___","gaps":[["ausschliesslich"]],"solution":"**ausschliesslich**","en":"他只吃蔬菜和米饭。他只吃蔬菜和米饭，别的都不吃。","why":"*ausschliesslich* = 仅仅、完全只是。瑞士写法用 *ss*；德国用 sharp s（尖 s）书写。"},{"label":"★","lead":"Lösungswort (die markierte Zeile im Rätsel)","text":"___","gaps":[["Muttersprache"]],"solution":"**Muttersprache**","en":"答案词（格子里突出显示的那一行）：母语","why":"每个词给出突出显示那一行中的一个字母：stam**M**en、trenn**U**ng、schrif**T**、（格子里已有 T）、veränd**E**rt、auto**R**in、（格子里已有 S）、schim**P**fen、erfah**R**ung、durchein**A**nder、unters**C**heiden、griec**H**isch、ausschli**E**sslich。"}]}]},{"page":"AB 137","heading":"E  In mehreren Sprachen zu Hause","heading_en":"在多种语言中安家","exercises":[{"no":"20","tag":"E3","instruction":"Mein schönstes deutsches Wort","instruction_en":"我最美的德语单词","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"把每张照片和方框里的一个词配对。课本里的彩色圆点表示冠词：蓝色 = der，绿色 = das，红色 = die。","box":["Sommervogel","Caramelchöpfli","Sternschnuppe"],"box_exact":true,"items":[{"label":"1","lead":"(Foto 1: ein Dessert mit Karamellsauce auf einem Teller)","text":"___","gaps":[["Caramelchöpfli","das Caramelchöpfli"]],"solution":"**Caramelchöpfli**","en":"das Caramelchöpfli – 焦糖布丁（一种焦糖蛋奶甜点）","why":"焦糖布丁的瑞士叫法。*Chöpfli* 是瑞士德语，意思是“小脑袋”（*Kopf*）。绿色圆点 → *das*。"},{"label":"2","lead":"(Foto 2: ein Stern mit einem langen, hellen Schweif am Nachthimmel)","text":"___","gaps":[["Sternschnuppe","die Sternschnuppe"]],"solution":"**Sternschnuppe**","en":"die Sternschnuppe – 流星","why":"*der Stern* = 星星；*die Sternschnuppe* = 流星。红色圆点 → *die*。"},{"label":"3","lead":"(Foto 3: ein blauer Schmetterling auf einer orangen Blume)","text":"___","gaps":[["Sommervogel","der Sommervogel"]],"solution":"**Sommervogel**","en":"der Sommervogel – 蝴蝶","why":"*der Schmetterling*（蝴蝶）的瑞士说法；Duden 标注为 *schweizerisch, sonst landschaftlich*。蓝色圆点 → *der*。","source":"sommervogel"}]},{"no":"20","part":"b","part_instruction":"Warum findet wohl jemand genau diese Wörter am schönsten? Was meinen Sie? Machen Sie Notizen und sprechen Sie.","part_instruction_en":"为什么有人会觉得恰恰是这些词最美？你怎么看？先做笔记，然后说一说。参考笔记只是一种可能。","example":[{"text":"Sommervogel: so farbig, …"}],"items":[{"label":"1","lead":"Sommervogel","text":"","open":true,"solution":"so farbig und leicht, erinnert an den Sommer, lustig: das Tier ist ja kein Vogel","en":"色彩丰富又轻盈，让人想起夏天，很有趣：这种动物其实根本不是鸟","why":"想一想这个词让你看到或感受到什么，以及它听起来怎么样。"},{"label":"2","lead":"Caramelchöpfli","text":"","open":true,"solution":"süss, erinnert an die Kindheit, tönt lustig und typisch schweizerisch","en":"甜甜的，让人想起童年，听起来很有趣，而且很有瑞士特色","why":"*tönen* = 瑞士用语，即 *klingen*（听起来）。"},{"label":"3","lead":"Sternschnuppe","text":"","open":true,"solution":"romantisch, man kann sich etwas wünschen, tönt weich","en":"浪漫，可以许个愿，听起来很柔和","why":"简短的笔记就够了：几个形容词加一个理由。"}]},{"no":"21","tag":"E3","instruction":"Mein Lieblingswort","instruction_en":"我最喜欢的词","part":"a","part_instruction":"Welches deutsche Wort und welches Wort in Ihrer Muttersprache gefallen Ihnen? Warum? Schreiben Sie.","part_instruction_en":"你喜欢哪个德语单词，又喜欢你母语里的哪个词？为什么？用这些短语写一篇短文。参考答案只是一种可能。","phrases":["Wenn ich … höre, dann denke ich an …","Deshalb finde ich …","Dieses Wort ist …","Das tönt …","Für mich ist …","Auf Deutsch/In meiner Muttersprache …"],"example":[{"text":"Wenn ich das Wort «Sommervogel» höre, dann denke ich an …"}],"items":[{"label":"a","text":"","open":true,"solution":"Mein deutsches Lieblingswort ist «gemütlich». **Wenn** ich dieses Wort höre, **dann** denke ich an einen Winterabend mit Tee, Kerzen und Freunden. **Deshalb** finde ich es so schön. Das tönt weich und warm. In meiner Muttersprache Englisch gibt es kein Wort mit genau dieser Bedeutung. Auf Englisch gefällt mir das Wort «sunshine». Für mich ist es ein fröhliches Wort, denn es tönt hell und freundlich.","en":"我最喜欢的德语单词是 “gemütlich”（舒适、惬意）。听到这个词，我就会想到一个有茶、蜡烛和朋友相伴的冬夜。所以我觉得它特别美。它听起来柔和又温暖。在我的母语英语里，没有一个词的意思和它完全一样。在英语里，我喜欢 “sunshine”（阳光）这个词。对我来说，这是一个快乐的词，因为它听起来明亮又友好。","why":"*Wenn …, dann* + 紧跟动词（*denke ich*）；*Deshalb* + 紧跟动词（*finde ich*）。换成你自己的母语和词语。","source":"wenn"}]},{"no":"21","part":"b","part_instruction":"Präsentieren Sie Ihren Text im Kurs.","part_instruction_en":"在课堂上介绍你的短文。参考答案里给出了一种可能的开头。","items":[{"label":"b","text":"","open":true,"solution":"Ich möchte euch heute mein Lieblingswort vorstellen. Es ist das Wort «gemütlich». …","en":"今天我想向大家介绍我最喜欢的词。这个词是“gemütlich”。……","why":"先说出这个词，然后读你在 a 中写的短文。对同学用 *euch*，正式场合用 *Ihnen*。"}]}]}],"sources":[{"id":"sommervogel","title":"Duden：Sommervogel（schweizerisch, sonst landschaftlich = Schmetterling，蝴蝶）","url":"https://www.duden.de/rechtschreibung/Sommervogel"},{"id":"deswegen","title":"grammis 连词词典：deswegen（表示结果；位于动词前或句中）","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wenn","title":"grammis 连词词典：wenn（引导从句，动词放在句末）","url":"https://grammis.ids-mannheim.de/konnektoren/407100"}]},{"id":"03-nachfragen-test","no":3,"title":"Nachfragen · Fremdsprachen lernen · Test Lektion 4","title_en":"礼貌地追问、学习语言、找工作 – 第 4 课测试","added":"2026-11-10","book":"Schritte plus Neu 5 · Arbeitsbuch und Testheft · Lektion 4","sources":[{"id":"hueber","title":"Hueber：Schritte plus Neu 5 Schweiz, Lösungen Arbeitsbuch（官方答案，Lektion 4）","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Loesungen_AB.pdf"},{"id":"k2","title":"grammis：Konjunktiv II（第二虚拟式）","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis：Konditionalgefüge（条件句，包括用第二虚拟式表示的非真实条件句）","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"weil","title":"grammis 连词词典：weil（引导从句，动词放在句末）","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"grammis 连词词典：denn（表示原因，动词保持在第二位）","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"grammis 连词词典：deswegen（表示结果；位于动词前或句中）","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"deshalb","title":"grammis 连词词典：deshalb（表示结果；同义词 daher、deswegen）","url":"https://grammis.ids-mannheim.de/konnektoren/407094"},{"id":"darum","title":"grammis 连词词典：d(a)rum（表示结果）","url":"https://grammis.ids-mannheim.de/konnektoren/407096"},{"id":"wegen","title":"grammis：Wegen dem Regen oder wegen des Regens?（wegen 加第二格）","url":"https://grammis.ids-mannheim.de/fragen/67"}],"pages":[{"page":"AB 133","heading":"C  Entschuldigung, könnten Sie das bitte wiederholen?","heading_en":"对不起，您能再说一遍吗？","exercises":[{"no":"13","tag":"C2","instruction":"Ordnen Sie zu.","instruction_en":"用框里的开头补全每个问题或句子。每个开头只用一次；划掉的那个已用在例句中。","box":["Tut mir leid, das Wort habe ich","Könnten Sie bitte langsamer","Entschuldigung, habe ich das","Könnten Sie das bitte","Darf ich Sie schnell","Was bedeutet","Könnten Sie mir vielleicht sagen","Wissen Sie, ob"],"box_used":[4],"box_exact":true,"example":[{"label":"a","text":"**Darf ich Sie schnell** etwas fragen?"}],"items":[{"label":"b","text":"___ der Ausdruck «es eilig haben»?","gaps":[["Was bedeutet"]],"solution":"**Was bedeutet** der Ausdruck «es eilig haben»?","en":"«es eilig haben» 这个说法是什么意思？","why":"*Was bedeutet …?* 用来询问一个词或说法的意思。（*es eilig haben* = 赶时间。）","source":"hueber"},{"label":"c","text":"___ sprechen?","gaps":[["Könnten Sie bitte langsamer"]],"solution":"**Könnten Sie bitte langsamer** sprechen?","en":"您能说慢一点吗？","why":"*Könnten Sie …*（第二虚拟式）让请求显得礼貌；不定式 *sprechen* 放在句末。","source":"hueber"},{"label":"d","text":"___ nicht verstanden.","gaps":[["Tut mir leid, das Wort habe ich"]],"solution":"**Tut mir leid, das Wort habe ich** nicht verstanden.","en":"对不起，这个词我没听懂。","why":"现在完成时：*habe … verstanden*；*das Wort* 为了强调放在句首，所以动词 *habe* 紧跟在它后面。","source":"hueber"},{"label":"e","text":"Wie bitte? ___ wiederholen?","gaps":[["Könnten Sie das bitte"]],"solution":"Wie bitte? **Könnten Sie das bitte** wiederholen?","en":"您说什么？您能再重复一遍吗？","why":"用 *Könnten Sie …* 提出礼貌的请求；*wiederholen*（重复）放在句末。","source":"hueber"},{"label":"f","text":"___ es hier auch Integrationskurse gibt?","gaps":[["Wissen Sie, ob"]],"solution":"**Wissen Sie, ob** es hier auch Integrationskurse gibt?","en":"您知道这里是否也有融入课程吗？","why":"*ob* 引导间接的是非疑问句，所以动词 *gibt* 放在句末。","source":"hueber"},{"label":"g","text":"___ richtig verstanden?","gaps":[["Entschuldigung, habe ich das"]],"solution":"**Entschuldigung, habe ich das** richtig verstanden?","en":"不好意思，我理解得对吗？","why":"现在完成时的是非疑问句：*habe* 在句首，*verstanden* 在句末。","source":"hueber"},{"label":"h","text":"___, wo die Mensa ist?","gaps":[["Könnten Sie mir vielleicht sagen"]],"solution":"**Könnten Sie mir vielleicht sagen**, wo die Mensa ist?","en":"您能不能告诉我，大学食堂在哪里？","why":"由 *wo* 引导的间接疑问句：动词 *ist* 放在句末。*die Mensa* = 大学食堂。","source":"hueber"}]},{"no":"14","tag":"C2","instruction":"Ergänzen Sie.","instruction_en":"补全对话。书中已印出每个词的首字母（以及词中的几个字母）；请写出完整的缺失单词。","example":[{"label":"a","lead":"◆ Was ist denn das? ○ Das ist ein Zigerkrapfen. ◆ Entschuldigung, Zigerkrapfen kenne ich nicht.","text":"**Könnten Sie mir sagen**, was das ist?"}],"items":[{"label":"b","lead":"◆ Entschuldigen Sie bitte. Wo ist denn da die Mensa?  ○ Wie bitte? Das letzte Wort h… i… n… v… .  ◆ Die Mensa, die Uni-Kantine.","text":"Wie bitte? Das letzte Wort ___.","gaps":[["habe ich nicht verstanden"]],"solution":"Wie bitte? Das letzte Wort **habe ich nicht verstanden**.","en":"抱歉，您说什么？最后那个词我没听懂。","why":"现在完成时：*habe* 在 *Das letzte Wort* 之后的第二位，*verstanden* 在句末。","source":"hueber"},{"label":"c","lead":"◆ Also, dann treffen wir uns am 12.5. um 13.35 Uhr am Bahnhof.  ○ Entschuldigen Sie, es ist so laut da. K… S… den Termin b… w…?","text":"Entschuldigen Sie, es ist so laut da. ___ den Termin ___ ___?","gaps":[["Könnten Sie"],["bitte"],["wiederholen"]],"solution":"Entschuldigen Sie, es ist so laut da. **Könnten Sie** den Termin **bitte wiederholen**?","en":"不好意思，这里太吵了。您能再说一遍约定的时间吗？","why":"礼貌的请求：*Könnten Sie* … 不定式 *wiederholen* 在句末。*der Termin* 在这里 = 约定的时间。","source":"hueber"},{"label":"d","lead":"◆ D… i… S… etwas f…?  ○ Ja, gern.  ◆ W… S…, o… es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","text":"◆ ___ etwas ___? ○ Ja, gern. ◆ ___, ___ es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","gaps":[["Darf ich Sie"],["fragen"],["Wissen Sie"],["ob"]],"solution":"◆ **Darf ich Sie** etwas **fragen**? ○ Ja, gern. ◆ **Wissen Sie**, **ob** es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","en":"我可以问您一件事吗？——好的，请问。——您知道 14:33 开往日内瓦的那趟火车上是否也有小餐吧或餐厅吗？","why":"*Darf ich Sie etwas fragen?* 是礼貌的开场白；*ob* 引导间接的是非疑问句，所以 *gibt* 放在句末。","source":"hueber"}]},{"no":"15","tag":"C2","instruction":"Bilden Sie Wörter und ordnen Sie zu.","instruction_en":"用框里的音节组成单词，补全句子。划掉的音节（Men, sa）已用在例句中。","phrases":["schrei · druck · ni · lung · ker · der · auf · Aus · ben · ho · Me · Wie · cha  (durchgestrichen im Beispiel: Men, sa)"],"example":[{"label":"a","text":"Ich wähle in der **Mensa** immer ein vegetarisches Gericht."}],"items":[{"label":"b","text":"Mein Auto ist schon wieder kaputt. Könntest du mir bitte noch einmal die Telefonnummer von deinem guten ___ geben? Diesmal will ich sie mir gleich in meinem Adressbuch ___, damit ich sie nicht wieder verliere.","gaps":[["Mechaniker"],["aufschreiben"]],"solution":"Mein Auto ist schon wieder kaputt. Könntest du mir bitte noch einmal die Telefonnummer von deinem guten **Mechaniker** geben? Diesmal will ich sie mir gleich in meinem Adressbuch **aufschreiben**, damit ich sie nicht wieder verliere.","en":"我的车又坏了。你能再给我一次你那位好修车师傅的电话号码吗？这次我要马上把它记在我的通讯录里，免得又弄丢。","why":"Me-cha-ni-ker（修车的人）和 auf-schrei-ben（在 *will* 之后，不定式放在句末）。","source":"hueber"},{"label":"c","text":"Was bedeutet der ___ «eine Entscheidung treffen»? Den habe ich noch nie gehört.","gaps":[["Ausdruck"]],"solution":"Was bedeutet der **Ausdruck** «eine Entscheidung treffen»? Den habe ich noch nie gehört.","en":"«eine Entscheidung treffen» 这个说法是什么意思？我从来没听过。","why":"Aus-druck：*der Ausdruck* = 说法、表达；*der* 和 *Den* 表明它是阳性。（*eine Entscheidung treffen* = 做决定。）","source":"hueber"},{"label":"d","text":"Leider vergesse ich oft wichtige deutsche Wörter. Ich brauche mehr Zeit zur ___.","gaps":[["Wiederholung"]],"solution":"Leider vergesse ich oft wichtige deutsche Wörter. Ich brauche mehr Zeit zur **Wiederholung**.","en":"可惜我经常忘记重要的德语单词。我需要更多时间来复习。","why":"Wie-der-ho-lung：*zur* = *zu der*，所以后面接阴性名词：*die Wiederholung*（复习、重复）。","source":"hueber"}]}]},{"page":"AB 134","heading":"D  Fremdsprachen lernen – aber wie?","heading_en":"学外语——可是怎么学？","exercises":[{"no":"16","tag":"D1","instruction":"Fremdsprachen lernen – aber wie?","instruction_en":"学外语——可是怎么学？","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ordnen Sie zu.","part_instruction_en":"谁说了什么？阅读三篇短文，在每个句子后面写上相应短文的字母（A、B 或 C）。","reading":[{"label":"A  Mila, 17 Jahre","text":"Ich finde es total wichtig, dass man neue Wörter lernt und sie immer wieder wiederholt. Ich schreibe sie auf kleine Zettel oder Karten, auf der einen Seite das fremdsprachige Wort und auf der anderen die Übersetzung in meine Muttersprache. Diese Wortkarten habe ich immer in meiner Handtasche. Jeden Tag fahre ich eine Stunde mit dem Zug zur Schule. Das ist langweilig. Da habe ich viel Zeit und dann hole ich meine Wortkarten heraus und wiederhole die Wörter."},{"label":"B  Hakan, 19 Jahre","text":"Ich lerne seit vier Jahren Englisch in der Schule. Mir hilft es sehr, wenn ich viel Englisch höre. Ich habe viele MP3s mit Übungen aus dem Englischbuch und für die Aussprache auf meinem Smartphone. Ausserdem habe ich im Internet gute englische Podcasts gefunden. Die höre ich, wenn ich unterwegs bin. Ich möchte irgendwann nach der Schule ein Jahr nach London gehen und mir dort einen Job suchen. Darum will ich gut Englisch sprechen und auch meine Aussprache verbessern."},{"label":"C  Danila, 16 Jahre","text":"Ich bin vor drei Jahren in die Schweiz gekommen. Jetzt kann ich schon ziemlich gut Deutsch. Viel Zuhören ist für mich am allerwichtigsten. Deswegen habe ich im Bus, auf der Strasse, einfach überall immer den Schweizern zugehört und viel deutschsprachiges Fernsehen geschaut. Einfache Filme oder Serien. So habe ich viele Wörter und kleine Sätze der Alltagssprache gelernt, sogar auf Dialekt. Immer nur Grammatik und Wörter lernen, das finde ich uninteressant."}],"example":[{"label":"1","text":"Ich möchte meine Aussprache verbessern. → **B**"}],"items":[{"label":"2","text":"Ich höre oft anderen Leuten zu. → ___","gaps":[["C","Danila"]],"solution":"Ich höre oft anderen Leuten zu. → **C**","en":"我经常倾听别人说话。→ C（Danila）","why":"Danila：*Deswegen habe ich … einfach überall immer den Schweizern zugehört.*","source":"hueber"},{"label":"3","text":"Auf dem Weg zur Schule lerne ich Wörter. → ___","gaps":[["A","Mila"]],"solution":"Auf dem Weg zur Schule lerne ich Wörter. → **A**","en":"我在上学的路上背单词。→ A（Mila）","why":"Mila 在坐一小时火车去上学的路上拿出她的单词卡片。","source":"hueber"},{"label":"4","text":"Ich möchte nach der Schule in England arbeiten. → ___","gaps":[["B","Hakan"]],"solution":"Ich möchte nach der Schule in England arbeiten. → **B**","en":"中学毕业后我想去英国工作。→ B（Hakan）","why":"Hakan：*… ein Jahr nach London gehen und mir dort einen Job suchen.*","source":"hueber"},{"label":"5","text":"Ich schaue viel deutschsprachiges Fernsehen. → ___","gaps":[["C","Danila"]],"solution":"Ich schaue viel deutschsprachiges Fernsehen. → **C**","en":"我看很多德语电视节目。→ C（Danila）","why":"Danila：*… viel deutschsprachiges Fernsehen geschaut. Einfache Filme oder Serien.*","source":"hueber"},{"label":"6","text":"Ich schreibe Wortkarten. → ___","gaps":[["A","Mila"]],"solution":"Ich schreibe Wortkarten. → **A**","en":"我写单词卡片。→ A（Mila）","why":"Mila 在卡片的一面写外语单词，另一面写翻译。","source":"hueber"}]},{"no":"16","part":"b","part_instruction":"Schreiben Sie Sätze.","part_instruction_en":"写出第二个句子：用给出的词（Deshalb, Darum …）开头，并使用括号里的词。动词紧跟在开头的词后面。","example":[{"label":"1","lead":"Mila möchte viele neue Wörter lernen. (neue Wörter auf Wortkarten schreiben)","text":"Deshalb **schreibt sie neue Wörter auf Wortkarten**."}],"items":[{"label":"2","lead":"Mila findet den Weg zur Schule langweilig. (mit Wortkarten neue Wörter wiederholen)","text":"","accept":["Darum wiederholt sie neue Wörter mit Wortkarten.","Darum wiederholt sie mit Wortkarten neue Wörter."],"solution":"**Darum wiederholt sie neue Wörter mit Wortkarten.**","en":"所以她用单词卡片复习新单词。","why":"*Darum* 占第一位，所以变位动词 *wiederholt* 紧随其后，然后是主语 *sie*。","source":"darum"},{"label":"3","lead":"Hakan hilft es, wenn er viel Englisch hört. (viele Podcasts auf seinem Smartphone haben)","text":"","accept":["Aus diesem Grund hat er viele Podcasts auf seinem Smartphone."],"solution":"**Aus diesem Grund hat er viele Podcasts auf seinem Smartphone.**","en":"出于这个原因，他的智能手机上有很多播客。","why":"*Aus diesem Grund* 和 *deshalb* 一样占第一位：接着是动词 *hat*，然后是 *er*。","source":"hueber"},{"label":"4","lead":"Hakan möchte nach der Schule ein Jahr in London arbeiten. (gut Englisch sprechen wollen)","text":"","accept":["Deswegen will er gut Englisch sprechen."],"solution":"**Deswegen will er gut Englisch sprechen.**","en":"所以他想把英语说好。","why":"*Deswegen* + 情态动词 *will* 在第二位，不定式 *sprechen* 在句末。","source":"deswegen"},{"label":"5","lead":"Danila findet Grammatik und Wörter lernen uninteressant. (viel deutschsprachiges Fernsehen schauen)","text":"","accept":["Daher schaut sie viel deutschsprachiges Fernsehen."],"solution":"**Daher schaut sie viel deutschsprachiges Fernsehen.**","en":"因此她看很多德语电视节目。","why":"*Daher* 的意思和 *deshalb* 一样；动词 *schaut* 紧跟在它后面。","source":"deshalb"},{"label":"6","lead":"Für Danila ist Zuhören am allerwichtigsten. (einfach überall immer den Schweizern zugehört)","text":"","accept":["Aus diesem Grund hört sie einfach überall immer den Schweizern zu.","Aus diesem Grund hat sie einfach überall immer den Schweizern zugehört."],"solution":"**Aus diesem Grund hört sie einfach überall immer den Schweizern zu.**","en":"出于这个原因，她干脆随时随地都听瑞士人说话。","why":"*zuhören* 是可分动词：*hört … zu*。题目印的是 *zugehört*，所以现在完成时 *hat … zugehört*（和 Danila 的短文一样）也正确。","source":"hueber","check":"官方答案给的是现在时（*hört … zu*），虽然题目印的是第二分词 *zugehört*。两个句子都是正确的德语；问问你的老师书上要的是哪一个。"}]}]},{"page":"AB 138","heading":"Test Lektion 4","heading_en":"第 4 课测试","exercises":[{"no":"1","instruction":"Ergänzen Sie.","instruction_en":"补全 Arif 的短文。书中给出了每个词的首字母和词中的几个字母；请写出完整的单词。","reading":[{"text":"Ich heisse Arif und bin 16 Jahre alt. Meine Familie und ich stammen (a) aus Syrien und unsere M… (b) ist Arabisch. Jetzt lerne ich seit einem Jahr Deutsch. Nächstes Jahr möchte ich eine Lehre beginnen. D… (c) möchte ich mein Deutsch verbessern. Natürlich spreche ich dann noch nicht f… (d) Deutsch. Besonders die Schrift und die A… (e) finde ich schwierig und ich verstehe auch noch nicht alle A… (f). Aber ich bin optimistisch."}],"example":[{"label":"a","text":"Meine Familie und ich **stammen** aus Syrien."}],"items":[{"label":"b","lead":"… und unsere M _ t _ _ _ s _ _ _ c _ _ ist Arabisch.","text":"… und unsere ___ ist Arabisch.","gaps":[["Muttersprache"]],"solution":"… und unsere **Muttersprache** ist Arabisch.","en":"……而我们的母语是阿拉伯语。","why":"*die Muttersprache* = 母语，即你从小说的第一语言。"},{"label":"c","lead":"D _ _ _ e _ e _ möchte ich mein Deutsch verbessern.","text":"___ möchte ich mein Deutsch verbessern.","gaps":[["Deswegen"]],"solution":"**Deswegen** möchte ich mein Deutsch verbessern.","en":"所以我想提高我的德语水平。","why":"字母提示（D, e, e）符合 *Deswegen*；它表示结果，动词 *möchte* 紧跟在它后面。","source":"deswegen"},{"label":"d","lead":"Natürlich spreche ich dann noch nicht f _ _ _ _ _ e _ _ Deutsch.","text":"Natürlich spreche ich dann noch nicht ___ Deutsch.","gaps":[["fliessend"]],"solution":"Natürlich spreche ich dann noch nicht **fliessend** Deutsch.","en":"当然，到那时我还不能说一口流利的德语。","why":"*fliessend* = 流利的、流利地。瑞士写法用 *ss*。"},{"label":"e","lead":"Besonders die Schrift und die A _ _ _ p _ _ _ _ e finde ich schwierig …","text":"Besonders die Schrift und die ___ finde ich schwierig …","gaps":[["Aussprache"]],"solution":"Besonders die Schrift und die **Aussprache** finde ich schwierig …","en":"我觉得特别难的是文字和发音……","why":"*die Aussprache* = 发音（*aussprechen* = 发音、读出）。"},{"label":"f","lead":"… und ich verstehe auch noch nicht alle A _ _ d _ _ c _ e.","text":"… und ich verstehe auch noch nicht alle ___.","gaps":[["Ausdrücke"]],"solution":"… und ich verstehe auch noch nicht alle **Ausdrücke**.","en":"……而且我也还不懂所有的表达。","why":"*der Ausdruck, die Ausdrücke* = 说法、表达（单数、复数）；*alle* 后面要用复数。"}]},{"no":"2","instruction":"Schreiben Sie Sätze mit wenn.","instruction_en":"用 *wenn* 和第二虚拟式（*wäre, hätte, könnte, müsste* 或 *würde* + 不定式）写非真实条件句。","example":[{"label":"a","lead":"(ich heute nicht so viel vorhaben – spazieren gehen)","text":"Wenn **ich heute nicht so viel vorhätte, würde ich spazieren gehen**."}],"items":[{"label":"b","lead":"(ich mein Englisch besser sein – dir bei der Hausaufgabe helfen können)","text":"","accept":["Wenn mein Englisch besser wäre, könnte ich dir bei der Hausaufgabe helfen.","Wenn mein Englisch besser wäre, würde ich dir bei der Hausaufgabe helfen können."],"solution":"**Wenn mein Englisch besser wäre, könnte ich dir bei der Hausaufgabe helfen.**","en":"如果我的英语好一些，我就能帮你做作业了。","why":"*sein* → **wäre**，放在 *wenn* 从句的末尾；*können* → **könnte**，然后主句以动词开头。","source":"kond"},{"label":"c","lead":"(ich euch besser verstehen – ihr nicht durcheinander sprechen)","text":"","accept":["Ich würde euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet.","Ich würde euch besser verstehen, wenn ihr nicht durcheinandersprechen würdet.","Ich könnte euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet."],"solution":"**Ich würde euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet.**","en":"如果你们不是七嘴八舌地同时说话，我会更好地听懂你们。","why":"主句在前；两部分都用 *würde* + 不定式。在 *wenn* 从句中，*würdet* 放在句末。","source":"kond"},{"label":"d","lead":"(ich mehr Freizeit haben – nicht so viel arbeiten müssen)","text":"","accept":["Ich hätte mehr Freizeit, wenn ich nicht so viel arbeiten müsste."],"solution":"**Ich hätte mehr Freizeit, wenn ich nicht so viel arbeiten müsste.**","en":"如果我不用工作这么多，我就会有更多空闲时间。","why":"*haben* → **hätte**，*müssen* → **müsste**（放在 *wenn* 从句的末尾）。","source":"k2"}]},{"no":"3","instruction":"Ordnen Sie zu.","instruction_en":"用框里的词填空。每个词只用一次；划掉的那个已用在例句中（即 a 项的答案）。","box":["denn","Weshalb","Weil","Wegen","Deswegen"],"box_used":[2],"box_exact":true,"items":[{"label":"a","text":"___ möchte Costa Mechatroniker werden? – Weil er sich für Autos interessiert.","gaps":[["Weshalb"]],"solution":"**Weshalb** möchte Costa Mechatroniker werden? – Weil er sich für Autos interessiert.","en":"Costa 为什么想当机电技师？——因为他对汽车感兴趣。","why":"这里需要一个疑问词；**Weshalb** = *warum*（为什么）。书上印的回答以 *Weil* 开头。","source":"weil"},{"label":"b","text":"___ seiner guten Deutschkenntnisse hat er schnell eine Lehrstelle gefunden.","gaps":[["Wegen"]],"solution":"**Wegen** seiner guten Deutschkenntnisse hat er schnell eine Lehrstelle gefunden.","en":"由于德语知识扎实，他很快就找到了一个学徒岗位。","why":"后面接名词短语（*seiner guten Deutschkenntnisse*，复数第二格）→ 介词 **Wegen**。","source":"wegen"},{"label":"c","text":"Er ist erst 17 Jahre alt. ___ wohnt er noch bei seinen Eltern.","gaps":[["Deswegen"]],"solution":"Er ist erst 17 Jahre alt. **Deswegen** wohnt er noch bei seinen Eltern.","en":"他才 17 岁。所以他还和父母住在一起。","why":"表示结果，而且动词紧跟在空格后面（*wohnt er*）→ **Deswegen**。","source":"deswegen"},{"label":"d","text":"Jetzt spart er Geld, ___ er möchte nach der Ausbildung eine eigene Wohnung haben.","gaps":[["denn"]],"solution":"Jetzt spart er Geld, **denn** er möchte nach der Ausbildung eine eigene Wohnung haben.","en":"现在他在存钱，因为他想在职业培训结束后有一套自己的公寓。","why":"表示原因，而且动词仍在第二位（*er möchte*）→ **denn**。","source":"denn"}]},{"no":"4","instruction":"Wie kann man auch sagen? Ergänzen Sie.","instruction_en":"还可以怎么说？补全第二个说法。书中给出了一些字母；请写出完整的单词。","example":[{"label":"a","text":"Können Sie mir sagen, wo …? – **Wissen Sie**, wo …?"}],"items":[{"label":"b","lead":"Ich habe eine Frage. – D _ _ _  i _ _  S _ _  e _ _ _ _  f _ _ _ _ _?","text":"Ich habe eine Frage. – ___?","gaps":[["Darf ich Sie etwas fragen"]],"solution":"Ich habe eine Frage. – **Darf ich Sie etwas fragen**?","en":"我有一个问题。——我可以问您一件事吗？","why":"礼貌地开始提问的一种方式：*Darf ich Sie etwas fragen?*"},{"label":"c","lead":"Könnten Sie das bitte noch einmal sagen? – K _ _ _ t _ _  S _ _  d _ s  b _ _ t _  wi _ _ _ h _ _ _ _?","text":"Könnten Sie das bitte noch einmal sagen? – ___?","gaps":[["Könnten Sie das bitte wiederholen"]],"solution":"Könnten Sie das bitte noch einmal sagen? – **Könnten Sie das bitte wiederholen**?","en":"您能再说一遍吗？——您能重复一遍吗？","why":"*wiederholen* = 重复 = *noch einmal sagen*。"},{"label":"d","lead":"Was meinen Sie mit …? – W _ _  b _ _ e _ _ _ _ …?","text":"Was meinen Sie mit …? – ___ …?","gaps":[["Was bedeutet"]],"solution":"Was meinen Sie mit …? – **Was bedeutet** …?","en":"您说的……是指什么？——……是什么意思？","why":"*Was bedeutet …?* 询问意思，和 *Was meinen Sie mit …?* 一样。","check":"照片上这个空里的字母很难看清；*Was bedeutet …?* 和这些字母相符，也是第 13 题中的说法。如果你的书上印的是别的，问问你的老师。"},{"label":"e","lead":"Entschuldigung. – T _ _  m _ _  l _ _ _.","text":"Entschuldigung. – ___.","gaps":[["Tut mir leid"]],"solution":"Entschuldigung. – **Tut mir leid**.","en":"对不起。/ 不好意思。——很抱歉。","why":"*Tut mir leid* = 很抱歉，是另一种道歉的说法。"}]}]},{"page":"AB 139","heading":"Fokus Beruf: Stellensuche","heading_en":"职场聚焦：找工作","exercises":[{"no":"1","instruction":"Yusuf sucht eine neue Stelle als Coiffeur. Er liest eine Broschüre mit Tipps für die Stellensuche. Lesen Sie die Tipps und ordnen Sie die Überschriften zu.","instruction_en":"Yusuf 在找一份新的理发师工作。他读了一本介绍求职窍门的小册子。阅读这些窍门，在每段后面写上相应标题的字母（A–E）。","reading":[{"label":"1","text":"Machen Sie eine Liste von Personen, die Sie persönlich kennen: Bekannte, Kollegen, Freunde und Verwandte. Notieren Sie auch die Namen von früheren Arbeitgebern und Arbeitskollegen. Informieren Sie diese Personen – mündlich oder schriftlich – darüber, dass Sie auf Stellensuche sind. Wichtig: Informieren Sie Ihre Kontaktpersonen, wenn Sie eine Stelle gefunden haben."},{"label":"2","text":"Werden Sie aktiv. Warten Sie nicht, bis Sie ein passendes Stelleninserat finden, sondern schreiben Sie Ihre eigene Stellenanzeige. Suchen Sie ein Internet-Portal, das zu Ihrer Branche passt, und präsentieren Sie sich. Solche Annoncen kosten viel weniger als gedruckte Annoncen und Sie können sie ausserdem noch mit einer eigenen Bewerber-Website verbinden."},{"label":"3","text":"Erhöhen Sie Ihre Erfolgschancen mit einer Kurzbewerbung. Suchen Sie sich Ihre Wunschfirma und bewerben Sie sich. Dafür braucht es natürlich eine gute Recherche, damit Sie die «richtige» Firma und die «richtige» Person anschreiben. Wie ihr Name sagt, ist diese Bewerbung kurz: Sie besteht aus einem Bewerbungsschreiben und dem tabellarischen Lebenslauf."},{"label":"4","text":"Sind in Ihrer Branche Bewerbungen per Telefon üblich? Sind Sie besonders mutig und überzeugen vor allem mündlich sehr gut? Aus welchem Grund Sie sich für diese Bewerbungsform entscheiden: Wichtig ist auch hier eine gründliche Vorbereitung. Machen Sie Notizen und üben Sie das Gespräch mit Freunden. Fehlt Ihnen der Mut dazu, wählen Sie die schriftliche Bewerbung."},{"label":"5","text":"Die grösste Auswahl an Stelleninseraten finden Sie im Internet. Wichtig ist eine sorgfältige Analyse der Inserate: Was will die Firma? Welche Qualifikationen und Erfahrungen haben Sie? Machen Sie eine Liste und beantworten Sie diese Fragen. Können Sie ca. 80 Prozent der Anforderungen erfüllen, dann ist eine Bewerbung sinnvoll."}],"items":[{"label":"1","text":"Absatz 1 (Liste von Personen, die Sie kennen) → ___","gaps":[["C","C Das persönliche Netzwerk"]],"solution":"Absatz 1 (Liste von Personen, die Sie kennen) → **C**","en":"第 1 段（你认识的人的名单）→ C，你的个人人脉","why":"朋友、同事和以前的雇主就是你的个人人脉。","source":"hueber"},{"label":"2","text":"Absatz 2 (Ihre eigene Stellenanzeige im Internet) → ___","gaps":[["A","A Online-Stellengesuch"]],"solution":"Absatz 2 (Ihre eigene Stellenanzeige im Internet) → **A**","en":"第 2 段（你自己发布在网上的求职广告）→ A，网上求职广告","why":"*das Stellengesuch* = 你为找工作而发布的广告；这里是发在网上的求职平台上。","source":"hueber"},{"label":"3","text":"Absatz 3 (Kurzbewerbung bei Ihrer Wunschfirma) → ___","gaps":[["E","E Spontanbewerbung"]],"solution":"Absatz 3 (Kurzbewerbung bei Ihrer Wunschfirma) → **E**","en":"第 3 段（向你心仪的公司发送简短的求职信）→ E，主动求职","why":"你向一家没有发布招聘信息的公司求职：*die Spontanbewerbung*。","source":"hueber"},{"label":"4","text":"Absatz 4 (Bewerbungen per Telefon) → ___","gaps":[["D","D Telefonische Bewerbung"]],"solution":"Absatz 4 (Bewerbungen per Telefon) → **D**","en":"第 4 段（通过电话求职）→ D，电话求职","why":"*per Telefon* = *telefonisch*。","source":"hueber"},{"label":"5","text":"Absatz 5 (Stelleninserate im Internet analysieren) → ___","gaps":[["B","B Stelleninserate"]],"solution":"Absatz 5 (Stelleninserate im Internet analysieren) → **B**","en":"第 5 段（分析网上的招聘广告）→ B，招聘广告","why":"*das Stelleninserat*（瑞士用语）= 公司发布的招聘广告。","source":"hueber"}],"phrases":["A Online-Stellengesuch","B Stelleninserate","C Das persönliche Netzwerk","D Telefonische Bewerbung","E Spontanbewerbung"]},{"no":"2","instruction":"Yusuf hat entschieden, selbst aktiv zu werden, und hat ein Stellengesuch geschrieben. Lesen Sie seinen Text und unterstreichen Sie: – Wer und wie ist Yusuf? – Was kann er? – Was sucht er?","instruction_en":"Yusuf 决定主动出击，写了一则求职广告。阅读他的文字，找出：Yusuf 是谁、是什么样的人，他会做什么，他在找什么。针对每个问题写出相应的词语。","reading":[{"text":"Suchen Sie einen engagierten Coiffeur, der kreativ und flexibel ist? Dann rufen Sie mich, 24, an. Ich biete sechs Jahre Berufserfahrung und diverse Weiterbildungen im Bereich Stilberatung. Ich suche eine Herausforderung, bei der ich Neues lernen und mich weiter spezialisieren kann."}],"items":[{"label":"1","lead":"Wer und wie ist Yusuf?","text":"","open":true,"solution":"ein engagierter Coiffeur, kreativ und flexibel, 24 Jahre alt","en":"一名敬业的理发师，有创意又灵活，24 岁","why":"他是谁（职业、年龄）和他是什么样的人（形容词）。","source":"hueber"},{"label":"2","lead":"Was kann er?","text":"","open":true,"solution":"sechs Jahre Berufserfahrung, diverse Weiterbildungen im Bereich Stilberatung","en":"六年工作经验，参加过多次形象风格咨询方面的进修","why":"他能提供什么：经验和进修。","source":"hueber"},{"label":"3","lead":"Was sucht er?","text":"","open":true,"solution":"eine Herausforderung, bei der er Neues lernen und sich weiter spezialisieren kann","en":"一项能让他学到新东西、并在专业上进一步深耕的挑战","why":"最后一句：*Ich suche …*","source":"hueber"}]},{"no":"3","instruction":"Ein Stellengesuch im Internet aufgeben. Sie suchen eine neue Stelle. Machen Sie eine Tabelle. Schreiben Sie dann einen Profiltext wie in 2.","instruction_en":"在网上发布一则求职广告。你正在找一份新工作。画一个三栏的表格（我是谁、是什么样的人？我会做什么？我在找什么？），然后像第 2 题中的 Yusuf 那样写一段个人简介。参考答案只是一种可能。","phrases":["teamfähig/selbstständig/kontaktfreudig/zuverlässig/verantwortungsbewusst / … sein","gute Computer-/Sprachkenntnisse/Kenntnisse in … haben","gut mit … umgehen können","… Vollzeit/Teilzeit/auf Stundenbasis arbeiten","ab sofort / ab nächstem Monat / … suchen"],"example":[{"label":"Tabelle","text":"Wer und wie bin ich? flexibel, teamfähig, … | Was kann ich? … | Was suche ich? …"}],"items":[{"label":"1","lead":"Tabelle","text":"","open":true,"solution":"Wer und wie bin ich? flexibel, teamfähig, zuverlässig, kontaktfreudig | Was kann ich? gut mit Kunden umgehen, gute Computerkenntnisse, fliessend Deutsch und Englisch | Was suche ich? eine Teilzeitstelle ab nächstem Monat, ein internationales Team","en":"我是谁、是什么样的人？灵活、有团队精神、可靠、善于交际 | 我会做什么？善于和顾客打交道、电脑技能好、德语和英语流利 | 我在找什么？从下个月开始的兼职工作、一个国际化的团队","why":"每栏写几个关键词就够了；用框里的短语。","source":"hueber"},{"label":"2","lead":"Profiltext","text":"","open":true,"solution":"Suchen Sie eine zuverlässige Verkäuferin, die teamfähig und kontaktfreudig ist? Ich kann gut mit Kunden umgehen, habe gute Computerkenntnisse und spreche fliessend Deutsch und Englisch. Ich suche ab nächstem Monat eine Teilzeitstelle in einem internationalen Team.","en":"您在找一位可靠、有团队精神又善于交际的女售货员吗？我善于和顾客打交道，电脑技能好，德语和英语都说得很流利。我在找一份从下个月开始、在国际化团队里的兼职工作。","why":"和 Yusuf 一样的三步：你是谁、你会做什么、你在找什么。关系从句中的 *die* 指的是 *Verkäuferin*。","source":"hueber"}]}]},{"page":"Test L4 · 19","heading":"Grammatik","heading_en":"语法","exercises":[{"no":"1","instruction":"Wunsch und Realität?","instruction_en":"愿望与现实？","part":"a","part_instruction":"Ergänzen Sie.","part_instruction_en":"Nina 必须做一件事，却更想做另一件事。用 *würde* + 括号里的词写出她更想做什么（用 *lieber*，第 5 项用 *gern*）。","example":[{"label":"1","lead":"Nina macht Diät. (Sahnetorte essen)","text":"Aber sie **würde lieber Sahnetorte essen**."}],"items":[{"label":"2","lead":"Nina muss für eine Sprachprüfung lernen. (Musik hören)","text":"Aber sie ___.","gaps":[["würde lieber Musik hören"]],"solution":"Aber sie **würde lieber Musik hören**.","en":"可是她更想听音乐。","why":"*würde* 在第二位，*lieber* = 更愿意，不定式 *hören* 在句末。","source":"k2"},{"label":"3","lead":"Nina muss ihre Kleider aufräumen. (mit ihrer Freundin telefonieren)","text":"Aber sie ___.","gaps":[["würde lieber mit ihrer Freundin telefonieren"]],"solution":"Aber sie **würde lieber mit ihrer Freundin telefonieren**.","en":"可是她更想和她的朋友打电话。","why":"*würde* + *lieber* + 句末的不定式。","source":"k2"},{"label":"4","lead":"Nina arbeitet am Computer. (Computerspiele spielen)","text":"Aber sie ___.","gaps":[["würde lieber Computerspiele spielen"]],"solution":"Aber sie **würde lieber Computerspiele spielen**.","en":"可是她更想玩电脑游戏。","why":"*würde* + *lieber* + 句末的不定式。","source":"k2"},{"label":"5","lead":"Nina hat morgen sehr früh einen Termin. (bis spät in die Nacht lesen)","text":"Sie ___ gern ___.","gaps":[["würde aber"],["bis spät in die Nacht lesen"]],"solution":"Sie **würde aber** gern **bis spät in die Nacht lesen**.","en":"不过她很想读书读到深夜。","why":"书中印的是 *gern*：*würde* + *gern* + 不定式（表示愿望），*aber* 放在动词之后。","source":"k2"},{"label":"6","lead":"Nina verbringt den Abend mit ihren Eltern. (tanzen gehen)","text":"Aber sie ___.","gaps":[["würde lieber tanzen gehen"]],"solution":"Aber sie **würde lieber tanzen gehen**.","en":"可是她更想去跳舞。","why":"*würde* + *lieber*；两个不定式 *tanzen gehen* 都在句末。","source":"k2"}]},{"no":"1","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"把 a 中的句子改写成非真实条件句：*Wenn Nina nicht …, würde sie …*","example":[{"label":"1","text":"Wenn Nina nicht Diät machen würde, würde sie Sahnetorte essen."}],"items":[{"label":"2","text":"","accept":["Wenn Nina nicht für eine Sprachprüfung lernen müsste, würde sie Musik hören."],"solution":"**Wenn Nina nicht für eine Sprachprüfung lernen müsste, würde sie Musik hören.**","en":"如果 Nina 不用为语言考试学习，她就会听音乐。","why":"*muss* → **müsste**，放在 *wenn* 从句的末尾；主句以 *würde* 开头。","source":"kond"},{"label":"3","text":"","accept":["Wenn Nina nicht ihre Kleider aufräumen müsste, würde sie mit ihrer Freundin telefonieren.","Wenn Nina ihre Kleider nicht aufräumen müsste, würde sie mit ihrer Freundin telefonieren."],"solution":"**Wenn Nina nicht ihre Kleider aufräumen müsste, würde sie mit ihrer Freundin telefonieren.**","en":"如果 Nina 不用整理她的衣服，她就会和她的朋友打电话。","why":"*müsste* + 不定式 *aufräumen*：在 *wenn* 从句中，*müsste* 放在最后。","source":"kond"},{"label":"4","text":"","accept":["Wenn Nina nicht am Computer arbeiten würde, würde sie Computerspiele spielen.","Wenn Nina nicht am Computer arbeiten müsste, würde sie Computerspiele spielen."],"solution":"**Wenn Nina nicht am Computer arbeiten würde, würde sie Computerspiele spielen.**","en":"如果 Nina 不是在用电脑工作，她就会玩电脑游戏。","why":"答案里 *wenn* 从句用 *arbeiten würde* 或 *arbeiten müsste* 都可以。"},{"label":"5","text":"","accept":["Wenn Nina morgen nicht sehr früh einen Termin hätte, würde sie bis spät in die Nacht lesen.","Wenn Nina morgen keinen Termin sehr früh hätte, würde sie bis spät in die Nacht lesen."],"solution":"**Wenn Nina morgen nicht sehr früh einen Termin hätte, würde sie bis spät in die Nacht lesen.**","en":"如果 Nina 明天不是一大早就有约，她就会读书读到深夜。","why":"*hat* → **hätte**，放在 *wenn* 从句的末尾。"},{"label":"6","text":"","accept":["Wenn Nina den Abend nicht mit ihren Eltern verbringen würde, würde sie tanzen gehen.","Wenn Nina den Abend nicht mit ihren Eltern verbringen müsste, würde sie tanzen gehen."],"solution":"**Wenn Nina den Abend nicht mit ihren Eltern verbringen würde, würde sie tanzen gehen.**","en":"如果 Nina 不是和父母一起度过这个晚上，她就会去跳舞。","why":"两部分都用 *würde* + 不定式；*verbringen würde* 在 *wenn* 从句的末尾。"}]},{"no":"2","instruction":"Ergänzen Sie: darum – weil – wegen.","instruction_en":"用 *darum*、*weil* 或 *wegen* 填空。每个词用两次。","box":["darum","weil","wegen"],"items":[{"label":"a","text":"Viele Deutsche hören Majids Grammatikfehler nicht, ___ er eine sehr gute Aussprache hat.","gaps":[["weil"]],"solution":"Viele Deutsche hören Majids Grammatikfehler nicht, **weil** er eine sehr gute Aussprache hat.","en":"很多德国人听不出 Majid 的语法错误，因为他的发音非常好。","why":"表示原因，而且动词 *hat* 在句末 → **weil**。","source":"weil"},{"label":"b","text":"Mirko hat die Prüfung nicht bestanden, ___ will er jetzt einen Intensivkurs machen.","gaps":[["darum"]],"solution":"Mirko hat die Prüfung nicht bestanden, **darum** will er jetzt einen Intensivkurs machen.","en":"Mirko 没有通过考试，所以他现在想上一门强化课程。","why":"表示结果，而且动词 *will* 紧跟在空格后面 → **darum**。","source":"darum"},{"label":"c","text":"Hassan will als Arzt in einem deutschen Krankenhaus arbeiten, ___ braucht er sehr gute Deutschkenntnisse.","gaps":[["darum"]],"solution":"Hassan will als Arzt in einem deutschen Krankenhaus arbeiten, **darum** braucht er sehr gute Deutschkenntnisse.","en":"Hassan 想在德国的一家医院当医生，所以他需要非常好的德语水平。","why":"结果 + 动词紧跟在空格后面（*braucht er*）→ **darum**。","source":"darum"},{"label":"d","text":"Camilla ist Managerin und kann ___ ihrer vielen Konferenzen nicht regelmässig am Deutschkurs teilnehmen.","gaps":[["wegen"]],"solution":"Camilla ist Managerin und kann **wegen** ihrer vielen Konferenzen nicht regelmässig am Deutschkurs teilnehmen.","en":"Camilla 是一名经理，由于会议很多，她不能定期上德语课。","why":"后面接名词短语（*ihrer vielen Konferenzen*，复数第二格）→ **wegen**。","source":"wegen"},{"label":"e","text":"Boris wird ___ seines Akzents sofort als Russe erkannt.","gaps":[["wegen"]],"solution":"Boris wird **wegen** seines Akzents sofort als Russe erkannt.","en":"由于口音，Boris 一下子就被认出是俄罗斯人。","why":"第二格的名词短语（*seines Akzents*）→ **wegen**。","source":"wegen"},{"label":"f","text":"Anja würde gern Arabisch lernen, ___ sie die arabische Schrift so schön findet.","gaps":[["weil"]],"solution":"Anja würde gern Arabisch lernen, **weil** sie die arabische Schrift so schön findet.","en":"Anja 很想学阿拉伯语，因为她觉得阿拉伯文字非常漂亮。","why":"表示原因，动词 *findet* 在句末 → **weil**。","source":"weil"}]}]},{"page":"Test L4 · 20","heading":"Wortschatz","heading_en":"词汇","exercises":[{"no":"3","instruction":"Ordnen Sie zu.","instruction_en":"用框里的词补全 Ferdez 的短文。每个词只用一次；划掉的那个已用在例句中。练习纸用的是带 sharp s（尖 s）的德国写法；这里用瑞士写法 *ss*（*fliessend*）。","box":["Akzent","fliessend","schimpfe","Muttersprache","Schrift","übersetzen","vergleiche"],"box_used":[3],"box_exact":true,"example":[{"label":"a","text":"Mein Name ist Ferdez. Ich komme aus Mazedonien. Meine **Muttersprache** ist Albanisch, aber ich spreche auch Mazedonisch."}],"items":[{"label":"b","text":"Im Mazedonischen wird die kyrillische ___ verwendet. Darum war es anfangs für mich nicht einfach, Deutsch zu schreiben.","gaps":[["Schrift"]],"solution":"Im Mazedonischen wird die kyrillische **Schrift** verwendet. Darum war es anfangs für mich nicht einfach, Deutsch zu schreiben.","en":"马其顿语使用西里尔字母。所以一开始写德语对我来说并不容易。","why":"*die kyrillische Schrift* = 西里尔字母。"},{"label":"c","text":"Seit acht Jahren lebe ich in Bayern. Inzwischen spreche ich ___ Deutsch, finde ich.","gaps":[["fliessend"]],"solution":"Seit acht Jahren lebe ich in Bayern. Inzwischen spreche ich **fliessend** Deutsch, finde ich.","en":"我在巴伐利亚已经住了八年。我觉得，现在我的德语已经说得很流利了。","why":"*fliessend Deutsch sprechen* = 说一口流利的德语。"},{"label":"d","text":"Aber meine Kollegen aus Norddeutschland meinen, dass ich einen bayerischen ___ habe!","gaps":[["Akzent"]],"solution":"Aber meine Kollegen aus Norddeutschland meinen, dass ich einen bayerischen **Akzent** habe!","en":"可是我那些来自德国北部的同事说，我有巴伐利亚口音！","why":"*einen … Akzent haben* = 有……口音；*einen bayerischen* → 阳性名词。"},{"label":"e","text":"Wenn ich auf Bayerisch ___, lachen meine Kollegen sich kaputt.","gaps":[["schimpfe"]],"solution":"Wenn ich auf Bayerisch **schimpfe**, lachen meine Kollegen sich kaputt.","en":"每当我用巴伐利亚话骂骂咧咧时，我的同事们都笑得前仰后合。","why":"*schimpfen* = 发牢骚、骂人；*ich schimpfe* 在 *wenn* 从句的末尾。"},{"label":"f","text":"Wenn ich Deutsch, Mazedonisch und Albanisch miteinander ___, dann fällt mir auf, …","gaps":[["vergleiche"]],"solution":"Wenn ich Deutsch, Mazedonisch und Albanisch miteinander **vergleiche**, dann fällt mir auf, …","en":"当我把德语、马其顿语和阿尔巴尼亚语相互比较时，我发现……","why":"*miteinander vergleichen* = 相互比较；*ich vergleiche* 在 *wenn* 从句的末尾。"},{"label":"g","text":"… dass man nicht alle Wörter wirklich gut in die andere Sprache ___ kann. Ich fühle mich heute in Mazedonien und in Deutschland zu Hause.","gaps":[["übersetzen"]],"solution":"… dass man nicht alle Wörter wirklich gut in die andere Sprache **übersetzen** kann. Ich fühle mich heute in Mazedonien und in Deutschland zu Hause.","en":"……不是所有的词都能很好地翻译成另一种语言。如今我在马其顿和德国都有家的感觉。","why":"*in eine Sprache übersetzen* = 翻译成某种语言；在 *dass* 从句的末尾，不定式放在 *kann* 前面。"}]},{"no":"Pause","instruction":"Was bedeutet das? Kreuzen Sie an. «Lügen haben kurze Beine.»","instruction_en":"俗语 «Lügen haben kurze Beine»（谎言腿短）是什么意思？写 A 或 B。","items":[{"label":"A/B","lead":"A Die Wahrheit kommt immer schnell ans Licht. Darum sollte man nicht lügen.  B Wer lügt, der bekommt zur Strafe kurze Beine.","text":"___","gaps":[["A"]],"solution":"**A**","en":"A：真相总是很快就会暴露。所以不应该说谎。","why":"谎言走不远，就像腿短的人一样：很快就会被识破。B 是拿字面意思开玩笑。"}]},{"no":"4","instruction":"Welches Wort passt auch? Notieren Sie.","instruction_en":"框里的哪个词可以替换画线的词？把它写出来。每个词只用一次；划掉的那个已用在例句中。画线的词以粗体显示。","box":["allerdings","allmählich","aufschreiben","deswegen","ebenso","irgendwann","korrekt","stammt"],"box_used":[7],"box_exact":true,"example":[{"label":"a","text":"Meine Familie **kommt** aus Iran. → stammt"}],"items":[{"label":"b","lead":"Ich selbst bin **aber** in Mainz geboren.","text":"___","gaps":[["allerdings"]],"solution":"**allerdings**","en":"不过我自己是在美因茨出生的。","why":"*allerdings* = *aber*：它对前面说的内容加以限制。"},{"label":"c","lead":"Mit mir haben meine Eltern immer Deutsch gesprochen, **deshalb** kann ich leider nicht Farsi.","text":"___","gaps":[["deswegen"]],"solution":"**deswegen**","en":"我父母一直跟我说德语，所以很可惜我不会说波斯语。","why":"*deswegen* = *deshalb*（表示结果，动词紧随其后）。","source":"deswegen"},{"label":"d","lead":"Jetzt nehme ich an einem Sprachkurs teil. Ich finde, Farsi ist **genauso** schwierig wie Deutsch.","text":"___","gaps":[["ebenso"]],"solution":"**ebenso**","en":"现在我在上语言课。我觉得波斯语和德语一样难。","why":"*ebenso … wie* = *genauso … wie* = 和……一样。"},{"label":"e","lead":"Besonders die Schrift! Ich bin ein Mensch, der sich alle neuen Wörter **notieren** muss.","text":"___","gaps":[["aufschreiben"]],"solution":"**aufschreiben**","en":"特别是文字！我是那种必须把所有新词都写下来的人。","why":"*sich etwas notieren* = *sich etwas aufschreiben* = 把某事记下来。"},{"label":"f","lead":"Das ist schwierig, wenn man es in einer Schrift tun muss, die man auch erst **langsam** lernt.","text":"___","gaps":[["allmählich"]],"solution":"**allmählich**","en":"要用一种自己还在慢慢学的文字来写，这就很难了。","why":"*allmählich* = 慢慢地、一步一步地、逐渐地。"},{"label":"g","lead":"Auch die Aussprache ist nicht leicht. Es gibt da diesen Laut «gh», den kann ich nicht **richtig** aussprechen.","text":"___","gaps":[["korrekt"]],"solution":"**korrekt**","en":"发音也不容易。有一个“gh”音，我发不准。","why":"*korrekt* = *richtig* = 正确地。"},{"label":"h","lead":"**Eines Tages** klappt es – hoffe ich jedenfalls!","text":"___","gaps":[["irgendwann","Irgendwann"]],"solution":"**irgendwann**","en":"总有一天会成功的——至少我希望如此！","why":"*irgendwann* = 在某个时候、总有一天 = *eines Tages*。"}]}]},{"page":"Test L4 · 21","heading":"Lesen","heading_en":"阅读","exercises":[{"no":"5","instruction":"Lesen Sie und kreuzen Sie an: Was ist richtig?","instruction_en":"阅读“学德语重要吗？”这项调查中的回答，为每个句子选出正确的结尾。写出这个结尾（或只写它开头的几个词）。","reading":[{"label":"Brad, 30, aus Australien","text":"«Meine Freundin ist Deutsche. Deshalb bin ich vor einem Jahr nach Deutschland gekommen. Ich dachte, dass ich mit Englisch als Muttersprache keine Schwierigkeiten haben würde, einen Job zu finden. Aber immer wenn ich mich bewarb, bekam ich zur Antwort: Lernen Sie erst einmal richtig Deutsch. Dann können Sie wiederkommen. Offenbar glauben die Leute, dass man auch keine Berufserfahrung hat, wenn man nicht perfekt Deutsch spricht. Seit sechs Monaten besuche ich nun einen Deutschkurs.»"},{"label":"Alena, 24, aus Tschechien","text":"«Meine Grossmutter hat 30 Jahre in Wien gelebt. Ich habe sie als Kind oft besucht und Wien dabei sehr gut kennengelernt. Ich denke, ich habe in Wien bessere Karrierechancen als bei uns zu Hause. Darum habe ich jetzt das Zertifikat Deutsch gemacht. Mit dem Zertifikat habe ich bestimmt gute Chancen, wenn ich mich bei österreichischen Firmen bewerbe.»"},{"label":"Ewa, 23, aus Polen","text":"«Ich finde es aus historischen Gründen wichtig, Deutsch zu lernen. Denn Polen und Deutschland verbindet eine lange Geschichte, die nicht immer schön war. Aber gerade deshalb ist es wichtig, dass wir uns gegenseitig gut kennenlernen. Ich würde mir wünschen, dass auch mehr Deutsche sich für die polnische Sprache interessieren würden.»"},{"label":"Sopha, 32, aus Thailand","text":"«Mein Mann stammt aus Hessen. Ich habe von ihm das Deutsch gelernt, das ich im Alltag so brauche. Aber jetzt gehen unsere beiden Söhne zur Schule, und ich habe gemerkt, dass meine Deutschkenntnisse nicht mehr ausreichend sind: In der Kommunikation mit der Klassenlehrerin und bei Elternabenden habe ich grosse Schwierigkeiten. Deshalb nehme ich jetzt an einem Deutschkurs für Eltern teil.»"},{"label":"Abdullah, 35, aus Bahrain","text":"«Ich arbeite seit ein paar Monaten an einer deutschen Klinik als Arzt. Für meine Arbeitserlaubnis musste ich sehr gute Deutschkenntnisse nachweisen. Im Krankenhaus brauche ich eigentlich gar nicht so viel Deutsch, denn für die Gespräche mit den Patienten genügt mein Deutsch, und die Kollegen sprechen alle sehr gut Englisch. Aber natürlich möchte ich die Sprache des Landes gut können, in dem ich lebe. Dann versteht man die Menschen und ihr Land besser. Aus diesem Grund lerne ich weiter Deutsch.»"},{"label":"Zeliha, 45, aus der Türkei","text":"«Ich bin nach Dortmund gekommen, als ich meinen Mann – einen Deutschtürken – geheiratet habe. Schnell kamen vier Kinder zur Welt. Das Geld war immer knapp bei uns, deswegen habe ich neben dem Haushalt und der Kindererziehung Schicht gearbeitet. Für einen Deutschkurs war nie Zeit und Geld da. Meine Kinder haben oft geschimpft, weil ich so schlecht Deutsch sprach. Jetzt lerne ich endlich richtig Deutsch, und meine Kinder helfen mir beim Lernen.»"}],"items":[{"label":"a","lead":"Wer gut Englisch kann, … ○ findet in Deutschland problemlos einen Job. ○ muss trotzdem gut Deutsch lernen.","text":"Wer gut Englisch kann, ___.","gaps":[["muss trotzdem gut Deutsch lernen","muss trotzdem"]],"solution":"Wer gut Englisch kann, **muss trotzdem gut Deutsch lernen**.","en":"英语说得好的人，也还是得把德语学好。","why":"Brad 的母语是英语，别人却一再对他说：*Lernen Sie erst einmal richtig Deutsch.*"},{"label":"b","lead":"Deutsche glauben offenbar, … ○ dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat. ○ dass man für eine Ausbildung Deutsch braucht.","text":"Deutsche glauben offenbar, ___.","gaps":[["dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat","dass man ohne perfektes Deutsch"]],"solution":"Deutsche glauben offenbar, **dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat**.","en":"看来德国人认为，德语不完美的人就没有专业能力。","why":"Brad：*… dass man auch keine Berufserfahrung hat, wenn man nicht perfekt Deutsch spricht.*"},{"label":"c","lead":"Alena hofft, dass sie mit dem Zertifikat Deutsch … ○ eine Arbeitsstelle in Österreich findet. ○ besser Bewerbungen schreiben kann.","text":"Alena hofft, dass sie mit dem Zertifikat Deutsch ___.","gaps":[["eine Arbeitsstelle in Österreich findet","eine Arbeitsstelle"]],"solution":"Alena hofft, dass sie mit dem Zertifikat Deutsch **eine Arbeitsstelle in Österreich findet**.","en":"Alena 希望凭着德语证书在奥地利找到一份工作。","why":"Alena 预计 *bei österreichischen Firmen* 有很好的机会。"},{"label":"d","lead":"Als Polin will Ewa Deutsch können, denn … ○ Deutschland und Polen haben eine gemeinsame Geschichte. ○ sie hat viele Deutsche kennengelernt.","text":"Als Polin will Ewa Deutsch können, denn ___.","gaps":[["Deutschland und Polen haben eine gemeinsame Geschichte","Deutschland und Polen"]],"solution":"Als Polin will Ewa Deutsch können, denn **Deutschland und Polen haben eine gemeinsame Geschichte**.","en":"作为波兰人，Ewa 想会德语，因为德国和波兰有共同的历史。","why":"Ewa：*Denn Polen und Deutschland verbindet eine lange Geschichte.*"},{"label":"e","lead":"Ewa findet es … ○ toll, dass so viel Deutsche Polnisch sprechen. ○ schade, dass sich nicht so viele Deutsche für Polnisch interessieren.","text":"Ewa findet es ___.","gaps":[["schade, dass sich nicht so viele Deutsche für Polnisch interessieren","schade"]],"solution":"Ewa findet es **schade, dass sich nicht so viele Deutsche für Polnisch interessieren**.","en":"Ewa 觉得很遗憾，对波兰语感兴趣的德国人不多。","why":"Ewa 希望有更多德国人对波兰语感兴趣。"},{"label":"f","lead":"Sopha hat … ○ von ihrem Mann Deutsch gelernt. ○ hat einen Integrationskurs besucht.","text":"Sopha hat ___.","gaps":[["von ihrem Mann Deutsch gelernt","von ihrem Mann"]],"solution":"Sopha hat **von ihrem Mann Deutsch gelernt**.","en":"Sopha 是跟她丈夫学的德语。","why":"Sopha：*Ich habe von ihm das Deutsch gelernt, das ich im Alltag so brauche.*"},{"label":"g","lead":"Sie … ○ muss ihren Söhnen bei den Deutschhausaufgaben helfen. ○ hat Probleme, weil sie die Lehrer nicht gut genug versteht.","text":"Sie ___.","gaps":[["hat Probleme, weil sie die Lehrer nicht gut genug versteht","hat Probleme"]],"solution":"Sie **hat Probleme, weil sie die Lehrer nicht gut genug versteht**.","en":"她遇到了困难，因为她对老师们的话理解得不够好。","why":"和班主任打交道时以及在家长会上，她都有 *grosse Schwierigkeiten*。"},{"label":"h","lead":"Für die Arbeitserlaubnis … ○ werden gute Deutschkenntnisse erwartet. ○ braucht man gar nicht so gute Deutschkenntnisse.","text":"Für die Arbeitserlaubnis ___.","gaps":[["werden gute Deutschkenntnisse erwartet","werden gute"]],"solution":"Für die Arbeitserlaubnis **werden gute Deutschkenntnisse erwartet**.","en":"申请工作许可需要具备良好的德语能力。","why":"Abdullah：*Für meine Arbeitserlaubnis musste ich sehr gute Deutschkenntnisse nachweisen.*"},{"label":"i","lead":"Abdullah will gut Deutsch können, weil … ○ die Patienten nicht Englisch sprechen. ○ er in Deutschland lebt.","text":"Abdullah will gut Deutsch können, weil ___.","gaps":[["er in Deutschland lebt"]],"solution":"Abdullah will gut Deutsch können, weil **er in Deutschland lebt**.","en":"Abdullah 想把德语学好，因为他住在德国。","why":"他想掌握 *des Landes …, in dem ich lebe* 的语言；他的德语应付病人已经够用了。"},{"label":"j","lead":"Zeliha lernt Deutsch … ○ , weil sie Geld verdienen muss. ○ wegen ihrer Kinder.","text":"Zeliha lernt Deutsch ___.","gaps":[["wegen ihrer Kinder"]],"solution":"Zeliha lernt Deutsch **wegen ihrer Kinder**.","en":"Zeliha 是因为她的孩子们才学德语的。","why":"她的孩子们抱怨她的德语太差，现在他们帮她学习。"}]}]},{"page":"Test L4 · 22","heading":"Sprechen","heading_en":"口语","exercises":[{"no":"7","instruction":"Welche Reaktion passt am besten? Verbinden Sie.","instruction_en":"哪个回答最合适？在每个句子后面写上回答的编号（1–6）。（本页的第 6 题是听力练习，已略去。）","example":[{"label":"a","text":"Darf ich Sie kurz etwas fragen? → **2** Natürlich, gern."}],"items":[{"label":"b","text":"Mein Name ist Kranitzky-Krampe. → ___","gaps":[["5"]],"solution":"Mein Name ist Kranitzky-Krampe. → **5**","en":"我叫 Kranitzky-Krampe。→ 5 对不起，您叫什么名字来着？","why":"一个又长又不常见的名字：你要再问一遍。"},{"label":"c","text":"Zu Kleidung kann man auch «Klamotten» sagen. → ___","gaps":[["4"]],"solution":"Zu Kleidung kann man auch «Klamotten» sagen. → **4**","en":"衣服也可以说成 «Klamotten»。→ 4 这个词我从来没听过。","why":"一个新的（口语）词：*Das Wort habe ich noch nie gehört.*"},{"label":"d","text":"Was bedeutet dieses Wort? → ___","gaps":[["1"]],"solution":"Was bedeutet dieses Wort? → **1**","en":"这个词是什么意思？→ 1 恐怕我也不知道。","why":"对一个你回答不了的问题的回应。"},{"label":"e","text":"Da habe ich echt Schwein gehabt. → ___","gaps":[["6"]],"solution":"Da habe ich echt Schwein gehabt. → **6**","en":"那次我真是走运。→ 6 我理解得对吗：你很走运？","why":"*Schwein haben*（口语）= 走运；你确认自己是否理解对了。"},{"label":"f","text":"Könnten Sie bitte langsamer sprechen? → ___","gaps":[["3"]],"solution":"Könnten Sie bitte langsamer sprechen? → **3**","en":"您能说慢一点吗？→ 3 好的，我试试。","why":"对一个请求的回应。"}],"phrases":["1 Das weiss ich leider auch nicht.","2 Natürlich, gern.","3 Okay, ich versuche es.","4 Das Wort habe ich noch nie gehört.","5 Wie war bitte Ihr Name?","6 Habe ich das richtig verstanden: Du hattest Glück?"]},{"no":"8","instruction":"Schreiben Sie die Fragen.","instruction_en":"用括号里的词写间接疑问句。在间接疑问句中，动词放在句末。","example":[{"label":"a","lead":"(Bild: Ein Mann und eine Frau lesen zusammen in einem Buch.) Weisst du vielleicht, … (Aufgabe – wie?)","text":"Weisst du vielleicht, **wie ich diese Aufgaben machen muss**?"}],"items":[{"label":"b","lead":"(Bild: Zwei Männer stehen mit ihren Mülltonnen auf der Strasse.) Können Sie mir sagen, … (Müll – wohin?)","text":"Können Sie mir sagen, ___?","gaps":[["wohin ich den Müll bringen muss","wohin ich den Müll bringen soll"]],"solution":"Können Sie mir sagen, **wohin ich den Müll bringen muss**?","en":"您能告诉我垃圾要拿到哪里去吗？","why":"*wohin* 引导间接疑问句；变位动词 *muss* 放在句末。"},{"label":"c","lead":"(Bild: Eine Frau sitzt beim Arzt.) Können Sie mir bitte sagen, … (Schmerzen – wo?)","text":"Können Sie mir bitte sagen, ___?","gaps":[["wo Sie Schmerzen haben"]],"solution":"Können Sie mir bitte sagen, **wo Sie Schmerzen haben**?","en":"您能告诉我您哪里疼吗？","why":"医生问：*wo* + 主语 + 句末的动词（*haben*）。"},{"label":"d","lead":"(Bild: Eine Frau fragt einen Mann im Zug.) Wissen Sie vielleicht, … (Zug nach Berlin – ob?)","text":"Wissen Sie vielleicht, ___?","gaps":[["ob der Zug nach Berlin fährt","ob dieser Zug nach Berlin fährt","ob das der Zug nach Berlin ist"]],"solution":"Wissen Sie vielleicht, **ob der Zug nach Berlin fährt**?","en":"请问您知道这趟火车是开往柏林的吗？","why":"是非疑问句用 *ob* 变成间接疑问句；动词 *fährt* 放在句末。"}]}]},{"page":"Test L4 · 23","heading":"Schreiben","heading_en":"写作","exercises":[{"no":"9","instruction":"Wählen Sie eine Sprache, die Sie gern lernen würden, und schreiben Sie eine Nachricht an die Sprachschule. – Schreiben Sie, für welche Sprache Sie sich interessieren. – Sagen Sie, wann und wie oft pro Woche Sie Zeit für den Kurs haben. – Fragen Sie, zu welchen Terminen/Zeiten die Sprachschule einen Kurs in Ihrer Wunschsprache anbietet. – Fragen Sie auch nach den Kursgebühren und der Kursdauer. – Bitten Sie um eine Antwort. – Denken Sie an die passende Anrede und den Gruss am Ende.","instruction_en":"选一门你想学的语言，给语言学校写一条消息：哪门语言、你什么时候有空、每周有几次时间、他们提供哪些上课日期/时间、课程费用和时长，请对方回复，并使用合适的称呼和结束语。参考答案依照官方答案。","phrases":["… Damen und Herren,","ich würde gern …","Ich … und …","Bitte teilen Sie mir mit, …","Auch müsste ich wissen, …","Mit …","**LERNTIPP** Was sagt man in dieser Situation? Notieren und lernen Sie nicht nur einzelne neue Wörter. Wenn Sie sich zu verschiedenen Situationen passende Sätze und Ausdrücke aufschreiben, fühlen Sie sich in Gesprächen sicherer. Benutzen Sie zum Beispiel Karteikärtchen und schreiben Sie eine Situation oder ein Thema auf die Vorderseite: «nachfragen». Schreiben Sie Beispiele zum Thema auf die Rückseite und lernen Sie diese auswendig: «Was meinen Sie mit …?», «Was bedeutet …?» … Diese Methode eignet sich auch gut, wenn Sie sich auf ein Gespräch vorbereiten möchten. Überlegen Sie, was Sie sagen oder fragen möchten und was der Gesprächspartner sagen oder fragen könnte. Sicher können Sie während des Gesprächs einen Ihrer geübten Sätze anwenden."],"items":[{"label":"9","text":"","open":true,"solution":"**Sehr geehrte** Damen und Herren, ich würde gern **Neugriechisch lernen**. Ich **habe von Montag bis Donnerstag abends Zeit** und **könnte zweimal pro Woche kommen**. Bitte teilen Sie mir mit, **zu welchen Zeiten Sie einen Neugriechisch-Kurs anbieten**. Auch müsste ich wissen, **wie viel der Kurs kostet und wie lange er dauert**. **Ich bitte Sie um eine kurze Antwort.** Mit **freundlichen Grüssen** …","en":"尊敬的女士们、先生们：我想学现代希腊语。我周一到周四晚上有空，每周可以来两次。请告诉我，贵校在什么时间开设现代希腊语课程。我还需要知道课程费用是多少、课程持续多长时间。请您简短回复。此致敬礼……","why":"正式信函：*Sehr geehrte Damen und Herren* … *Mit freundlichen Grüssen*。这些问题都是间接疑问句（*zu welchen Zeiten …, wie viel …, wie lange …*）：动词放在句末。"}]}]}]},{"id":"04-zu-infinitiv-bewerbung","no":4,"title":"Infinitiv mit zu · Bewerbung · Test Lektion 5","title_en":"带 zu 的不定式、求职信、关于工作的闲聊 · 第 5 课测试","added":"2026-11-12","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 5","sources":[{"id":"hueber","title":"Hueber：Schritte plus Neu 5 Schweiz, Lösungen Arbeitsbuch（官方答案，Lektion 5）","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Loesungen_AB.pdf"},{"id":"g98","title":"grammis：Verben mit einem Infinitiv mit oder ohne zu（情态动词不带 zu；brauchen 带 zu）","url":"https://grammis.ids-mannheim.de/fragen/98"},{"id":"g6865","title":"grammis：Vertiefung: Infinitivsätze（带 zu 的不定式句）","url":"https://grammis.ids-mannheim.de/progr@mm/6865"},{"id":"g4069","title":"grammis：Verbflexion（zu 放在前缀和动词之间：anzurufen）","url":"https://grammis.ids-mannheim.de/progr@mm/4069"},{"id":"g6393","title":"grammis：Alternation von zu- und dass-Komplementen（dass 从句或 zu + 不定式）","url":"https://grammis.ids-mannheim.de/korpusgrammatik/6393"},{"id":"g299310","title":"grammis：während（Präposition，支配第二格）","url":"https://grammis.ids-mannheim.de/praepositionen/299310"},{"id":"prep","title":"grammis：Präpositionalphrase（介词及其支配的格）","url":"https://grammis.ids-mannheim.de/kontrastive-grammatik/5747"}],"pages":[{"page":"AB 140","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"赶快开始写求职信吧！","exercises":[{"no":"1","tag":"A1","instruction":"Ich habe leider keine Zeit …","instruction_en":"可惜我没有时间……","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"用方框里的一个动词补全每个句子。每个动词只用一次；划掉的那个已用在例句中。","box":["mitzuarbeiten","auszuschalten","zu erklären","mitzukommen","zu sein","zu gehen"],"box_used":[5],"box_exact":true,"example":[{"label":"1","text":"Erlaubst du uns, ins Kino **zu gehen**?"}],"items":[{"label":"2","text":"Vergesst bitte nicht, den Herd ___.","gaps":[["auszuschalten"]],"solution":"Vergesst bitte nicht, den Herd **auszuschalten**.","en":"请你们别忘了关掉炉子。","why":"*ausschalten* 是可分动词，所以 *zu* 放在前缀和动词之间：*aus**zu**schalten*。","source":"g4069"},{"label":"3","text":"Ich habe Angst, nachts allein ___.","gaps":[["zu sein"]],"solution":"Ich habe Angst, nachts allein **zu sein**.","en":"我害怕晚上一个人待着。","why":"*Angst haben* + *zu* + 不定式；*sein* 是简单动词，所以 *zu* 放在它前面。","source":"g6865"},{"label":"4","text":"Nein, es ist nicht zu stressig, in einem Verein ___.","gaps":[["mitzuarbeiten"]],"solution":"Nein, es ist nicht zu stressig, in einem Verein **mitzuarbeiten**.","en":"不，在社团里帮忙压力并不太大。","why":"*Es ist* + 形容词 + *zu* + 不定式。*mitarbeiten* 是可分动词：*mit**zu**arbeiten*。（这里第一个 *zu* 的意思是“太”。）","source":"g4069"},{"label":"5","text":"Ich habe leider keine Zeit, Ihnen den Weg ___.","gaps":[["zu erklären"]],"solution":"Ich habe leider keine Zeit, Ihnen den Weg **zu erklären**.","en":"很抱歉，我没有时间给您指路。","why":"*keine Zeit haben* + *zu* + 不定式。*erklären* 不是可分动词（*er-* 是不可分前缀），所以 *zu* 放在它前面。","source":"g4069"},{"label":"6","text":"Ich habe heute keine Lust, ins Training ___.","gaps":[["mitzukommen"]],"solution":"Ich habe heute keine Lust, ins Training **mitzukommen**.","en":"我今天不想一起去训练。","why":"*keine Lust haben* + *zu* + 不定式；*mitkommen* 是可分动词：*mit**zu**kommen*。","source":"g4069"}]},{"no":"1","part":"b","part_instruction":"Nach welchen Ausdrücken folgt *zu*? Markieren Sie in a wie im Beispiel.","part_instruction_en":"哪些表达后面接 *zu*？写出 a 中每个句子里引出 *zu* 的表达（动词，或动词 + 名词/形容词）。","example":[{"label":"1","text":"**Erlaubst** du uns, ins Kino zu gehen?"}],"items":[{"label":"2","text":"Vergesst bitte nicht, den Herd auszuschalten. → ___","gaps":[["Vergesst","Vergesst bitte nicht","vergessen","vergesst nicht"]],"solution":"Vergesst bitte nicht, den Herd auszuschalten. → **Vergesst**","en":"请你们别忘了关掉炉子。→ 忘记","why":"动词 *vergessen*（这里是 *Vergesst*）后面接 *zu* + 不定式。","source":"hueber"},{"label":"3","text":"Ich habe Angst, nachts allein zu sein. → ___","gaps":[["habe Angst","Angst haben","Ich habe Angst","Angst"]],"solution":"Ich habe Angst, nachts allein zu sein. → **habe Angst**","en":"我害怕晚上一个人待着。→ 害怕","why":"*haben* + 名词（*Angst, Lust, Zeit, Interesse*）后面接 *zu* + 不定式。","source":"hueber"},{"label":"4","text":"Nein, es ist nicht zu stressig, in einem Verein mitzuarbeiten. → ___","gaps":[["ist nicht zu stressig","es ist nicht zu stressig","ist stressig","stressig sein","es ist stressig","stressig"]],"solution":"Nein, es ist nicht zu stressig, in einem Verein mitzuarbeiten. → **ist nicht zu stressig**","en":"不，在社团里帮忙压力并不太大。→ 压力（不太）大","why":"*Es ist* + 形容词后面接 *zu* + 不定式。","source":"hueber"},{"label":"5","text":"Ich habe leider keine Zeit, Ihnen den Weg zu erklären. → ___","gaps":[["habe leider keine Zeit","habe keine Zeit","keine Zeit haben","Zeit haben","keine Zeit","Zeit"]],"solution":"Ich habe leider keine Zeit, Ihnen den Weg zu erklären. → **habe leider keine Zeit**","en":"很抱歉，我没有时间给您指路。→ （没）有时间","why":"*Zeit haben*（这里是 *keine Zeit*）后面接 *zu* + 不定式。","source":"hueber"},{"label":"6","text":"Ich habe heute keine Lust, ins Training mitzukommen. → ___","gaps":[["habe heute keine Lust","habe keine Lust","keine Lust haben","Lust haben","keine Lust","Lust"]],"solution":"Ich habe heute keine Lust, ins Training mitzukommen. → **habe heute keine Lust**","en":"我今天不想一起去训练。→ （没）有兴趣","why":"*Lust haben*（这里是 *keine Lust*）后面接 *zu* + 不定式。","source":"hueber"}]},{"no":"1","part":"c","part_instruction":"Wo steht *zu*? Ergänzen Sie die Tabelle mit den Sätzen aus a.","part_instruction_en":"*zu* 放在哪里？表格有三栏：句子的开头、中间部分，然后是带 *zu* 的动词。把 a 中含可分动词的句子（2、4、6）填进表格，写出最后一栏。动词的各个部分写在括号里。","example":[{"label":"1","text":"Erlaubst du uns, | ins Kino | **zu gehen**? (gehen)"}],"items":[{"label":"2","text":"Vergesst bitte nicht, | den Herd | ___. (aus·schalten)","gaps":[["auszuschalten"]],"solution":"Vergesst bitte nicht, | den Herd | **auszuschalten**. (aus·schalten)","en":"请你们别忘了 | 把炉子 | 关掉。","why":"可分动词：*zu* 放在 *aus* 和 *schalten* 之间，整个写成一个词。","source":"g4069"},{"label":"4","text":"Nein, es ist nicht zu stressig, | in einem Verein | ___. (mit·arbeiten)","gaps":[["mitzuarbeiten"]],"solution":"Nein, es ist nicht zu stressig, | in einem Verein | **mitzuarbeiten**. (mit·arbeiten)","en":"不，压力并不太大 | 在社团里 | 帮忙。","why":"可分动词：*mit* + *zu* + *arbeiten*，连写成一个词。","source":"g4069"},{"label":"6","text":"Ich habe heute keine Lust, | ins Training | ___. (mit·kommen)","gaps":[["mitzukommen"]],"solution":"Ich habe heute keine Lust, | ins Training | **mitzukommen**. (mit·kommen)","en":"我今天没兴趣 | 去训练 | 一起去。","why":"可分动词：*mit* + *zu* + *kommen*，连写成一个词。","source":"g4069"}]},{"no":"2","tag":"A1","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"哪个是对的？如果句子需要 *zu*，就输入 *zu*；如果什么都不需要，就输入 *–*（短横线）。","example":[{"label":"a","text":"Ich höre nicht auf, nach meinem Traumjob **zu** suchen."}],"items":[{"label":"b","text":"Möchten Sie nicht auch in Ihrem Traumberuf ___ arbeiten?","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Möchten Sie nicht auch in Ihrem Traumberuf **–** arbeiten?","en":"您不也想从事您梦想的职业吗？","why":"情态动词（*möchten*）之后，不定式从不带 *zu*。","source":"g98"},{"label":"c","text":"Ich könnte mir gut vorstellen, ein Handwerk ___ lernen.","gaps":[["zu"]],"solution":"Ich könnte mir gut vorstellen, ein Handwerk **zu** lernen.","en":"我完全可以想象去学一门手艺。","why":"*sich vorstellen können* 在逗号后引出第二个分句，用 *zu* + 不定式。*könnte* 只属于 *vorstellen*。","source":"g6865"},{"label":"d","text":"Mit einer Ausbildung als Handwerker kann man einen guten Arbeitsplatz ___ finden.","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Mit einer Ausbildung als Handwerker kann man einen guten Arbeitsplatz **–** finden.","en":"有了手工艺人的职业培训，就能找到一份好工作。","why":"情态动词 *kann* + 不带 *zu* 的不定式。","source":"g98"},{"label":"e","text":"Könnten Sie mir bei der Berufswahl ___ helfen?","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Könnten Sie mir bei der Berufswahl **–** helfen?","en":"您能帮我选择职业吗？","why":"*Könnten* 是情态动词（*können* 的第二虚拟式）：不加 *zu*。","source":"g98"},{"label":"f","text":"Es ist ziemlich stressig, sich über die beruflichen Möglichkeiten ___ informieren.","gaps":[["zu"]],"solution":"Es ist ziemlich stressig, sich über die beruflichen Möglichkeiten **zu** informieren.","en":"要了解各种职业发展的可能性，压力挺大的。","why":"*Es ist* + 形容词（*stressig*）+ *zu* + 不定式。","source":"g6865"}]},{"no":"3","tag":"A1","marker":"◇","instruction":"Ergänzen Sie: *zu* oder *–*.","instruction_en":"用 *zu* 填空；如果不缺任何词，就输入 *–*（短横线）。","example":[{"label":"a","text":"Ich habe schon einmal angefangen, das Bewerbungsgespräch vor**zu**bereiten."}],"items":[{"label":"b","text":"Wir dürfen den Geburtstag der Chefin nicht ___ vergessen!","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Wir dürfen den Geburtstag der Chefin nicht **–** vergessen!","en":"我们可不能忘了女老板的生日！","why":"情态动词 *dürfen* + 不带 *zu* 的不定式。","source":"g98"},{"label":"c","text":"Es ist nicht leicht, eine Stelle in seinem Traumjob ___ finden.","gaps":[["zu"]],"solution":"Es ist nicht leicht, eine Stelle in seinem Traumjob **zu** finden.","en":"在自己梦想的行业里找到一个职位并不容易。","why":"*Es ist nicht leicht* + *zu* + 不定式。","source":"g6865"},{"label":"d","text":"Ich würde am liebsten in einem Team ___ arbeiten.","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Ich würde am liebsten in einem Team **–** arbeiten.","en":"我最想在团队里工作。","why":"*würde* + 不定式（第二虚拟式）的用法和情态动词一样：不加 *zu*。","source":"g98"},{"label":"e","text":"Hast du vielleicht kurz Zeit, mir bei meiner Bewerbung ___ helfen?","gaps":[["zu"]],"solution":"Hast du vielleicht kurz Zeit, mir bei meiner Bewerbung **zu** helfen?","en":"你有没有一点时间，帮我弄一下求职申请？","why":"*Zeit haben* + *zu* + 不定式。","source":"g6865"},{"label":"f","text":"Kannst du dir eine Lehre im Büro vor ___ stellen?","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Kannst du dir eine Lehre im Büro vor **–** stellen?","en":"你能想象在办公室当学徒吗？","why":"*Kannst* 是情态动词，所以中间不加任何东西：*vorstellen* 写成一个词。","source":"g98"}]}]},{"page":"AB 141","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"赶快开始写求职信吧！","exercises":[{"no":"4","instruction":"Schreiben Sie Sätze.","instruction_en":"写出关于你职业生活的句子：把左边方框里的一个表达和右边方框里的一个活动组合起来。划掉的词已用在例句中。参考答案只是一种可能。","box":["(keine) Lust haben","möchten","hoffen","Freude machen","können","sich vorstellen können","würde … gern","anstrengend sein","…","ein halbes Jahr um die Welt reisen","am Abend arbeiten","(nicht) immer dasselbe machen","sehr gut selbstständig arbeiten","mit netten Kollegen zusammenarbeiten","Neues lernen","wenig Freizeit haben"],"box_used":[0,1,10],"example":[{"label":"Beispiel","text":"Ich habe keine Lust, am Abend **zu arbeiten**. Ich möchte in meinem Berufsleben …"}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich möchte in meinem Berufsleben nicht immer dasselbe machen. Ich hoffe, mit netten Kollegen zusammenzuarbeiten. Es macht mir Freude, Neues zu lernen. Ich kann sehr gut selbstständig arbeiten. Es ist anstrengend, wenig Freizeit zu haben. Ich würde gern ein halbes Jahr um die Welt reisen.","en":"在我的职业生涯中，我不想一直做同样的事。我希望能和友善的同事一起工作。学新东西让我很开心。我能很好地独立工作。空闲时间少很累人。我很想花半年时间环游世界。","why":"在 *hoffen, Freude machen, sich vorstellen können, anstrengend sein, Lust haben* 之后用 *zu* + 不定式（可分动词：*zusammen**zu**arbeiten*）。在 *möchten, können, würde … gern* 之后不用 *zu*。","source":"g98"}]},{"no":"5","instruction":"Ordnen Sie zu und schreiben Sie Sätze mit *zu*.","instruction_en":"给每句话配上方框里的一个动词，并用 *zu* + 不定式写一个句子。划掉的动词已用在例句中。","box":["sich vorstellen können","versuchen","aufhören","versprechen","vorhaben"],"box_used":[1],"example":[{"label":"a","lead":"Morgen will ich pünktlich sein. Vielleicht!","text":"versuchen: Morgen versuche ich, pünktlich **zu sein**."}],"items":[{"label":"b","lead":"Ich hole dich morgen ab. Ganz sicher.","text":"","accept":["Ich verspreche, dich morgen abzuholen.","Ich verspreche dir, dich morgen abzuholen.","versprechen: Ich verspreche, dich morgen abzuholen."],"solution":"**Ich verspreche, dich morgen abzuholen.**","en":"我答应明天去接你。","why":"“一定” = 一个承诺：*versprechen*。*abholen* 是可分动词：*ab**zu**holen*。","source":"hueber"},{"label":"c","lead":"Einen interessanten Job finden! Das ist mein Plan.","text":"","accept":["Ich habe vor, einen interessanten Job zu finden.","vorhaben: Ich habe vor, einen interessanten Job zu finden."],"solution":"**Ich habe vor, einen interessanten Job zu finden.**","en":"我打算找一份有意思的工作。","why":"计划 = *vorhaben*：*Ich habe vor, … zu finden.* 前缀 *vor* 放到主句末尾。","source":"hueber"},{"label":"d","lead":"Ein Handwerk lernen? Ja, warum eigentlich nicht?","text":"","accept":["Ich kann mir vorstellen, ein Handwerk zu lernen.","Ich kann mir gut vorstellen, ein Handwerk zu lernen.","sich vorstellen können: Ich kann mir vorstellen, ein Handwerk zu lernen."],"solution":"**Ich kann mir vorstellen, ein Handwerk zu lernen.**","en":"我可以想象去学一门手艺。","why":"“为什么不呢？” = 你能想象这件事：*Ich kann mir vorstellen, … zu lernen.*","source":"hueber"},{"label":"e","lead":"Ich arbeite als Pflegefachmann. Aber nur noch bis Ende Monat.","text":"","accept":["Ich höre Ende Monat auf, als Pflegefachmann zu arbeiten.","Ende Monat höre ich auf, als Pflegefachmann zu arbeiten.","aufhören: Ich höre Ende Monat auf, als Pflegefachmann zu arbeiten."],"solution":"**Ich höre Ende Monat auf, als Pflegefachmann zu arbeiten.**","en":"我月底就不再做护士的工作了。","why":"“只到月底” = 停止：*aufhören*，*auf* 放在主句末尾、逗号之前。","source":"hueber"}]},{"no":"6","instruction":"Markieren Sie noch neun Wörter und ordnen Sie zu.","instruction_en":"在字母方格里再找出九个词，把它们填进招聘广告 A–C 中。圈出来的词（*Bewerbung, Tätigkeit*）是例子。按照句子需要的形式写出每个词（名词首字母大写）。","reading":[{"label":"Buchstabengitter","text":"AUFGABENSGBESCHÄFTIGSTIBEWERBUNGTERWARTENZTÄTIGKEIT\nBEWERBUNGSUNTERLAGENZYTWHANDELUTPOÜKENNTNISSENKWAQ\nUNTERSTÜTZUNGMUSJÄMTILVORAUSSETZUNGDUQSCHRIFTLICHLW"},{"label":"A  Heimpflegedienst Bachmann","text":"Wir suchen für 15 Stunden pro Woche … (1) für den Patientenfahrdienst.\n… (2) für die Tätigkeit ist: + Führerausweis Kategorie B + … (3) in Erster Hilfe + Freude an der Arbeit mit Menschen\nEs … (4) Sie: + interessante … (5) + Weiterbildungsmöglichkeiten + ein angenehmes Betriebsklima\nBitte schicken Sie Ihre Bewerbung an personal@hpfd-bachmann.ch"},{"label":"B","text":"Detailhandelsassistent/in für unser kleines Modegeschäft gesucht!\nErfahrung im … (1) und Verkauf von Vorteil. Wenden Sie sich bei Fragen … (2) oder telefonisch an Frau Kleinert: kleinert@neuemode.ch / 031 330 110 10."},{"label":"C","text":"HAST DU HANDWERKLICHES TALENT?\n… (1) du dich gern mit Holz? Dann komm zu uns! Wir bieten dir eine Lehrstelle als Schreiner/in EFZ.\nSchick deine … (2) noch heute an: Clemens Meier (cl.meier@schreinerei-meier.ch)"}],"example":[{"label":"A","text":"… für die **Tätigkeit** ist: … Bitte schicken Sie Ihre **Bewerbung** an personal@hpfd-bachmann.ch"}],"items":[{"label":"A1","text":"Wir suchen für 15 Stunden pro Woche ___ für den Patientenfahrdienst.","gaps":[["Unterstützung"]],"solution":"Wir suchen für 15 Stunden pro Woche **Unterstützung** für den Patientenfahrdienst.","en":"我们为病人接送服务寻找帮手，每周 15 小时。","why":"*die Unterstützung* = 支持、帮助；这里指提供帮助的人。","source":"hueber"},{"label":"A2","text":"___ für die Tätigkeit ist: Führerausweis Kategorie B","gaps":[["Voraussetzung"]],"solution":"**Voraussetzung** für die Tätigkeit ist: Führerausweis Kategorie B","en":"从事这项工作的前提条件：B 类驾照","why":"*die Voraussetzung* = 要求、前提条件。*der Führerausweis* 是瑞士用语，即驾照。","source":"hueber"},{"label":"A3","text":"+ ___ in Erster Hilfe","gaps":[["Kenntnisse"]],"solution":"+ **Kenntnisse** in Erster Hilfe","en":"+ 急救知识","why":"*Kenntnisse in* + 第三格 = ……方面的知识 / 技能。","source":"hueber"},{"label":"A4","text":"Es ___ Sie: interessante Aufgaben, Weiterbildungsmöglichkeiten, ein angenehmes Betriebsklima","gaps":[["erwarten"]],"solution":"Es **erwarten** Sie: interessante Aufgaben, Weiterbildungsmöglichkeiten, ein angenehmes Betriebsklima","en":"等待您的是：有趣的任务、进修机会、愉快的工作氛围","why":"*Es erwarten Sie …* = “等待您的是……”；*es* 只是占据第一位，动词和后面的复数主语保持一致。","source":"hueber"},{"label":"A5","text":"+ interessante ___","gaps":[["Aufgaben"]],"solution":"+ interessante **Aufgaben**","en":"+ 有趣的任务","why":"*die Aufgabe, die Aufgaben* = 任务；*interessante* 表明是复数。","source":"hueber"},{"label":"B1","text":"Erfahrung im ___ und Verkauf von Vorteil.","gaps":[["Handel"]],"solution":"Erfahrung im **Handel** und Verkauf von Vorteil.","en":"有零售和销售经验者优先。","why":"*der Handel* = 贸易、零售；*im* = *in dem*。*von Vorteil* = 是优势。","source":"hueber"},{"label":"B2","text":"Wenden Sie sich bei Fragen ___ oder telefonisch an Frau Kleinert.","gaps":[["schriftlich"]],"solution":"Wenden Sie sich bei Fragen **schriftlich** oder telefonisch an Frau Kleinert.","en":"如有问题，请以书面或电话方式联系 Kleinert 女士。","why":"*schriftlich oder telefonisch* = 以书面或电话方式。","source":"hueber"},{"label":"C1","text":"___ du dich gern mit Holz?","gaps":[["Beschäftigst"]],"solution":"**Beschäftigst** du dich gern mit Holz?","en":"你喜欢和木头打交道吗？","why":"*sich beschäftigen mit* = 忙于、从事；*du beschäftigst dich*。它放在是非疑问句的开头，所以首字母大写。","source":"hueber"},{"label":"C2","text":"Schick deine ___ noch heute an: Clemens Meier","gaps":[["Bewerbungsunterlagen"]],"solution":"Schick deine **Bewerbungsunterlagen** noch heute an: Clemens Meier","en":"今天就把你的求职材料寄给：Clemens Meier","why":"*die Bewerbungsunterlagen*（复数）= 简历、证书和求职信的统称。","source":"hueber"}]}]},{"page":"AB 142","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"赶快开始写求职信吧！","exercises":[{"no":"7","tag":"A2","instruction":"Ergänzen Sie in der richtigen Form: *brauchen – müssen*.","instruction_en":"用 *brauchen* 或 *müssen* 的正确形式填空。提示：*brauchen* 和 *zu* + 不定式以及否定词或 *nur* 连用；*müssen* 从不带 *zu*。","example":[{"label":"a","text":"Ich **brauche** nur die neuen Wörter zu lernen, dann schaffe ich die Prüfung schon."}],"items":[{"label":"b","text":"Dein Zeugnis ist doch so gut. Du ___ dir wirklich keine Gedanken um einen Job zu machen.","gaps":[["brauchst"]],"solution":"Dein Zeugnis ist doch so gut. Du **brauchst** dir wirklich keine Gedanken um einen Job zu machen.","en":"你的成绩单那么好。你真的不必为工作操心。","why":"否定词（*keine*）+ *zu machen*：*brauchen … zu* = *nicht müssen*。","source":"g98"},{"label":"c","text":"Wenn sie nur Teilzeit arbeitet, dann ___ sie nicht den ganzen Tag am Computer sitzen.","gaps":[["muss"]],"solution":"Wenn sie nur Teilzeit arbeitet, dann **muss** sie nicht den ganzen Tag am Computer sitzen.","en":"如果她只做兼职，就不必一整天坐在电脑前。","why":"不定式 *sitzen* 前面没有 *zu*，所以动词用 *müssen*：*sie muss … sitzen*。","source":"g98"},{"label":"d","text":"Wenn wir für drei Monate ins Ausland reisen wollen, dann ___ wir jetzt viel Geld sparen.","gaps":[["müssen"]],"solution":"Wenn wir für drei Monate ins Ausland reisen wollen, dann **müssen** wir jetzt viel Geld sparen.","en":"如果我们想出国旅行三个月，现在就得存很多钱。","why":"没有 *zu*，也没有否定词：表示义务，所以用 *müssen*。","source":"g98"}]},{"no":"8","tag":"A2","instruction":"Mein Traumjob. Schreiben Sie Sätze mit *brauchen … zu*.","instruction_en":"我的梦想职业。用 *brauchen … zu* + 不定式写句子（= 不必 / 只需要）。","example":[{"label":"a","lead":"(nicht früh aufstehen)","text":"In meinem Traumjob **brauche ich nicht früh aufzustehen**."}],"items":[{"label":"b","lead":"(keine langweiligen Aufgaben übernehmen)","text":"","accept":["Ich brauche keine langweiligen Aufgaben zu übernehmen.","In meinem Traumjob brauche ich keine langweiligen Aufgaben zu übernehmen."],"solution":"**Ich brauche keine langweiligen Aufgaben zu übernehmen.**","en":"我不必承担无聊的任务。","why":"*brauchen* 在第二位，*zu übernehmen* 在句末。*übernehmen* 在这里不是可分动词，所以 *zu* 放在它前面。","source":"g98"},{"label":"c","lead":"(keine Überstunden machen)","text":"","accept":["Ich brauche keine Überstunden zu machen.","In meinem Traumjob brauche ich keine Überstunden zu machen."],"solution":"**Ich brauche keine Überstunden zu machen.**","en":"我不必加班。","why":"*keine* + *brauchen … zu* = 没有义务。","source":"g98"},{"label":"d","lead":"(nur arbeiten, wenn ich Lust dazu habe)","text":"","accept":["Ich brauche nur zu arbeiten, wenn ich Lust dazu habe.","In meinem Traumjob brauche ich nur zu arbeiten, wenn ich Lust dazu habe."],"solution":"**Ich brauche nur zu arbeiten, wenn ich Lust dazu habe.**","en":"我只在有兴致的时候才需要工作。","why":"*nur brauchen … zu* = 只需要。*zu arbeiten* 在 *wenn* 从句之前结束主句。","source":"g98"},{"label":"e","lead":"(nicht mit unfreundlichen Kollegen zusammenarbeiten)","text":"","accept":["Ich brauche nicht mit unfreundlichen Kollegen zusammenzuarbeiten.","In meinem Traumjob brauche ich nicht mit unfreundlichen Kollegen zusammenzuarbeiten."],"solution":"**Ich brauche nicht mit unfreundlichen Kollegen zusammenzuarbeiten.**","en":"我不必和不友善的同事一起工作。","why":"*zusammenarbeiten* 是可分动词：*zusammen**zu**arbeiten*，写成一个词。","source":"g4069"}]},{"no":"9","tag":"A4","instruction":"Ein Bewerbungsschreiben","instruction_en":"一封求职信","part":"a","part_instruction":"Lesen Sie und ordnen Sie.","part_instruction_en":"阅读信的各个部分，把它们按正确的顺序排列：写出每个部分的编号（1–8）。这里按照课本印出的顺序用字母 A–H 标出各部分；B 是例子。","example":[{"label":"B","text":"Bewerbung als Verkäufer von E-Bikes → **1**"}],"items":[{"label":"A","text":"Es fällt mir leicht, neue Dinge zu lernen. Ausserdem macht es mir Freude, Kunden zu beraten. Deshalb wäre ich gern als Verkäufer bei Ihnen tätig. → ___","gaps":[["5"]],"solution":"Es fällt mir leicht, neue Dinge zu lernen. Ausserdem macht es mir Freude, Kunden zu beraten. Deshalb wäre ich gern als Verkäufer bei Ihnen tätig. → **5**","en":"学新东西对我来说很容易。此外，我也喜欢为顾客提供咨询。所以我很想在贵公司当售货员。→ 5","why":"说明你为什么想要这份工作的部分放在你的经历（4）之后、结尾的请求（6）之前。","source":"hueber"},{"label":"C","text":"Freundliche Grüsse / Tibor Kelemen → ___","gaps":[["7"]],"solution":"Freundliche Grüsse / Tibor Kelemen → **7**","en":"此致敬礼 / Tibor Kelemen → 7","why":"结尾的问候语和你的名字放在最后一句之后。","source":"hueber"},{"label":"D","text":"Mit grossem Interesse habe ich Ihr Inserat gelesen und bewerbe mich um die freie Stelle als Verkäufer von E-Bikes. → ___","gaps":[["3"]],"solution":"Mit grossem Interesse habe ich Ihr Inserat gelesen und bewerbe mich um die freie Stelle als Verkäufer von E-Bikes. → **3**","en":"我怀着极大的兴趣读了贵公司的招聘广告，现申请电动自行车售货员这一空缺职位。→ 3","why":"称呼之后的第一句说明你申请的是哪个职位。","source":"hueber"},{"label":"E","text":"Über eine Einladung zu einem persönlichen Gespräch würde ich mich freuen. → ___","gaps":[["6"]],"solution":"Über eine Einladung zu einem persönlichen Gespräch würde ich mich freuen. → **6**","en":"如能收到面试邀请，我将十分高兴。→ 6","why":"求职信标准的最后一句。","source":"hueber"},{"label":"F","text":"Beilagen: Lebenslauf, Arbeitszeugnisse → ___","gaps":[["8"]],"solution":"Beilagen: Lebenslauf, Arbeitszeugnisse → **8**","en":"附件：简历、工作证明 → 8","why":"*Beilagen*（附件）放在最末尾，名字下方。","source":"hueber"},{"label":"G","text":"Sehr geehrte Damen und Herren → ___","gaps":[["2"]],"solution":"Sehr geehrte Damen und Herren → **2**","en":"尊敬的女士们、先生们 → 2","why":"称呼放在事由行之后。在瑞士，称呼后面不加逗号。","source":"hueber"},{"label":"H","text":"Wie Sie meinen Unterlagen entnehmen können, habe ich nach meinem Sekundarschulabschluss die Ausbildung zum Fahrradmechaniker bei der Firma «Velo-XL» gemacht. Danach war ich zwei Jahre als Angestellter in einem Velogeschäft tätig und konnte auch erste Erfahrungen im Verkauf sammeln. → ___","gaps":[["4"]],"solution":"Wie Sie meinen Unterlagen entnehmen können, habe ich nach meinem Sekundarschulabschluss die Ausbildung zum Fahrradmechaniker bei der Firma «Velo-XL» gemacht. Danach war ich zwei Jahre als Angestellter in einem Velogeschäft tätig und konnte auch erste Erfahrungen im Verkauf sammeln. → **4**","en":"正如您从我的材料中可以看到的，我在中学毕业后在 «Velo-XL» 公司接受了自行车机械师的职业培训。之后我在一家自行车店当了两年雇员，还积累了最初的销售经验。→ 4","why":"你的职业培训和经历放在开头那句之后。","source":"hueber"}]}]},{"page":"AB 143","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"赶快开始写求职信吧！","exercises":[{"no":"9","part":"b","part_instruction":"Ergänzen Sie das Bewerbungsschreiben. Hilfe finden Sie in a.","part_instruction_en":"补全这封求职信。你可以在 a 中找到帮助。","reading":[{"label":"Lerntipp","text":"Ein Bewerbungsschreiben muss fehlerfrei sein! Notieren Sie zuerst Ihre typischen Fehler. Überprüfen Sie dann Ihren Text pro Fehlertyp einmal. Lassen Sie Ihre Bewerbung am Ende noch einmal von einem Muttersprachler Korrektur lesen."}],"example":[{"label":"1","text":"Bewerbung **als** Physiotherapeutin im Altersheim"}],"items":[{"label":"2","text":"Sehr ___ Frau Zerlich","gaps":[["geehrte"]],"solution":"Sehr **geehrte** Frau Zerlich","en":"尊敬的 Zerlich 女士","why":"*Sehr geehrte Frau …*、*Sehr geehrter Herr …*：词尾随对方的性别变化。","source":"hueber"},{"label":"3","text":"___ habe ich Ihr Stelleninserat gelesen und bewerbe mich um die Stelle als Physiotherapeutin.","gaps":[["Mit grossem Interesse"]],"solution":"**Mit grossem Interesse** habe ich Ihr Stelleninserat gelesen und bewerbe mich um die Stelle als Physiotherapeutin.","en":"我怀着极大的兴趣读了贵机构的招聘广告，现申请物理治疗师一职。","why":"a 中的固定开头语；它占据第一位，所以动词 *habe* 紧随其后。","source":"hueber"},{"label":"4","text":"Wie Sie ___ entnehmen können, war ich in Polen nach meiner Ausbildung zur Physiotherapeutin vier Jahre in einem Spital in Lodz tätig.","gaps":[["meinen Unterlagen"]],"solution":"Wie Sie **meinen Unterlagen** entnehmen können, war ich in Polen nach meiner Ausbildung zur Physiotherapeutin vier Jahre in einem Spital in Lodz tätig.","en":"正如您从我的材料中可以看到的，我在波兰完成物理治疗师的职业培训后，在罗兹的一家医院工作了四年。","why":"*etwas (Dativ) entnehmen* = 从某物中看出：*meinen Unterlagen* 是复数第三格。","source":"hueber"},{"label":"5","text":"Danach habe ich zwei Jahre in der Praxis *Kunz & Rosenthal* gearbeitet. Dort konnte ich auch ___ im Bereich der Sportmedizin sammeln.","gaps":[["Erfahrungen","erste Erfahrungen"]],"solution":"Danach habe ich zwei Jahre in der Praxis *Kunz & Rosenthal* gearbeitet. Dort konnte ich auch **Erfahrungen** im Bereich der Sportmedizin sammeln.","en":"之后我在 Kunz & Rosenthal 诊所工作了两年。在那里我也积累了运动医学方面的经验。","why":"*Erfahrungen sammeln* = 积累经验。","source":"hueber"},{"label":"6","text":"___ ist Polnisch. Ich spreche aber auch sehr gut Deutsch und Englisch.","gaps":[["Meine Muttersprache"]],"solution":"**Meine Muttersprache** ist Polnisch. Ich spreche aber auch sehr gut Deutsch und Englisch.","en":"我的母语是波兰语。不过我的德语和英语也说得很好。","why":"*die Muttersprache* = 母语；用 *meine* 是因为它是阴性。","source":"hueber"},{"label":"7","text":"Die Stelle in einem Altersheim ist für mich etwas ganz Neues. Es ___ grosse Freude, Neues zu lernen. Ausserdem kümmere ich mich gern um andere Menschen und freue mich auf den Kontakt mit den Bewohnern.","gaps":[["macht mir"]],"solution":"Die Stelle in einem Altersheim ist für mich etwas ganz Neues. Es **macht mir** grosse Freude, Neues zu lernen. Ausserdem kümmere ich mich gern um andere Menschen und freue mich auf den Kontakt mit den Bewohnern.","en":"养老院的这份工作对我来说是全新的事情。学习新东西让我非常开心。此外，我喜欢照顾别人，也很期待和院里的老人们接触。","why":"*Es macht mir Freude, … zu* + 不定式，和 a 中一样。","source":"hueber"},{"label":"8","text":"Über eine Einladung ___ würde ich mich freuen.","gaps":[["zu einem persönlichen Gespräch"]],"solution":"Über eine Einladung **zu einem persönlichen Gespräch** würde ich mich freuen.","en":"如能收到面试邀请，我将十分高兴。","why":"固定的结尾句：*eine Einladung zu* + 第三格。","source":"hueber"},{"label":"9","text":"___ Alina Jankowska","gaps":[["Freundliche Grüsse"]],"solution":"**Freundliche Grüsse** Alina Jankowska","en":"此致敬礼，Alina Jankowska","why":"结尾问候语；瑞士写法 *Grüsse*。","source":"hueber"}]},{"no":"9","part":"c","part_instruction":"Wählen Sie ein Stelleninserat und schreiben Sie eine Bewerbung.","part_instruction_en":"从 Zirkus Tortellini（Tortellini 马戏团）的三则招聘广告中选一则，写一封求职信。使用 a 和 b 中的各个部分。参考答案只是一种可能。","reading":[{"label":"1","text":"Zirkus Tortellini sucht Dompteur/-in\nWir erwarten: + Ausbildung als Tierpfleger/-in + Erfahrung mit wilden Tieren (Tiger, …)\nInfos und Bewerbung bei Zirkusdirektor Flavio Tortellini: flavio.tortellini@zirkus-tortellini.com"},{"label":"2","text":"Sind Sie ein fröhlicher, positiver Mensch? Dann arbeiten Sie bei uns als Clown/-in\nSie haben Berufserfahrung als Kleinkinderzieher/-in oder als Schauspieler/-in? Sie können gut mit Kindern umgehen und haben viele lustige Ideen? Dann sind Sie die Richtige oder der Richtige für uns!\nGleich bewerben bei Zirkusdirektor Flavio Tortellini: flavio.tortellini@zirkus-tortellini.com"},{"label":"3","text":"Wir suchen zwei Artisten für unseren Zirkus.\nSie haben: + eine Ausbildung als Tänzer/-in + erste Berufserfahrung an einem Theater gesammelt oder schon als Artist/-in in einem Zirkus gearbeitet\nSenden Sie Ihre Bewerbung an Zirkusdirektor Flavio Tortellini: flavio.tortellini@zirkus-tortellini.com"}],"example":[{"label":"Beispiel","text":"Sehr geehrter Herr Tortellini / Mit grossem Interesse …"}],"items":[{"label":"1","lead":"Inserat 3: Artist/-in","text":"","open":true,"solution":"Bewerbung als Artistin / Sehr geehrter Herr Tortellini / Mit grossem Interesse habe ich Ihr Stelleninserat gelesen und bewerbe mich um die Stelle als Artistin in Ihrem Zirkus. Wie Sie meinen Unterlagen entnehmen können, habe ich eine Ausbildung als Tänzerin gemacht. Danach habe ich drei Jahre an einem Theater in Bern getanzt und dort erste Erfahrungen auf der Bühne gesammelt. Es macht mir grosse Freude, vor Publikum aufzutreten. Ich kann mir gut vorstellen, mit Ihrem Zirkus durch die Schweiz zu reisen. Über eine Einladung zu einem persönlichen Gespräch würde ich mich freuen. / Freundliche Grüsse / Lara Steiner / Beilagen: Lebenslauf, Arbeitszeugnis","en":"申请杂技演员一职 / 尊敬的 Tortellini 先生 / 我怀着极大的兴趣读了贵马戏团的招聘广告，现申请杂技演员一职。正如您从我的材料中可以看到的，我接受过舞蹈演员的职业培训。之后我在伯尔尼的一家剧院跳了三年舞，在那里积累了最初的舞台经验。在观众面前表演让我非常开心。我完全可以想象和贵马戏团一起在瑞士各地巡演。如能收到面试邀请，我将十分高兴。/ 此致敬礼 / Lara Steiner / 附件：简历、工作证明","why":"和 a 中一样的八个部分；每一部分都回应广告里的一点（舞蹈演员的培训、在剧院的最初经验）。*auf**zu**treten*：*auftreten* 是可分动词。","source":"g4069"}]}]},{"page":"AB 144","heading":"B  Während seines letzten Schuljahres …","heading_en":"在他上学的最后一年里……","exercises":[{"no":"10","tag":"B1","instruction":"Ergänzen Sie in der richtigen Form: *während – innerhalb – ausserhalb*.","instruction_en":"用 *während*（在……期间）、*innerhalb*（在……之内）或 *ausserhalb*（在……之外）填空，并把括号里的词变成正确的形式。这三个词都支配第二格。","example":[{"label":"a","text":"Man sollte schon **während der** (die) Schulzeit Schnupperlehren machen."}],"items":[{"label":"b","lead":"(wenige)","text":"Vielen Dank für Ihre Bewerbung. Sie erhalten ___ Wochen unsere Antwort.","gaps":[["innerhalb weniger"]],"solution":"Vielen Dank für Ihre Bewerbung. Sie erhalten **innerhalb weniger** Wochen unsere Antwort.","en":"感谢您的申请。您将在几周内收到我们的答复。","why":"时间期限 = *innerhalb*；不带冠词的复数第二格：*weniger Wochen*。","source":"prep"},{"label":"c","lead":"(unsere)","text":"Sie rufen ___ Geschäftszeiten an. Diese sind von …","gaps":[["ausserhalb unserer"]],"solution":"Sie rufen **ausserhalb unserer** Geschäftszeiten an. Diese sind von …","en":"您是在我们的营业时间之外打来的。我们的营业时间是从……","why":"在某段时间之外 = *ausserhalb*；复数第二格 *unserer Geschäftszeiten*。","source":"prep"},{"label":"d","lead":"(die)","text":"Sie können sich ___ Wartezeit gern einen Kaffee nehmen.","gaps":[["während der"]],"solution":"Sie können sich **während der** Wartezeit gern einen Kaffee nehmen.","en":"等候期间，您可以随意取一杯咖啡。","why":"与……同时 = *während*；阴性第二格 *der Wartezeit*。","source":"g299310"},{"label":"e","lead":"(die)","text":"Die Firma möchte ihre Ergebnisse ___ nächsten zwei Jahre um 20 % verbessern.","gaps":[["innerhalb der"]],"solution":"Die Firma möchte ihre Ergebnisse **innerhalb der** nächsten zwei Jahre um 20 % verbessern.","en":"公司希望在未来两年内把业绩提高 20%。","why":"时间期限 = *innerhalb*；复数第二格 *der nächsten zwei Jahre*。","source":"prep"}]},{"no":"11","tag":"B2","instruction":"Ordnen Sie zu.","instruction_en":"用方框里的时间介词补全这篇访谈。每个介词只用一次；*während* 在方框里出现了两次。划掉的 *von … an* 已用在例句中。","phrases":["ausserhalb","bei","von … bis","nach","von … an (Beispiel)","Vor","während","während"],"reading":[{"label":"Karrierestart","text":"Technikerin HF Maschinenbau – ein Beruf auch für Mädchen? Interview mit Samira\nKarrierestart: Warum machst du eine Ausbildung zur Maschinenbau-Technikerin?\nKarrierestart: Wie lange dauert die Ausbildung zur Maschinenbau-Technikerin?\nKarrierestart: Wie sieht dein Arbeitstag aus?\nKarrierestart: Welche Erfahrungen hast du als Frau … deiner Arbeit gemacht?"}],"example":[{"label":"d","text":"Ich durfte **von** Anfang **an** selbstständig Probleme lösen."}],"items":[{"label":"a","text":"Technik hat mich schon immer interessiert. Schon ___ meiner Schulzeit habe ich bei einem Elektroinstallateur gearbeitet.","gaps":[["während"]],"solution":"Technik hat mich schon immer interessiert. Schon **während** meiner Schulzeit habe ich bei einem Elektroinstallateur gearbeitet.","en":"我一直对技术很感兴趣。早在上学期间，我就在一位电工那里干过活。","why":"*während* + 第二格（*meiner Schulzeit*）= 在……期间。","source":"g299310"},{"label":"b","text":"Gleich ___ der Schule habe ich ein Praktikum bei einem grossen Energieunternehmen gemacht.","gaps":[["nach"]],"solution":"Gleich **nach** der Schule habe ich ein Praktikum bei einem grossen Energieunternehmen gemacht.","en":"一毕业我就在一家大型能源公司实习。","why":"*nach* + 第三格（*der Schule*）= 在……之后。","source":"prep"},{"label":"c","text":"Aber schon ___ des ersten Jahres lernt man die wichtigsten Dinge kennen.","gaps":[["während"]],"solution":"Aber schon **während** des ersten Jahres lernt man die wichtigsten Dinge kennen.","en":"不过在第一年里就能学到最重要的东西。","why":"*während* + 第二格 *des ersten Jahres*。","source":"g299310"},{"label":"e","text":"___ der Abschlussprüfung muss ich aber trotzdem noch viel lernen.","gaps":[["Vor"]],"solution":"**Vor** der Abschlussprüfung muss ich aber trotzdem noch viel lernen.","en":"不过在结业考试之前，我还是得学很多东西。","why":"*vor* + 第三格（*der Abschlussprüfung*）= 在……之前；位于句首，所以首字母大写。","source":"prep"},{"label":"f","text":"Ich bin ___ morgens ___ zum Feierabend auf dem Gebiet unseres Unternehmens unterwegs und repariere Anlagen.","gaps":[["von"],["bis"]],"solution":"Ich bin **von** morgens **bis** zum Feierabend auf dem Gebiet unseres Unternehmens unterwegs und repariere Anlagen.","en":"我从早到下班都在我们公司的厂区里跑来跑去，维修设备。","why":"*von … bis* = 从……到……；*bis zum Feierabend*（*zum* = *zu dem*）。","source":"prep"},{"label":"g","text":"Welche Erfahrungen hast du als Frau ___ deiner Arbeit gemacht?","gaps":[["bei"]],"solution":"Welche Erfahrungen hast du als Frau **bei** deiner Arbeit gemacht?","en":"作为女性，你在工作中有过哪些经历？","why":"*bei* + 第三格（*deiner Arbeit*）= 在……过程中、在……时。","source":"prep"},{"label":"h","text":"Nur positive! Meine Kollegen und ich treffen uns oft abends, also ___ der Arbeitszeit.","gaps":[["ausserhalb"]],"solution":"Nur positive! Meine Kollegen und ich treffen uns oft abends, also **ausserhalb** der Arbeitszeit.","en":"只有正面的！我和同事们经常在晚上聚会，也就是在工作时间以外。","why":"*ausserhalb* + 第二格（*der Arbeitszeit*）= 在……之外。","source":"prep"}]},{"no":"12","tag":"B2","instruction":"Lesen Sie den Text und schliessen Sie die Lücken 1–6. Welche Lösung (a, b oder c) passt am besten?","instruction_en":"考试练习：阅读这封电子邮件，填写第 1–6 个空。哪个选项（a、b 或 c）最合适？写出这个词（或它的字母）。","reading":[{"label":"E-Mail senden","text":"Sehr (0) Herr Nemati\nVielen Dank (1) Ihre Bewerbung als Automobil-Mechatroniker. Wir freuen uns über Ihr (2) an unserer Firma und laden Sie zu einem Vorstellungsgespräch am 25. Mai um 11.30 Uhr ein. Bitte geben Sie uns (3) der nächsten Tage Bescheid, (4) Sie zu diesem Termin kommen können. Bringen Sie noch folgende (5) mit: den Berufsschulabschluss im Original und Ihr B2-Zertifikat. Für Fragen und weitere Informationen (6) wir Ihnen gern zur Verfügung.\nFreundliche Grüsse\nFranziska Leumann – Garage Leumann"}],"example":[{"label":"0","lead":"a geehrter · b lieber · c freundlicher","text":"Sehr **geehrter** Herr Nemati"}],"items":[{"label":"1","lead":"a um · b für · c bei","text":"Vielen Dank ___ Ihre Bewerbung als Automobil-Mechatroniker.","gaps":[["für","b","b für"]],"solution":"Vielen Dank **für** Ihre Bewerbung als Automobil-Mechatroniker.","en":"感谢您申请汽车机电技师一职。","why":"*Vielen Dank für* + 第四格。","source":"hueber"},{"label":"2","lead":"a Bewerbung · b Interesse · c Mitarbeit","text":"Wir freuen uns über Ihr ___ an unserer Firma …","gaps":[["Interesse","b","b Interesse"]],"solution":"Wir freuen uns über Ihr **Interesse** an unserer Firma …","en":"我们很高兴您对我们公司感兴趣……","why":"*Interesse an* + 第三格 = 对……的兴趣；*Ihr* 和中性名词 *das Interesse* 相配。","source":"hueber"},{"label":"3","lead":"a innerhalb · b ausserhalb · c bis","text":"Bitte geben Sie uns ___ der nächsten Tage Bescheid, …","gaps":[["innerhalb","a","a innerhalb"]],"solution":"Bitte geben Sie uns **innerhalb** der nächsten Tage Bescheid, …","en":"请在接下来几天内告诉我们……","why":"带第二格的时间期限（*der nächsten Tage*）= *innerhalb*。用 *bis* 的话要说 *bis zum …*。","source":"prep"},{"label":"4","lead":"a wenn · b wann · c ob","text":"…, ___ Sie zu diesem Termin kommen können.","gaps":[["ob","c","c ob"]],"solution":"…, **ob** Sie zu diesem Termin kommen können.","en":"……您是否能在这个时间前来。","why":"间接的是非疑问句需要用 *ob*（是否）。","source":"hueber"},{"label":"5","lead":"a Zeugnisse · b Sachen · c Dokumente","text":"Bringen Sie noch folgende ___ mit: den Berufsschulabschluss im Original und Ihr B2-Zertifikat.","gaps":[["Dokumente","c","c Dokumente"]],"solution":"Bringen Sie noch folgende **Dokumente** mit: den Berufsschulabschluss im Original und Ihr B2-Zertifikat.","en":"另外请带上以下文件：职业学校毕业证书原件和您的 B2 证书。","why":"证书和文凭都属于 *Dokumente*；*Zeugnisse* 不能同时涵盖 B2 证书，而 *Sachen* 对正式信函来说太含糊。","source":"hueber"},{"label":"6","lead":"a stellen · b stehen · c haben","text":"Für Fragen und weitere Informationen ___ wir Ihnen gern zur Verfügung.","gaps":[["stehen","b","b stehen"]],"solution":"Für Fragen und weitere Informationen **stehen** wir Ihnen gern zur Verfügung.","en":"如有问题或需要更多信息，我们随时乐意为您提供帮助。","why":"固定说法：*jemandem zur Verfügung stehen* = 随时为某人提供帮助。","source":"hueber"}]}]},{"page":"AB 145","heading":"B  Während seines letzten Schuljahres …","heading_en":"在他上学的最后一年里……","exercises":[{"no":"14","tag":"B3","instruction":"Verbinden Sie.","instruction_en":"把面试中的每个问题或说法和相应的回答（1–7）配对。写出编号。（第 13 题是听力练习，已略去。）","phrases":["1 Ich war zuständig für die Kontrolle von Haushalts-, Garten- und Freizeitartikeln.","2 Ich beherrsche die üblichen Programme und habe mich letztes Jahr im Bereich Lagerdatenbank weitergebildet.","3 Ja, ich würde gern wissen, wie gross das Lager hier ist.","4 Vielen Dank auch Ihnen.","5 Vielen Dank.","6 Ja, ich spreche drei Sprachen.","7 Also, ich bin Baumaschinenmechaniker und mache gerade den Führerausweis Kategorie BE."],"example":[{"label":"a","text":"Guten Tag, Herr Trantow. Nehmen Sie doch bitte Platz. → **5** Vielen Dank."}],"items":[{"label":"b","text":"Erzählen Sie doch bitte etwas über sich. → ___","gaps":[["7"]],"solution":"Erzählen Sie doch bitte etwas über sich. → **7**","en":"请您说一说自己的情况。→ 7 嗯，我是一名工程机械技师，正在考 BE 类驾照。","why":"你在介绍自己：你的职业和你现在在做的事。","source":"hueber"},{"label":"c","text":"Welche Aufgaben hatten Sie bei Ihrem letzten Arbeitgeber? → ___","gaps":[["1"]],"solution":"Welche Aufgaben hatten Sie bei Ihrem letzten Arbeitgeber? → **1**","en":"您在上一个雇主那里负责哪些工作？→ 1 我负责检查家居、园艺和休闲用品。","why":"*zuständig sein für* = 负责（你的工作任务）。","source":"hueber"},{"label":"d","text":"Haben Sie noch andere Fähigkeiten? → ___","gaps":[["6"]],"solution":"Haben Sie noch andere Fähigkeiten? → **6**","en":"您还有其他技能吗？→ 6 有，我会说三种语言。","why":"关于技能的是非疑问句：*Ja, …*","source":"hueber"},{"label":"e","text":"Können Sie mir mehr über Ihre Computerkenntnisse erzählen? → ___","gaps":[["2"]],"solution":"Können Sie mir mehr über Ihre Computerkenntnisse erzählen? → **2**","en":"您能跟我多讲讲您的电脑技能吗？→ 2 我熟悉常用的软件，去年还参加了仓库数据库方面的进修。","why":"*beherrschen* = 精通、掌握；*sich weiterbilden* = 进修。","source":"hueber"},{"label":"f","text":"Haben Sie noch eine Frage? → ___","gaps":[["3"]],"solution":"Haben Sie noch eine Frage? → **3**","en":"您还有什么问题吗？→ 3 有，我想知道这里的仓库有多大。","why":"间接疑问句：*wie gross das Lager hier ist*（动词在句末）。","source":"hueber"},{"label":"g","text":"Vielen Dank, dass Sie zu uns gekommen sind, Herr Trantow. → ___","gaps":[["4"]],"solution":"Vielen Dank, dass Sie zu uns gekommen sind, Herr Trantow. → **4**","en":"Trantow 先生，非常感谢您来我们这里。→ 4 我也谢谢您。","why":"你回谢对方：*Vielen Dank auch Ihnen.*","source":"hueber"}]},{"no":"15","tag":"B3","instruction":"Das kann ich! Ergänzen Sie Informationen über sich.","instruction_en":"我能做到！用关于你自己的信息补全句子。参考答案只是一种可能。","items":[{"label":"a","lead":"Ich habe schon während der Schulzeit/des Studiums …","text":"","open":true,"solution":"Ich habe schon während der Schulzeit in einem Café gejobbt.","en":"我在上学期间就已经在一家咖啡馆打过工。","why":"*während* + 第二格；现在完成时，第二分词放在句末。","source":"g299310"},{"label":"b","lead":"Ich bin/war zuständig für …","text":"","open":true,"solution":"Ich war zuständig für die Buchhaltung in einem kleinen Büro.","en":"我在一家小办公室负责会计工作。","why":"*zuständig für* + 第四格。","source":"hueber"},{"label":"c","lead":"Ich beherrsche …","text":"","open":true,"solution":"Ich beherrsche Excel und die üblichen Office-Programme.","en":"我精通 Excel 和常用的办公软件。","why":"*beherrschen* + 第四格 = 精通某项技能或语言。","source":"hueber"},{"label":"d","lead":"Ich habe auch (sehr) gute Kenntnisse in …","text":"","open":true,"solution":"Ich habe auch sehr gute Kenntnisse in Englisch und Italienisch.","en":"我的英语和意大利语水平也非常好。","why":"*Kenntnisse in* + 第三格。","source":"hueber"},{"label":"e","lead":"Es fällt mir leicht, …","text":"","open":true,"solution":"Es fällt mir leicht, im Team zu arbeiten und auf neue Kunden zuzugehen.","en":"对我来说，在团队里工作、主动和新客户打交道都很容易。","why":"*Es fällt mir leicht* + *zu* + 不定式；*zugehen* 是可分动词：*zu**zu**gehen*。","source":"g4069"}]}]},{"page":"AB 146","heading":"C  Berufsberatung","heading_en":"职业咨询","exercises":[{"no":"16","tag":"C2","instruction":"Was ist richtig? Lesen Sie und kreuzen Sie an.","instruction_en":"哪些是对的？阅读短文。在每个句子后面输入 *richtig*（对）或 *falsch*（错）；在课本里你只需勾出正确的句子。","reading":[{"label":"Was wollt ihr werden? – Jacqueline","text":"Ich gehe noch zur Schule. Nächstes Jahr mache ich die Matura. Ein Studium ist aber nichts für mich. Das dauert zu lange. Planung und Organisation sind kein Problem für mich. Deshalb möchte ich einen kaufmännischen Beruf ergreifen. Kommenden Montag habe ich einen Termin bei der Berufsberatung."},{"label":"Konstantinos","text":"In der Schule war ich gut in Mathematik und Kunst. Für mich war immer klar, dass ich mich mit technischen Fragen beschäftigen möchte. Und ich wollte auch künstlerisch tätig sein. Aber ich wusste nicht, wie ich das zusammenbringen sollte. Deshalb bin ich zur Berufsberatung gegangen. Der Berater hat mir eine Lehre als Zeichner Landschaftsarchitektur empfohlen. Ich hätte nicht gedacht, dass mir diese Arbeit so gut gefällt."}],"items":[{"label":"a","text":"Jacqueline hat keine Lust zu studieren. → ___","gaps":[["richtig","r","ja"]],"solution":"Jacqueline hat keine Lust zu studieren. → **richtig**","en":"Jacqueline 不想上大学。→ 对","why":"原文：*Ein Studium ist aber nichts für mich. Das dauert zu lange.*（但上大学不适合我。那要花太长时间。）","source":"hueber"},{"label":"b","text":"Sie findet es schwierig, etwas zu planen oder zu organisieren. → ___","gaps":[["falsch","f","nein"]],"solution":"Sie findet es schwierig, etwas zu planen oder zu organisieren. → **falsch**","en":"她觉得计划或组织事情很难。→ 错","why":"正好相反：*Planung und Organisation sind kein Problem für mich.*（计划和组织对我来说不成问题。）","source":"hueber"},{"label":"c","text":"Nächste Woche will sie sich über kaufmännische Ausbildungen informieren. → ___","gaps":[["richtig","r","ja"]],"solution":"Nächste Woche will sie sich über kaufmännische Ausbildungen informieren. → **richtig**","en":"下周她想去了解商业类的职业培训。→ 对","why":"*Kommenden Montag habe ich einen Termin bei der Berufsberatung*（下周一我在职业咨询处有个预约），是关于一份商业类工作的。","source":"hueber"},{"label":"d","text":"Konstantinos hatte vor, nach der Schule im Bereich Technik zu arbeiten. → ___","gaps":[["richtig","r","ja"]],"solution":"Konstantinos hatte vor, nach der Schule im Bereich Technik zu arbeiten. → **richtig**","en":"Konstantinos 曾打算中学毕业后在技术领域工作。→ 对","why":"原文：*Für mich war immer klar, dass ich mich mit technischen Fragen beschäftigen möchte.*（对我来说一直很清楚，我想从事和技术问题有关的工作。）","source":"hueber"},{"label":"e","text":"Er fand es zunächst schwierig, seine Interessensgebiete zu verbinden. → ___","gaps":[["richtig","r","ja"]],"solution":"Er fand es zunächst schwierig, seine Interessensgebiete zu verbinden. → **richtig**","en":"他起初觉得很难把自己感兴趣的几个领域结合起来。→ 对","why":"原文：*Aber ich wusste nicht, wie ich das zusammenbringen sollte.*（但我不知道该怎么把这些结合起来。）","source":"hueber"},{"label":"f","text":"Er hat erwartet, dass ihm die Lehre als Zeichner Landschaftsarchitektur Freude macht. → ___","gaps":[["falsch","f","nein"]],"solution":"Er hat erwartet, dass ihm die Lehre als Zeichner Landschaftsarchitektur Freude macht. → **falsch**","en":"他原本就料到自己会喜欢景观建筑制图员的学徒工作。→ 错","why":"*Ich hätte nicht gedacht, dass mir diese Arbeit so gut gefällt*（我没想到我会这么喜欢这份工作）= 他没有料到。","source":"hueber"}]},{"no":"17","tag":"C2","instruction":"Schreiben Sie Sätze (a–e). Ordnen Sie dann den passenden Ratschlag (1–5) zu.","instruction_en":"针对每个提示（a–e）用 *zu* + 不定式写一个句子。然后找出相符的建议（1–5）；答案里给出了它的编号。","phrases":["1 Du könntest Busfahrer werden.","2 Dann werde doch Schreiner.","3 Hm, schwierig. Vielleicht Modedesigner?","4 Wie wäre es mit einer Tätigkeit als Bäcker?","5 An deiner Stelle würde ich Köchin werden."],"example":[{"label":"a","lead":"sich gut vorstellen können – im handwerklichen Bereich arbeiten","text":"**Ich kann mir gut vorstellen, im handwerklichen Bereich zu arbeiten.** → 2"}],"items":[{"label":"b","lead":"es nicht schwer finden – früh aufstehen","text":"","accept":["Ich finde es nicht schwer, früh aufzustehen.","Es fällt mir nicht schwer, früh aufzustehen."],"solution":"**Ich finde es nicht schwer, früh aufzustehen.** → 4","en":"我不觉得早起很难。→ 4 当面包师怎么样？","why":"*Ich finde es* + 形容词 + *zu* + 不定式；*aufstehen* 是可分动词：*auf**zu**stehen*。面包师很早就要开工。","source":"g4069","check":"官方答案写的是 *Es fällt mir nicht schwer, früh aufzustehen*，意思相同；提示 *es nicht schwer finden* 得出的是 *Ich finde es nicht schwer, …*。两种都正确。"},{"label":"c","lead":"Lust haben – viel unterwegs sein","text":"","accept":["Ich habe Lust, viel unterwegs zu sein."],"solution":"**Ich habe Lust, viel unterwegs zu sein.** → 1","en":"我很想经常在外面跑。→ 1 你可以去当公交车司机。","why":"*Lust haben* + *zu* + 不定式。","source":"g6865"},{"label":"d","lead":"Freude machen – für andere kochen","text":"","accept":["Es macht mir Freude, für andere zu kochen.","Mir macht es Freude, für andere zu kochen."],"solution":"**Es macht mir Freude, für andere zu kochen.** → 5","en":"我喜欢为别人做饭。→ 5 如果我是你，我会去当厨师。","why":"*Es macht mir Freude* + *zu* + 不定式。","source":"g6865"},{"label":"e","lead":"Interesse haben – Neues entwickeln","text":"","accept":["Ich habe Interesse daran, Neues zu entwickeln.","Ich habe Interesse, Neues zu entwickeln."],"solution":"**Ich habe Interesse daran, Neues zu entwickeln.** → 3","en":"我对开发新东西感兴趣。→ 3 嗯，这可难说。也许当时装设计师？","why":"*Interesse haben (daran)* + *zu* + 不定式；*daran* 指向后面的 *zu* 词组。","source":"g6865"}]},{"no":"18","tag":"C2","instruction":"Wörter mit -ng","instruction_en":"带 -ng 的词","part":"a","part_instruction":"Bilden Sie Wörter mit *-ung*.","part_instruction_en":"用这些动词构成以 *-ung* 结尾的名词，并写出冠词。（b–d 部分是听力练习，已略去。）","example":[{"label":"1","text":"beraten → **die Beratung**"},{"label":"4","text":"entwickeln → **die Entwicklung**"}],"items":[{"label":"2","text":"erfahren → ___","gaps":[["die Erfahrung","Erfahrung"]],"solution":"erfahren → **die Erfahrung**","en":"经历、得知 → 经验","why":"动词词干 + *-ung*；以 *-ung* 结尾的名词总是阴性：*die*。","source":"hueber"},{"label":"3","text":"verantworten → ___","gaps":[["die Verantwortung","Verantwortung"]],"solution":"verantworten → **die Verantwortung**","en":"负责 → 责任","why":"词干 *verantwort-* + *-ung*：*die Verantwortung*。","source":"hueber"},{"label":"5","text":"beschäftigen → ___","gaps":[["die Beschäftigung","Beschäftigung"]],"solution":"beschäftigen → **die Beschäftigung**","en":"雇用 / 使忙于 → 雇用、工作","why":"词干 *beschäftig-* + *-ung*。","source":"hueber"},{"label":"6","text":"unterstützen → ___","gaps":[["die Unterstützung","Unterstützung"]],"solution":"unterstützen → **die Unterstützung**","en":"支持 → 支持","why":"词干 *unterstütz-* + *-ung*。","source":"hueber"}]}]},{"page":"AB 147","heading":"D  Small Talk: Von der Arbeit erzählen","heading_en":"闲聊：谈论工作","exercises":[{"no":"19","tag":"D2","instruction":"Ordnen Sie zu.","instruction_en":"用两个方框里的短语（这里合成一个方框）补全 Bettina（○）和一位朋友（◆）之间的闲聊对话。每个短语只用一次；划掉的那个已用在例句中。","box":["es ist total stressig","Hast du noch nie daran gedacht","muss zwei Kollegen vertreten","Hast du immer noch so viel Arbeit","schon mehrere Bewerbungen geschrieben","suche immer noch eine Stelle","Wie läuft's denn so","Ist das nicht anstrengend","machst du jetzt eigentlich genau","habe kein Interesse","komme gut mit den Kunden und den Kollegen zurecht","muss jetzt leider gehen"],"box_used":[6],"box_exact":true,"example":[{"label":"a","text":"◆ Hoi, Bettina. Das ist aber schön, dich zu sehen. **Wie läuft's denn so** mit der Jobsuche?"}],"items":[{"label":"b","text":"○ Schwierig. Ich ___ als Übersetzerin.","gaps":[["suche immer noch eine Stelle"]],"solution":"○ Schwierig. Ich **suche immer noch eine Stelle** als Übersetzerin.","en":"○ 不太顺利。我还在找翻译的工作。","why":"*Ich* 后面接动词 *suche*。","source":"hueber"},{"label":"c","text":"○ Ich habe ___, aber nur Absagen erhalten.","gaps":[["schon mehrere Bewerbungen geschrieben"]],"solution":"○ Ich habe **schon mehrere Bewerbungen geschrieben**, aber nur Absagen erhalten.","en":"○ 我已经写了好几封求职信，但只收到了拒信。","why":"现在完成时：*habe … geschrieben*，与 *erhalten* 相对应。","source":"hueber"},{"label":"d","text":"◆ ___, dich selbstständig zu machen? Das machen doch viele Übersetzer.","gaps":[["Hast du noch nie daran gedacht"]],"solution":"◆ **Hast du noch nie daran gedacht**, dich selbstständig zu machen? Das machen doch viele Übersetzer.","en":"◆ 你就从来没想过自己单干吗？很多翻译都这么做。","why":"*daran denken* + *zu* + 不定式；*daran* 指向 *zu* 词组。","source":"hueber"},{"label":"e","text":"○ Ja, das stimmt. Aber ___, immer nach Aufträgen zu suchen. Ausserdem gibt es viel Konkurrenz.","gaps":[["es ist total stressig"]],"solution":"○ Ja, das stimmt. Aber **es ist total stressig**, immer nach Aufträgen zu suchen. Ausserdem gibt es viel Konkurrenz.","en":"○ 对，确实如此。可是总要到处找活儿，压力太大了。而且竞争也很激烈。","why":"*Es ist* + 形容词 + *zu* + 不定式。","source":"hueber"},{"label":"f","text":"○ Aber wie geht es dir denn? ___?","gaps":[["Hast du immer noch so viel Arbeit"]],"solution":"○ Aber wie geht es dir denn? **Hast du immer noch so viel Arbeit**?","en":"○ 那你呢，你怎么样？你还是那么忙吗？","why":"回答 *Ja, leider* 需要一个是非疑问句。","source":"hueber"},{"label":"g","text":"◆ Ja, leider. Bei uns in der Firma sind im Moment mehrere Leute krank. Ich ___. Und das jetzt, wo wir so viele Aufträge haben!","gaps":[["muss zwei Kollegen vertreten"]],"solution":"◆ Ja, leider. Bei uns in der Firma sind im Moment mehrere Leute krank. Ich **muss zwei Kollegen vertreten**. Und das jetzt, wo wir so viele Aufträge haben!","en":"◆ 是啊，可惜。我们公司现在有好几个人病了。我得替两个同事顶班。偏偏是现在，我们的订单这么多！","why":"*vertreten* = 替某人顶班、代替某人。","source":"hueber"},{"label":"h","text":"○ Was ___?","gaps":[["machst du jetzt eigentlich genau"]],"solution":"○ Was **machst du jetzt eigentlich genau**?","en":"○ 你现在到底具体做什么？","why":"W 疑问句：*Was* + 动词 *machst* + *du*。","source":"hueber"},{"label":"i","lead":"◆ Ich bin als Heizungsinstallateur tätig. Ich habe die Verantwortung für zwei Baustellen und soll nebenbei die Baustellen meiner Kollegen betreuen.","text":"○ ___, immer von Baustelle zu Baustelle zu fahren?","gaps":[["Ist das nicht anstrengend"]],"solution":"○ **Ist das nicht anstrengend**, immer von Baustelle zu Baustelle zu fahren?","en":"○ 总是从一个工地开到另一个工地，不累吗？","why":"*Ist das nicht anstrengend, … zu* + 不定式？","source":"hueber"},{"label":"j","text":"◆ Manchmal schon, aber meistens macht mir die Arbeit Freude. Ich ___. Übrigens, meine Firma sucht gerade jemanden fürs Büro. Willst du dich nicht bewerben?","gaps":[["komme gut mit den Kunden und den Kollegen zurecht"]],"solution":"◆ Manchmal schon, aber meistens macht mir die Arbeit Freude. Ich **komme gut mit den Kunden und den Kollegen zurecht**. Übrigens, meine Firma sucht gerade jemanden fürs Büro. Willst du dich nicht bewerben?","en":"◆ 有时候是挺累的，但大多数时候我很喜欢这份工作。我和客户、同事都相处得很好。对了，我们公司正在找一个办公室的人。你不想去申请吗？","why":"*mit jemandem gut zurechtkommen* = 和某人相处得好（可分动词）。","source":"hueber"},{"label":"k","text":"○ Aber was meinst denn du! Ich bin Übersetzerin. Ich ___ an einer Tätigkeit als Sekretärin.","gaps":[["habe kein Interesse"]],"solution":"○ Aber was meinst denn du! Ich bin Übersetzerin. Ich **habe kein Interesse** an einer Tätigkeit als Sekretärin.","en":"○ 你在想什么呢！我是翻译。我对秘书的工作没兴趣。","why":"*Interesse an* + 第三格（*an einer Tätigkeit*）。","source":"hueber"},{"label":"l","lead":"◆ Warum nicht? Als Übersetzerin sitzt du doch auch am Computer, schreibst und telefonierst. Der Job ist sicher und unsere Firma zahlt nicht schlecht. Überleg es dir doch einmal.","text":"○ Okay, das mache ich. Danke für den Tipp. Oh, ich ___.","gaps":[["muss jetzt leider gehen"]],"solution":"○ Okay, das mache ich. Danke für den Tipp. Oh, ich **muss jetzt leider gehen**.","en":"○ 好，我会的。谢谢你的建议。哦，可惜我现在得走了。","why":"结束闲聊的一种典型说法。","source":"hueber"}]},{"no":"20","tag":"D2","instruction":"Ergänzen Sie.","instruction_en":"补全这些简短的广告。书中给出了每个词的一些字母；请写出完整的单词。","example":[{"label":"Beispiel","text":"In den Semesterferien **jobben** – …"}],"items":[{"label":"A","lead":"Ü _ _ _ s _ tz _ _ /in","text":"In den Semesterferien jobben – wir suchen dich als ___/in von kurzen Werbetexten.","gaps":[["Übersetzer"]],"solution":"In den Semesterferien jobben – wir suchen dich als **Übersetzer**/in von kurzen Werbetexten.","en":"在学期假期打工——我们在找你来翻译简短的广告文案。","why":"*der Übersetzer / die Übersetzerin* = 翻译。","source":"hueber"},{"label":"B","lead":"A _ f _ _ ä _ _ n","text":"Selbstständig als Reinigungshilfe arbeiten: Auf Putzfee.net können Sie Ihren Service anbieten und nach ___ suchen.","gaps":[["Aufträgen"]],"solution":"Selbstständig als Reinigungshilfe arbeiten: Auf Putzfee.net können Sie Ihren Service anbieten und nach **Aufträgen** suchen.","en":"以自由职业者身份做清洁工：在 Putzfee.net 上，您可以提供您的服务并寻找订单。","why":"*der Auftrag, die Aufträge* = 订单、活儿；*nach* + 复数第三格要加 *-n*：*Aufträgen*。","source":"hueber"},{"label":"C1","lead":"F _ _ _ b _ _ _ _ g","text":"Machen Sie eine ___. Wir bieten interessante Seminare in den Bereichen Technik und Handel.","gaps":[["Fortbildung"]],"solution":"Machen Sie eine **Fortbildung**. Wir bieten interessante Seminare in den Bereichen Technik und Handel.","en":"参加进修吧。我们提供技术和商务领域的有趣研讨课。","why":"*eine Fortbildung machen* = 参加进修。","source":"hueber"},{"label":"C2","lead":"K _ _ k _ _ _ e _ z","text":"Denn die ___ schläft nicht!","gaps":[["Konkurrenz"]],"solution":"Denn die **Konkurrenz** schläft nicht!","en":"因为竞争对手从不睡觉！","why":"*die Konkurrenz* = 竞争对手。","source":"hueber"},{"label":"D","lead":"v _ _ tr _ _ _ n","text":"Flexibel und motiviert? Wir suchen Personen, die auf Stundenbasis unsere Lagermitarbeiter ___ können.","gaps":[["vertreten"]],"solution":"Flexibel und motiviert? Wir suchen Personen, die auf Stundenbasis unsere Lagermitarbeiter **vertreten** können.","en":"灵活又积极？我们在找能按小时顶替我们仓库员工的人。","why":"情态动词 *können* + 不定式 *vertreten*（不加 *zu*）。","source":"hueber"}]}]},{"page":"AB 148","heading":"Test Lektion 5","heading_en":"第 5 课测试","exercises":[{"no":"1","instruction":"Ergänzen Sie.","instruction_en":"补全句子。书中给出了每个词的一些字母；请写出完整的单词。","example":[{"label":"d","text":"Frau Angst will bald **aufhören** zu arbeiten und in Pension gehen."}],"items":[{"label":"a","lead":"A _ _ t _ ä _ e","text":"Die Firma *Müller & Müller* ist sehr gut und hat deshalb viele ___.","gaps":[["Aufträge"]],"solution":"Die Firma *Müller & Müller* ist sehr gut und hat deshalb viele **Aufträge**.","en":"Müller & Müller 公司非常好，所以有很多订单。","why":"*der Auftrag, die Aufträge* = 订单；*viele* 后面要用复数。"},{"label":"b","lead":"V _ r _ n _ w _ _ t _ _ g","text":"Frau Brügger hat die ___ für 200 Mitarbeiter.","gaps":[["Verantwortung"]],"solution":"Frau Brügger hat die **Verantwortung** für 200 Mitarbeiter.","en":"Brügger 女士负责 200 名员工。","why":"*die Verantwortung für* + 第四格 = 对……的责任。"},{"label":"c","lead":"_ t _ _ _ _ … h _ _","text":"Die Firma ___ die Möbel aus Schweizer Holz ___.","gaps":[["stellt"],["her"]],"solution":"Die Firma **stellt** die Möbel aus Schweizer Holz **her**.","en":"这家公司用瑞士木材制作家具。","why":"*herstellen* = 制造、生产；可分动词：*stellt … her*。"},{"label":"e","lead":"S _ _ v _ _ _ a _ g _ _ _ _ _ _ _ _ r","text":"Mario ist als ___ in einem Restaurant tätig.","gaps":[["Serviceangestellter"]],"solution":"Mario ist als **Serviceangestellter** in einem Restaurant tätig.","en":"Mario 在一家餐厅当服务员。","why":"*der Serviceangestellte* = 服务员（瑞士用语）；在不带冠词的 *als* 之后，词尾是 *-er*：*als Serviceangestellter*。"},{"label":"f","lead":"z _ st _ _ _ _ g","text":"Peter ist ___ für die Kontrolle und Reparatur der Werkzeugmaschinen.","gaps":[["zuständig"]],"solution":"Peter ist **zuständig** für die Kontrolle und Reparatur der Werkzeugmaschinen.","en":"Peter 负责检查和维修机床。","why":"*zuständig sein für* = 负责。"},{"label":"g","lead":"F _ _ _ b _ _ d _ _ g _ n","text":"Die Firma *Müller & Müller* bietet ihren Mitarbeitern viele ___ an.","gaps":[["Fortbildungen"]],"solution":"Die Firma *Müller & Müller* bietet ihren Mitarbeitern viele **Fortbildungen** an.","en":"Müller & Müller 公司为员工提供很多进修机会。","why":"*die Fortbildung, die Fortbildungen*；*viele* 后面要用复数。"}]},{"no":"2","instruction":"Schreiben Sie die Sätze neu.","instruction_en":"用给出的开头和 *zu* + 不定式改写每个句子。只写逗号后面的部分。","example":[{"label":"a","lead":"Fortbildungen interessieren mich nicht!","text":"Ich habe kein Interesse, **Fortbildungen zu machen**."}],"items":[{"label":"b","lead":"Die Zusammenarbeit mit meinen Kollegen macht mir Freude.","text":"Es macht mir Freude, ___.","gaps":[["mit meinen Kollegen zusammenzuarbeiten"]],"solution":"Es macht mir Freude, **mit meinen Kollegen zusammenzuarbeiten**.","en":"我很喜欢和同事们一起工作。","why":"*die Zusammenarbeit* → 动词 *zusammenarbeiten*，可分动词：*zusammen**zu**arbeiten*。","source":"g4069"},{"label":"c","lead":"Ich könnte mir eine Arbeit als Pflegefachmann gut vorstellen.","text":"Ich könnte mir gut vorstellen, ___.","gaps":[["als Pflegefachmann zu arbeiten"]],"solution":"Ich könnte mir gut vorstellen, **als Pflegefachmann zu arbeiten**.","en":"我完全可以想象当护士。","why":"名词短语 *eine Arbeit als …* → 动词词组 *als … zu arbeiten*。","source":"g6865"},{"label":"d","lead":"Der Berufsberater verspricht Hilfe bei der Berufswahl.","text":"Der Berufsberater verspricht, ___.","gaps":[["bei der Berufswahl zu helfen","mir bei der Berufswahl zu helfen","uns bei der Berufswahl zu helfen","bei der Berufswahl zu unterstützen"]],"solution":"Der Berufsberater verspricht, **bei der Berufswahl zu helfen**.","en":"职业顾问答应在选择职业方面提供帮助。","why":"*die Hilfe* → 动词 *helfen*：*zu helfen* 放在句末。","source":"g6865"}]},{"no":"3","instruction":"Ergänzen Sie: *während – innerhalb – ausserhalb* und *der – ein – …* in der richtigen Form.","instruction_en":"用 *während*、*innerhalb* 或 *ausserhalb* 加上正确形式的冠词（第二格）填空。书中给出了冠词的首字母。","example":[{"label":"a","text":"Sehr geehrter Herr Safak, vielen Dank für Ihre Bewerbung. Wir melden uns **innerhalb der** nächsten Tage bei Ihnen."}],"items":[{"label":"b1","lead":"Sehr geehrter Herr Safak, wir laden Sie zu einem Vorstellungsgespräch am 2.8. um 10 Uhr ein.","text":"___ Gesprächs können Sie natürlich gern Fragen stellen.","gaps":[["Während des"]],"solution":"**Während des** Gesprächs können Sie natürlich gern Fragen stellen.","en":"面试期间，您当然可以随时提问。","why":"*während* + 中性第二格：*des Gesprächs*。","source":"g299310"},{"label":"b2","text":"Bitte geben Sie ___ Woche Bescheid, ob Sie kommen.","gaps":[["innerhalb einer"]],"solution":"Bitte geben Sie **innerhalb einer** Woche Bescheid, ob Sie kommen.","en":"请在一周之内告诉我们您是否来。","why":"*innerhalb* + 阴性第二格：*einer Woche*。","source":"prep"},{"label":"b3","text":"Sie erreichen mich per Telefon oder ___ Bürozeiten per E-Mail.","gaps":[["ausserhalb der"]],"solution":"Sie erreichen mich per Telefon oder **ausserhalb der** Bürozeiten per E-Mail.","en":"您可以打电话联系我，在办公时间以外可以发电子邮件。","why":"*ausserhalb* + 复数第二格：*der Bürozeiten*。","source":"prep"}]},{"no":"4","instruction":"Verbinden Sie.","instruction_en":"把每个问题和相应的回答（1–5）配对。写出编号。","phrases":["1 Nein, das kann ich mir nicht vorstellen.","2 Nein, das finde ich nicht.","3 Ja, ich muss eine Kollegin vertreten.","4 Ich beende gerade meine Lehre als Maler.","5 Danke, recht gut. Wir haben viel Arbeit."],"example":[{"label":"a","text":"Wie läuft's denn so in der Firma? → **5** Danke, recht gut. Wir haben viel Arbeit."}],"items":[{"label":"b","text":"Hast du noch nie daran gedacht, die Stelle zu wechseln? → ___","gaps":[["1"]],"solution":"Hast du noch nie daran gedacht, die Stelle zu wechseln? → **1**","en":"你从来没想过换工作吗？→ 1 没有，我无法想象。","why":"关于一个想法的问题：*Nein, das kann ich mir nicht vorstellen.*"},{"label":"c","text":"Was machst du jetzt eigentlich genau? → ___","gaps":[["4"]],"solution":"Was machst du jetzt eigentlich genau? → **4**","en":"你现在具体做什么？→ 4 我正要完成油漆工的学徒培训。","why":"问你工作情况的 W 疑问句需要用事实来回答。"},{"label":"d","text":"Ist es nicht stressig, nachts zu arbeiten? → ___","gaps":[["2"]],"solution":"Ist es nicht stressig, nachts zu arbeiten? → **2**","en":"晚上工作压力不大吗？→ 2 不，我不这么觉得。","why":"*Ist es nicht stressig …?* 是在询问看法：*Nein, das finde ich nicht.*"},{"label":"e","text":"Hast du immer noch so viel Arbeit? → ___","gaps":[["3"]],"solution":"Hast du immer noch so viel Arbeit? → **3**","en":"你还是那么忙吗？→ 3 是的，我得顶替一位同事。","why":"是非疑问句；回答说明了工作多的原因：*eine Kollegin vertreten*。"}]}]},{"page":"AB 149","heading":"Fokus Beruf: Etwas verhandeln","heading_en":"职场聚焦：谈判","exercises":[{"no":"1","instruction":"Vier gute Tipps","instruction_en":"四个好建议","part":"a","part_instruction":"Wofür bekommt man hier Tipps? Überfliegen Sie den Text und kreuzen Sie an.","part_instruction_en":"这些建议是关于什么的？快速浏览短文，写出正确的答案。（本页的第 2 题和第 3 题是听力练习，已略去。）","reading":[{"label":"So kommen Sie weiter!","text":"Ist das Bewerbungsgespräch gut gelaufen? Herzlichen Glückwunsch! Jetzt haben Sie es fast geschafft. Aber wenn es im Bewerbungsgespräch zum Thema Geld kommt, machen viele Bewerber Fehler: Sie fordern zu viel Lohn – oder zu wenig. Unsere Tipps helfen Ihnen bei diesem schwierigen Thema.\n1  Sprechen Sie das Thema Geld nicht selbst an. Den ersten Schritt sollte die Personalchefin oder der Personalchef machen.\n2  Nennen Sie Ihre Gehaltsvorstellung. Wenn Sie vorher in anderen Unternehmen gearbeitet haben, ist Ihr letztes Gehalt die Grundlage.\n3  Natürlich können Sie an einem neuen Arbeitsplatz mehr Lohn verlangen, aber bleiben Sie realistisch und begründen Sie Ihre Gehaltsvorstellung: Haben Sie mehr Verantwortung? Können Sie mit besonderen Kenntnissen, Fähigkeiten oder Erfahrungen punkten? War der alte Arbeitgeber besonders zufrieden mit Ihnen?\n4  Was ist, wenn die Personalchefin oder der Personalchef negativ auf Ihre Gehaltsvorstellung reagiert? Dann müssen Sie flexibel sein und andere Vorschläge machen. Erklären Sie zum Beispiel, dass Sie mit weniger Lohn einverstanden sind, wenn die Firma Ihnen eine Weiter- oder Fortbildung bezahlt. Oder wenn Sie nach sechs Monaten mehr Lohn bekommen."}],"items":[{"label":"1","lead":"○ Für Gespräche mit der Bank   ○ Für Gespräche mit dem Arbeitgeber","text":"___","gaps":[["Für Gespräche mit dem Arbeitgeber","mit dem Arbeitgeber","Arbeitgeber","dem Arbeitgeber"]],"solution":"**Für Gespräche mit dem Arbeitgeber**","en":"关于和雇主的谈话","why":"这些建议讲的是在求职面试中和人事主管谈薪水。","source":"hueber"}]},{"no":"1","part":"b","part_instruction":"Was ist richtig? Lesen Sie noch einmal und kreuzen Sie an.","part_instruction_en":"哪些是对的？再读一遍。在每个句子后面输入 *richtig*（对）或 *falsch*（错）；在课本里你只需勾出正确的句子。","items":[{"label":"1","text":"Es ist Aufgabe der Personalchefin / des Personalchefs, das Thema Lohn anzusprechen. → ___","gaps":[["richtig","r","ja"]],"solution":"Es ist Aufgabe der Personalchefin / des Personalchefs, das Thema Lohn anzusprechen. → **richtig**","en":"主动提起工资话题是人事主管的事。→ 对","why":"建议 1：*Den ersten Schritt sollte die Personalchefin oder der Personalchef machen.*（应该由人事主管迈出第一步。）","source":"hueber"},{"label":"2","text":"Am neuen Arbeitsplatz bekommen Sie zunächst den gleichen Lohn wie in der alten Firma. → ___","gaps":[["falsch","f","nein"]],"solution":"Am neuen Arbeitsplatz bekommen Sie zunächst den gleichen Lohn wie in der alten Firma. → **falsch**","en":"在新的工作岗位上，您一开始拿的工资和在原公司一样。→ 错","why":"建议 2 和 3：你上一份工资只是基础；你可以要求更多。","source":"hueber"},{"label":"3","text":"Wenn Sie mehr Lohn haben möchten, sollten Sie gute Argumente dafür nennen. → ___","gaps":[["richtig","r","ja"]],"solution":"Wenn Sie mehr Lohn haben möchten, sollten Sie gute Argumente dafür nennen. → **richtig**","en":"如果您想要更高的工资，就应该为此提出充分的理由。→ 对","why":"建议 3：*begründen Sie Ihre Gehaltsvorstellung*（说明您期望薪资的理由）。","source":"hueber"},{"label":"4","text":"Wenn die Personalchefin / der Personalchef mit Ihrem Vorschlag nicht einverstanden ist, können Sie nichts weiter machen. → ___","gaps":[["falsch","f","nein"]],"solution":"Wenn die Personalchefin / der Personalchef mit Ihrem Vorschlag nicht einverstanden ist, können Sie nichts weiter machen. → **falsch**","en":"如果人事主管不同意您的建议，您就无计可施了。→ 错","why":"建议 4：要灵活，并提出其他方案（由公司支付培训费用、六个月后加薪）。","source":"hueber"}]}]}]},{"id":"05-um-zu-damit-statt-ohne-reklamation","no":5,"title":"Lektion 6","title_en":"用 um … zu 和 damit 表达目的、而不是 / 没有、带 es 的动词、购物对话和投诉 · 第 6 课测试","added":"2026-11-18","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 6","pages":[{"page":"AB 150","heading":"A  Es ist nicht leicht, aber es lohnt sich.","heading_en":"这并不容易，但是值得。","exercises":[{"no":"1","tag":"A2","instruction":"Ordnen Sie zu.","instruction_en":"用方框里带 *es* 的表达补全 Anna 的电子邮件。每个表达只用一次；*geht es* 已用在例句中。如果一个表达里有 *…*，说明中间还有别的词：把这两部分分别填进两个空里。","phrases":["geht es (Beispiel)","Es war","Es gibt","ist es … gelaufen","es … dunkel ist","wird es … schwierig","schwer es mir fällt","Es ist Sommer","regnet es","hat es … gefallen","es ist … kalt","ist es … ein Uhr","lohnt es sich"],"example":[{"label":"a","text":"Hallo Tim / Wie **geht es** Dir? Bei mir ist alles bestens."}],"items":[{"label":"b","text":"___, überall sieht man Blumen und ich bin viel draussen. Ich liebe diese Jahreszeit!","gaps":[["Es ist Sommer"]],"solution":"**Es ist Sommer**, überall sieht man Blumen und ich bin viel draussen. Ich liebe diese Jahreszeit!","en":"现在是夏天，到处都能看到花，我经常待在外面。我爱这个季节！","why":"*es* + *sein* + 季节或一天中的时段：*Es ist Sommer / Nacht / vier Uhr*。","source":"platzhalter"},{"label":"c","text":"Seit ein paar Tagen ___ zwar, aber schlechtes Wetter stört mich ja nicht.","gaps":[["regnet es"]],"solution":"Seit ein paar Tagen **regnet es** zwar, aber schlechtes Wetter stört mich ja nicht.","en":"这几天虽然一直在下雨，但是坏天气根本不影响我。","why":"天气动词总是以 *es* 作主语。*Seit ein paar Tagen* 在第 1 位，所以 *es* 放在动词后面：*regnet es*。","source":"platzhalter"},{"label":"d","text":"Hauptsache, ___ nicht ___.","gaps":[["es ist"],["kalt"]],"solution":"Hauptsache, **es ist** nicht **kalt**.","en":"最重要的是，天不冷。","why":"天气加形容词：*es ist kalt / heiss*。*nicht* 放在 *kalt* 前面。","source":"platzhalter"},{"label":"e","text":"Du, ich hatte heute Vormittag ein Vorstellungsgespräch! ___ wirklich aufregend, …","gaps":[["Es war"]],"solution":"Du, ich hatte heute Vormittag ein Vorstellungsgespräch! **Es war** wirklich aufregend, …","en":"跟你说，我今天上午去面试了！真的很紧张刺激……","why":"一般的 *es* + *sein* + 形容词，这里用过去时（Präteritum）：*Es war aufregend*。","source":"korrelat"},{"label":"f","text":"… aber eigentlich ___ ziemlich gut ___. Die Leute sind sehr nett und die Arbeit ist abwechslungsreich.","gaps":[["ist es"],["gelaufen"]],"solution":"… aber eigentlich **ist es** ziemlich gut **gelaufen**. Die Leute sind sehr nett und die Arbeit ist abwechslungsreich.","en":"……不过其实进行得挺顺利的。那里的人都很友好，工作也很多样。","why":"*Es ist gut gelaufen* = 进行得很顺利（用 *sein* 构成的现在完成时）。*eigentlich* 在第 1 位，所以是 *ist es*。","source":"platzhalter"},{"label":"g","text":"___ nur leider ein Problem: Ich soll morgens um 7 Uhr (!) anfangen zu arbeiten. So schlimm!","gaps":[["Es gibt"]],"solution":"**Es gibt** nur leider ein Problem: Ich soll morgens um 7 Uhr (!) anfangen zu arbeiten. So schlimm!","en":"可惜只有一个问题：我得早上 7 点（！）就开始上班。太可怕了！","why":"*es gibt* + 第四格 = 有：*Es gibt ein Problem*。","source":"platzhalter"},{"label":"h","text":"Du weisst doch, wie ___, früh aufzustehen.","gaps":[["schwer es mir fällt"]],"solution":"Du weisst doch, wie **schwer es mir fällt**, früh aufzustehen.","en":"你知道的，早起对我来说有多难。","why":"*Es fällt mir schwer, … zu …* = 我觉得做……很难。在 *wie* 从句里动词放在句末：*wie schwer es mir fällt*。","source":"korrelat"},{"label":"i","text":"Vor allem im Winter, wenn ___ noch ___, …","gaps":[["es"],["dunkel ist"]],"solution":"Vor allem im Winter, wenn **es** noch **dunkel ist**, …","en":"尤其是在冬天，天还黑的时候……","why":"*Es ist dunkel*（一天中的时段、光线）。在 *wenn* 从句里动词放在句末：*wenn es noch dunkel ist*。","source":"platzhalter"},{"label":"j","text":"… dann ___ wirklich ___ für mich.","gaps":[["wird es"],["schwierig"]],"solution":"… dann **wird es** wirklich **schwierig** für mich.","en":"……那时对我来说就真的很困难了。","why":"*Es wird schwierig* = 变得困难。*dann* 在第 1 位，所以是 *wird es*。","source":"korrelat"},{"label":"k","text":"Mir ___ in der Firma zwar sehr gut ___, aber ich weiss nicht, ob ich das mit dem frühen Aufstehen schaffe. Was rätst Du mir?","gaps":[["hat es"],["gefallen"]],"solution":"Mir **hat es** in der Firma zwar sehr gut **gefallen**, aber ich weiss nicht, ob ich das mit dem frühen Aufstehen schaffe. Was rätst Du mir?","en":"虽然我很喜欢那家公司，但我不知道自己能不能做到早起。你给我什么建议？","why":"*Es gefällt mir* = 我喜欢；现在完成时：*Es hat mir gefallen*。这里 *Mir* 在第 1 位。","source":"korrelat"},{"label":"l","text":"P.S.: Oh je, jetzt ___ schon wieder ___ nachts.","gaps":[["ist es"],["ein Uhr"]],"solution":"P.S.: Oh je, jetzt **ist es** schon wieder **ein Uhr** nachts.","en":"附言：哎呀，现在又已经是夜里一点了。","why":"钟点：*Es ist ein Uhr*。*jetzt* 在第 1 位，所以是 *ist es*。","source":"platzhalter"},{"label":"m","text":"Vielleicht sollte ich einfach mal früher ins Bett gehen? Wer weiss, vielleicht ___ und ich bin dann am Morgen plötzlich immer topfit?","gaps":[["lohnt es sich"]],"solution":"Vielleicht sollte ich einfach mal früher ins Bett gehen? Wer weiss, vielleicht **lohnt es sich** und ich bin dann am Morgen plötzlich immer topfit?","en":"也许我干脆早点上床睡觉？谁知道呢，也许这样做值得，然后我早上突然就总是精神饱满了？","why":"*Es lohnt sich* = 值得。*vielleicht* 在第 1 位，所以是 *lohnt es sich*。","source":"platzhalter"}]},{"no":"2","tag":"A2","instruction":"Machen Sie eine Tabelle und ergänzen Sie die Ausdrücke mit *es* aus 1.","instruction_en":"把练习 1 中带 *es* 的表达分成四类。写出类别：*Allgemein*（一般表达）、*Tages-/Jahreszeiten*（一天中的时段和季节）、*Wetter*（天气）或 *Befinden*（某人的状况）。","example":[{"label":"Befinden","text":"Wie geht es Dir? → **Befinden**"}],"items":[{"label":"1","text":"Es ist Sommer. → ___","gaps":[["Tages-/Jahreszeiten","Jahreszeiten","Tageszeiten","Jahreszeit","Tages- und Jahreszeiten"]],"solution":"Es ist Sommer. → **Tages-/Jahreszeiten**","en":"现在是夏天。→ 一天中的时段和季节","why":"一个季节。","source":"hueber"},{"label":"2","text":"regnet es → ___","gaps":[["Wetter"]],"solution":"regnet es → **Wetter**","en":"下雨 → 天气","why":"天气动词。","source":"hueber"},{"label":"3","text":"es ist kalt → ___","gaps":[["Wetter"]],"solution":"es ist kalt → **Wetter**","en":"天冷 → 天气","why":"气温属于天气。","source":"hueber"},{"label":"4","text":"Es war (aufregend) → ___","gaps":[["Allgemein","allgemein"]],"solution":"Es war (aufregend) → **Allgemein**","en":"那（很紧张刺激）→ 一般表达","why":"*es* + *sein* + 形容词，描述一种情况。","source":"hueber"},{"label":"5","text":"es ist gelaufen → ___","gaps":[["Allgemein","allgemein"]],"solution":"es ist gelaufen → **Allgemein**","en":"进行得（顺利）→ 一般表达","why":"某件事进行得怎么样：一般表达。","source":"hueber"},{"label":"6","text":"Es gibt → ___","gaps":[["Allgemein","allgemein"]],"solution":"Es gibt → **Allgemein**","en":"有 → 一般表达","why":"*es gibt* = 有。","source":"hueber"},{"label":"7","text":"schwer es mir fällt → ___","gaps":[["Allgemein","allgemein"]],"solution":"schwer es mir fällt → **Allgemein**","en":"对我来说有多难 → 一般表达","why":"*es fällt mir schwer* = 我觉得很难。","source":"hueber"},{"label":"8","text":"es dunkel ist → ___","gaps":[["Tages-/Jahreszeiten","Tageszeiten","Tageszeit","Jahreszeiten","Tages- und Jahreszeiten"]],"solution":"es dunkel ist → **Tages-/Jahreszeiten**","en":"天黑 → 一天中的时段","why":"天黑 = 一天中的时段。","source":"hueber","check":"官方答案把 *es ist dunkel* 归入一天中的时段。你也可以把它看作天气；如果你们班的分法不同，就问问老师。"},{"label":"9","text":"wird es schwierig → ___","gaps":[["Allgemein","allgemein"]],"solution":"wird es schwierig → **Allgemein**","en":"变得困难 → 一般表达","why":"*es* + *werden* + 形容词，描述一种情况。","source":"hueber"},{"label":"10","text":"hat es gefallen → ___","gaps":[["Allgemein","allgemein"]],"solution":"hat es gefallen → **Allgemein**","en":"我喜欢 → 一般表达","why":"*es gefällt mir* = 我喜欢。","source":"hueber"},{"label":"11","text":"ist es ein Uhr → ___","gaps":[["Tages-/Jahreszeiten","Tageszeiten","Tageszeit","Jahreszeiten","Tages- und Jahreszeiten"]],"solution":"ist es ein Uhr → **Tages-/Jahreszeiten**","en":"现在是一点 → 一天中的时段","why":"钟点。","source":"hueber"},{"label":"12","text":"lohnt es sich → ___","gaps":[["Allgemein","allgemein"]],"solution":"lohnt es sich → **Allgemein**","en":"值得 → 一般表达","why":"*es lohnt sich* = 值得。","source":"hueber"}]},{"no":"3","tag":"A2","instruction":"Wo fehlt *es*? Ergänzen Sie wie im Beispiel.","instruction_en":"哪里缺了 *es*？阅读 Fatima 的电子邮件。把下面的每个句子重写一遍，把 *es* 放在正确的位置。有一个句子本来就是对的：这时原样写出它。","reading":[{"label":"E-Mail","text":"Liebe Saskia\nist schon ein paar Monate her, dass ich Dir das letzte Mal geschrieben habe. Ich hoffe, dass euch gut geht. Seit wir in Gossau leben, ist viel passiert. Jetzt läuft ganz gut, aber am Anfang gab viele Probleme. Für unsere Kinder war besonders schwer. Sie haben ihre Freunde sehr vermisst und hatten Probleme mit der Sprache. Aber jetzt ist schon viel besser und sie haben sich an das Leben hier gewöhnt. Sie gehen ja jetzt auch zur Schule und haben andere Kinder kennengelernt. Übrigens gehe ich jetzt auch wieder in eine Schule – in eine Sprachschule. Ich besuche einen B1-Kurs. Das macht mir grosse Freude. So, jetzt ist gleich 9 Uhr. Ich muss Schluss machen. Mein Kurs fängt in einer halben Stunde an.\nBis bald, Deine Fatima"}],"example":[{"label":"Beispiel","text":"**Es** ist schon ein paar Monate her, dass ich Dir das letzte Mal geschrieben habe."}],"items":[{"label":"1","lead":"Ich hoffe, dass euch gut geht.","text":"","accept":["Ich hoffe, dass es euch gut geht."],"solution":"**Ich hoffe, dass es euch gut geht.**","en":"我希望你们一切都好。","why":"*Wie geht es euch?* → *dass es euch gut geht*：*es* 是 *gehen* 在这个意思下的主语，不能省略。","source":"platzhalter"},{"label":"2","lead":"Seit wir in Gossau leben, ist viel passiert.","text":"","accept":["Seit wir in Gossau leben, ist viel passiert."],"solution":"**Seit wir in Gossau leben, ist viel passiert.**","en":"自从我们住在 Gossau 以来，发生了很多事。","why":"不用 *es*：*viel* 是主语，*seit* 从句占了第 1 位。","source":"platzhalter"},{"label":"3","lead":"Jetzt läuft ganz gut, aber am Anfang gab viele Probleme.","text":"","accept":["Jetzt läuft es ganz gut, aber am Anfang gab es viele Probleme."],"solution":"**Jetzt läuft es ganz gut, aber am Anfang gab es viele Probleme.**","en":"现在一切都挺顺利的，但一开始有很多问题。","why":"两个空：*es läuft gut*（事情进展顺利）和 *es gab*（有，*es gibt* 的过去时）。*jetzt* / *am Anfang* 在第 1 位时，*es* 放在动词后面。","source":"platzhalter"},{"label":"4","lead":"Für unsere Kinder war besonders schwer.","text":"","accept":["Für unsere Kinder war es besonders schwer."],"solution":"**Für unsere Kinder war es besonders schwer.**","en":"对我们的孩子来说，这尤其困难。","why":"*es* + *sein* + 形容词：*es war schwer*。","source":"platzhalter"},{"label":"5","lead":"Aber jetzt ist schon viel besser und sie haben sich an das Leben hier gewöhnt.","text":"","accept":["Aber jetzt ist es schon viel besser und sie haben sich an das Leben hier gewöhnt."],"solution":"**Aber jetzt ist es schon viel besser und sie haben sich an das Leben hier gewöhnt.**","en":"不过现在已经好多了，他们也已经习惯了这里的生活。","why":"*es ist besser*：这种情况没有别的主语，所以需要 *es*。","source":"platzhalter"},{"label":"6","lead":"So, jetzt ist gleich 9 Uhr.","text":"","accept":["So, jetzt ist es gleich 9 Uhr."],"solution":"**So, jetzt ist es gleich 9 Uhr.**","en":"好了，现在马上就 9 点了。","why":"钟点：*es ist 9 Uhr*。","source":"platzhalter"}]}]},{"page":"AB 151","heading":"A  Es ist nicht leicht, aber es lohnt sich.","heading_en":"这并不容易，但是值得。","exercises":[{"no":"4","tag":"A3","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"哪个是对的？阅读关于村里聚会的短文，在每个空里填上合适的词。两个选项写在每个句子的上方。","reading":[{"label":"Stammtisch der Kulturen","text":"In unserem Dorf gibt es seit einiger Zeit am ersten Freitag im Monat einen Stammtisch der Kulturen. Dahin kommen alle, die Interesse an einem (a) Treffen mit Menschen aus aller Welt haben. Der Stammtisch ist ein grosser Erfolg geworden. Das war nicht immer so. Am Anfang war es eigentlich ein (b) und es kamen nur sehr wenige Teilnehmer. Es waren (c) fünf bis zehn da. Es war einfach so, dass die Leute aus der Region zuerst dachten, dass das Treffen nur für Migranten ist. Inzwischen kommen aber auch immer mehr Schweizer, (d) sind es oft sogar über 30 Leute pro Treffen. Alle helfen gratis mit und so funktioniert der Stammtisch ohne (e) Unterstützung."}],"example":[{"label":"a","text":"Dahin kommen alle, die Interesse an einem **interkulturellen** Treffen mit Menschen aus aller Welt haben."}],"items":[{"label":"b","lead":"Heimweh / Experiment","text":"Am Anfang war es eigentlich ein ___ und es kamen nur sehr wenige Teilnehmer.","gaps":[["Experiment"]],"solution":"Am Anfang war es eigentlich ein **Experiment** und es kamen nur sehr wenige Teilnehmer.","en":"一开始这其实是一次尝试，来参加的人非常少。","why":"*Heimweh*（想家）在这里说不通；一个可能成功也可能失败的新想法是 *Experiment*（尝试）。","source":"hueber"},{"label":"c","lead":"mindestens / höchstens","text":"Es waren ___ fünf bis zehn da.","gaps":[["höchstens"]],"solution":"Es waren **höchstens** fünf bis zehn da.","en":"最多只有五到十个人在场。","why":"*nur sehr wenige* → *höchstens*（最多），不是 *mindestens*（至少）。","source":"hueber"},{"label":"d","lead":"mindestens / mittlerweile","text":"Inzwischen kommen aber auch immer mehr Schweizer, ___ sind es oft sogar über 30 Leute pro Treffen.","gaps":[["mittlerweile"]],"solution":"Inzwischen kommen aber auch immer mehr Schweizer, **mittlerweile** sind es oft sogar über 30 Leute pro Treffen.","en":"不过现在来的瑞士人也越来越多了，如今每次聚会甚至常常有 30 多个人。","why":"*mittlerweile* = 如今、在此期间（和 *inzwischen* 一样）。","source":"hueber"},{"label":"e","lead":"finanzielle / spezielle","text":"Alle helfen gratis mit und so funktioniert der Stammtisch ohne ___ Unterstützung.","gaps":[["finanzielle"]],"solution":"Alle helfen gratis mit und so funktioniert der Stammtisch ohne **finanzielle** Unterstützung.","en":"大家都免费帮忙，所以这个聚会不需要经济资助也能办下去。","why":"*gratis*（免费）→ 不需要钱：*finanzielle Unterstützung*。","source":"hueber"}]},{"no":"5","tag":"A3","instruction":"Ergänzen Sie.","instruction_en":"补全句子。课本给出了每个词的一些字母（写在句子上方）；写出完整的词。","example":[{"label":"c","text":"Ich mag den Frühling und den Sommer. Aber der Winter ist für mich die schönste **Jahreszeit**."}],"items":[{"label":"a","lead":"H _ _ _ _ h","text":"Ich bin traurig, weil ich nicht zu Hause bin. Ich habe ___.","gaps":[["Heimweh"]],"solution":"Ich bin traurig, weil ich nicht zu Hause bin. Ich habe **Heimweh**.","en":"我很难过，因为我不在家。我想家了。","why":"*das Heimweh* = 想家；*Heimweh haben*。","source":"hueber"},{"label":"b","lead":"G _ _ _ r _ _","text":"Das Wichtigste beim Kochen von indischen Gerichten sind die richtigen ___.","gaps":[["Gewürze"]],"solution":"Das Wichtigste beim Kochen von indischen Gerichten sind die richtigen **Gewürze**.","en":"做印度菜时最重要的是合适的香料。","why":"*das Gewürz, die Gewürze* = 香料；因为后面是 *sind*，所以用复数。","source":"hueber"},{"label":"d","lead":"G _ _ _ _ ä _ _ _ _ _ _ _ e","text":"Meine Grosseltern hatten mehrere Geschäfte. Sie waren erfolgreiche ___.","gaps":[["Geschäftsleute"]],"solution":"Meine Grosseltern hatten mehrere Geschäfte. Sie waren erfolgreiche **Geschäftsleute**.","en":"我的祖父母有好几家店。他们是成功的生意人。","why":"*die Geschäftsleute* = *der Geschäftsmann / die Geschäftsfrau* 的复数。","source":"hueber"},{"label":"e","lead":"R _ _ _ _ c _ _ _","text":"Unser Nachbar hört zu jeder Tageszeit laute Musik. Das stört uns alle, aber er nimmt keine ___.","gaps":[["Rücksicht"]],"solution":"Unser Nachbar hört zu jeder Tageszeit laute Musik. Das stört uns alle, aber er nimmt keine **Rücksicht**.","en":"我们的邻居一天到晚都在放很吵的音乐。这让我们大家都很烦，可他一点也不顾及别人。","why":"*Rücksicht nehmen (auf)* = 顾及、体谅（某人）。","source":"hueber"},{"label":"f","lead":"f _ _ _ _ z _ _ _ _ _ _  R _ _ _ _ _","text":"Wenn man sich mit einem Geschäft selbstständig macht, ist das oft ein ___ ___.","gaps":[["finanzielles"],["Risiko"]],"solution":"Wenn man sich mit einem Geschäft selbstständig macht, ist das oft ein **finanzielles** **Risiko**.","en":"如果自己开店创业，这往往是一种经济风险。","why":"*das Risiko* 是中性，所以是 *ein finanzielles Risiko*。","source":"hueber"},{"label":"g","lead":"l _ _ _","text":"Mein Onkel hat viele gute Ideen. Er ___ fast jedes Problem.","gaps":[["löst"]],"solution":"Mein Onkel hat viele gute Ideen. Er **löst** fast jedes Problem.","en":"我叔叔有很多好主意。他几乎能解决所有问题。","why":"*ein Problem lösen* = 解决问题；*er löst*。","source":"hueber"}]},{"no":"6","tag":"A4","instruction":"Buchstaben und Laute: *b – p, g – k, d – t*","instruction_en":"字母和发音：*b – p, g – k, d – t*。（a 和 b 部分是听力练习，已略去。）","part":"c","part_instruction":"Ergänzen Sie die Regel.","part_instruction_en":"补全规则：*b, d, g* 在词尾怎么发音？看看 *halb, Geld, Tag*。","items":[{"label":"c","text":"Am Wortende spricht man *b, d, g* wie ___.","gaps":[["p, t, k","p t k","p, t und k","p,t,k"]],"solution":"Am Wortende spricht man *b, d, g* wie **p, t, k**.","en":"在词尾，*b, d, g* 读作 *p, t, k*。","why":"*halb* 听起来像 “halp”，*Geld* 像 “Gelt”，*Tag* 像 “Tak”。在另一个辅音前面也是这样：*Erfolg*、*Auftrag*、*ab und zu*。","source":"hueber"}]}]},{"page":"AB 152","heading":"B  Ich will bei dem Geschäft sein, um dort zu warten.","heading_en":"我想到店门口去，好在那里等着。","exercises":[{"no":"7","tag":"B1","instruction":"Margaretas Ziele. Ergänzen Sie.","instruction_en":"Margareta 的目标。每一行左边是一个愿望，右边是用 *um … zu* 表达的同一个目的。填写缺少的那一边。","example":[{"label":"a","lead":"Wozu ist Margareta in die Schweiz gekommen?","text":"Sie möchte ihr Deutsch verbessern. → Margareta ist in die Schweiz gekommen, **um** ihr Deutsch **zu verbessern**."}],"items":[{"label":"b","text":"Sie ___ eine Ausbildung ___. → um eine Ausbildung zu machen.","gaps":[["möchte"],["machen"]],"solution":"Sie **möchte** eine Ausbildung **machen**. → um eine Ausbildung zu machen.","en":"她想接受职业培训。→ 为了接受职业培训。","why":"愿望：*möchte* + 句末的不定式。*um … zu* 去掉了情态动词。","source":"g6865"},{"label":"c","text":"Sie möchte selbstständiger werden. → ___ selbstständiger ___.","gaps":[["um"],["zu werden"]],"solution":"Sie möchte selbstständiger werden. → **um** selbstständiger **zu werden**.","en":"她想变得更独立。→ 为了变得更独立。","why":"*um* 开启词组，*zu* + 不定式结束词组。*möchte* 消失了。","source":"g6865"},{"label":"d","text":"Sie ___ Geld ___. → um Geld zu verdienen.","gaps":[["möchte"],["verdienen"]],"solution":"Sie **möchte** Geld **verdienen**. → um Geld zu verdienen.","en":"她想挣钱。→ 为了挣钱。","why":"还原成愿望：*Sie möchte Geld verdienen.*","source":"g6865"},{"label":"e","text":"Sie möchte in der Nähe ihres Freundes sein. → ___ in der Nähe ihres Freundes ___.","gaps":[["um"],["zu sein"]],"solution":"Sie möchte in der Nähe ihres Freundes sein. → **um** in der Nähe ihres Freundes **zu sein**.","en":"她想待在男朋友身边。→ 为了待在男朋友身边。","why":"*um … zu sein*；*in der Nähe* 后面的 *ihres Freundes* 是第二格。","source":"g6865"}]},{"no":"8","tag":"B1","instruction":"Wozu machen die Leute das? Ordnen Sie zu und ergänzen Sie die Sätze mit *um … zu*.","instruction_en":"这些人为什么这样做？从方框里选出适合每个句子的目的，用 *um … zu* + 不定式加上去。*gesund bleiben* 已用在例句中。","phrases":["frische Zutaten und Gewürze kaufen","als Erster im Büro sein","gesund bleiben (Beispiel)","einen wichtigen Kunden treffen","bessere Chancen auf dem Arbeitsmarkt haben"],"example":[{"label":"a","text":"Miguel geht dreimal pro Woche ins Fitnessstudio, **um gesund zu bleiben**."}],"items":[{"label":"b","text":"Peter steht von Montag bis Freitag sehr früh auf, ___.","gaps":[["um als Erster im Büro zu sein"]],"solution":"Peter steht von Montag bis Freitag sehr früh auf, **um als Erster im Büro zu sein**.","en":"Peter 从星期一到星期五都很早起床，为了第一个到办公室。","why":"同一个人（Peter），所以用 *um … zu*；*sein* 带着 *zu* 放在最后。","source":"g6865"},{"label":"c","text":"Am Wochenende gehe ich immer auf den Markt, ___.","gaps":[["um frische Zutaten und Gewürze zu kaufen"]],"solution":"Am Wochenende gehe ich immer auf den Markt, **um frische Zutaten und Gewürze zu kaufen**.","en":"周末我总是去市场，为了买新鲜的食材和香料。","why":"所有属于 *kaufen* 的成分都放在 *zu kaufen* 前面。","source":"g6865"},{"label":"d","text":"Herr Aryan fährt morgen nach Genf, ___.","gaps":[["um einen wichtigen Kunden zu treffen"]],"solution":"Herr Aryan fährt morgen nach Genf, **um einen wichtigen Kunden zu treffen**.","en":"Aryan 先生明天去日内瓦，为了见一位重要的客户。","why":"*um … zu treffen*；宾语 *einen wichtigen Kunden* 放在中间。","source":"g6865"},{"label":"e","text":"Sabina macht eine berufliche Weiterbildung, ___.","gaps":[["um bessere Chancen auf dem Arbeitsmarkt zu haben"]],"solution":"Sabina macht eine berufliche Weiterbildung, **um bessere Chancen auf dem Arbeitsmarkt zu haben**.","en":"Sabina 在参加职业进修，为了在就业市场上有更好的机会。","why":"同一个人（Sabina）：*um … zu haben*。","source":"g6865"}]},{"no":"9","tag":"B1","instruction":"Wozu ist Yaroslav in die Schweiz gekommen?","instruction_en":"Yaroslav 为什么来瑞士？","part":"a","part_instruction":"Lesen Sie den Text und ergänzen Sie die Gründe.","part_instruction_en":"阅读短文，用文中的词补全理由。","reading":[{"label":"Abenteuer Ausland: Wozu sind Sie in die Schweiz gekommen? – Yaroslav Ivanenko, 38","text":"Meine Frau und ich wollten schon lange eine neue Perspektive im Leben finden. Meine Frau wollte zum Beispiel gern in einer Stadt im Ausland leben. Bei mir war das anders. Ich bin IT-Spezialist und habe jahrelang als Programmierer in einer Softwarefirma gearbeitet. In unserem Land gibt es aber weniger Entwicklungsmöglichkeiten für meine Berufsbranche. Auch für unsere Kinder habe ich mir gewünscht, dass sie einmal eine gute Schule besuchen können. Aber die sind in unserer Heimat teuer. In einem internationalen Job-Portal im Internet habe ich dann gesehen, dass in der Schweiz Programmierer gesucht werden. Ich habe mich bei mehreren Firmen beworben und hatte grosses Glück. Gleich eins der ersten Vorstellungsgespräche, das ich über Skype geführt habe, war so positiv, dass ich von der Firma sofort ein Jobangebot erhalten habe. Die erste Zeit habe ich noch von der Ukraine aus gearbeitet, aber nach meiner Probezeit habe ich über die Firma eine offizielle Arbeitsbewilligung für die Schweiz bekommen. Mein Chef wollte unbedingt, dass das ganze Programmiererteam in Zug ist. So haben wir uns entschlossen, mit den Kindern in die Schweiz zu ziehen. Es war nicht immer leicht für uns, aber jetzt sind wir einfach nur dankbar, dass wir diese Chance bekommen haben."}],"example":[{"label":"1","text":"Yaroslav und seine Frau können **eine neue Perspektive** finden."}],"items":[{"label":"2","text":"Seine Frau kann ___ leben.","gaps":[["in einer Stadt im Ausland"]],"solution":"Seine Frau kann **in einer Stadt im Ausland** leben.","en":"他的妻子可以在国外的一座城市生活。","why":"*Meine Frau wollte zum Beispiel gern in einer Stadt im Ausland leben.*","source":"hueber"},{"label":"3","text":"Seine Kinder können ___ besuchen.","gaps":[["eine gute Schule"]],"solution":"Seine Kinder können **eine gute Schule** besuchen.","en":"他的孩子们可以上一所好学校。","why":"*… dass sie einmal eine gute Schule besuchen können.*","source":"hueber"},{"label":"4","text":"Das ganze Programmiererteam ist ___.","gaps":[["in Zug"]],"solution":"Das ganze Programmiererteam ist **in Zug**.","en":"整个程序员团队都在 Zug。","why":"*Mein Chef wollte unbedingt, dass das ganze Programmiererteam in Zug ist.*","source":"hueber"}]}]},{"page":"AB 153","heading":"B  Ich will bei dem Geschäft sein, um dort zu warten.","heading_en":"我想到店门口去，好在那里等着。","exercises":[{"no":"9","part":"b","part_instruction":"Schreiben Sie die Sätze neu mit *damit*.","part_instruction_en":"把 a 中的理由改写成 *damit* 从句：*Yaroslav ist in die Schweiz gekommen, damit …* 动词放在句末。","example":[{"label":"1","text":"Yaroslav ist in die Schweiz gekommen, **damit er und seine Frau eine neue Perspektive finden können**."}],"items":[{"label":"2","lead":"Seine Frau kann in einer Stadt im Ausland leben.","text":"","accept":["Yaroslav ist in die Schweiz gekommen, damit seine Frau in einer Stadt im Ausland leben kann.","damit seine Frau in einer Stadt im Ausland leben kann.","damit seine Frau in einer Stadt im Ausland leben kann"],"solution":"**Yaroslav ist in die Schweiz gekommen, damit seine Frau in einer Stadt im Ausland leben kann.**","en":"Yaroslav 来到瑞士，好让他的妻子能在国外的一座城市生活。","why":"不同的人（他的妻子），所以只能用 *damit*；*kann* 放在最末尾。","source":"damit"},{"label":"3","lead":"Seine Kinder können eine gute Schule besuchen.","text":"","accept":["Yaroslav ist in die Schweiz gekommen, damit seine Kinder eine gute Schule besuchen können.","damit seine Kinder eine gute Schule besuchen können.","damit seine Kinder eine gute Schule besuchen können"],"solution":"**Yaroslav ist in die Schweiz gekommen, damit seine Kinder eine gute Schule besuchen können.**","en":"Yaroslav 来到瑞士，好让他的孩子们能上一所好学校。","why":"不同的人（他的孩子们）：*damit … besuchen können*。","source":"damit"},{"label":"4","lead":"Das ganze Programmiererteam ist in Zug.","text":"","accept":["Yaroslav ist in die Schweiz gekommen, damit das ganze Programmiererteam in Zug ist.","damit das ganze Programmiererteam in Zug ist.","damit das ganze Programmiererteam in Zug ist"],"solution":"**Yaroslav ist in die Schweiz gekommen, damit das ganze Programmiererteam in Zug ist.**","en":"Yaroslav 来到瑞士，好让整个程序员团队都在 Zug。","why":"不同的主语（团队）：*damit … ist*。","source":"damit"}]},{"no":"10","tag":"B1","instruction":"Warum steht Yaroslav früh auf? Lesen Sie und markieren Sie wie im Beispiel. Ergänzen Sie Sätze mit *damit* und *um … zu*, wenn möglich.","instruction_en":"Yaroslav 为什么早起？看看是谁做第二个动作。同一个人：*damit* 和 *um … zu* 都写出来。不同的人：只能用 *damit*。","example":[{"label":"A","lead":"Yaroslav steht früh auf. Er will vor der Arbeit joggen.","text":"Yaroslav steht früh auf, **damit er vor der Arbeit joggen kann**. / Yaroslav steht früh auf, **um vor der Arbeit zu joggen**."},{"label":"B","lead":"Yaroslav steht früh auf. Seine Kinder sollen pünktlich aus dem Haus gehen.","text":"Yaroslav steht früh auf, **damit seine Kinder pünktlich aus dem Haus gehen**."}],"items":[{"label":"A2","lead":"Yaroslav steht früh auf. Er will in Ruhe seinen Kaffee trinken.","text":"Yaroslav steht früh auf, damit ___.","gaps":[["er in Ruhe seinen Kaffee trinken kann","er seinen Kaffee in Ruhe trinken kann"]],"solution":"Yaroslav steht früh auf, damit **er in Ruhe seinen Kaffee trinken kann**.","en":"Yaroslav 早起，这样他就能安安静静地喝咖啡。","why":"同一个人（*er*）。在 *damit* 从句里 *will* 变成 *kann*；动词放在句末。","source":"damit"},{"label":"A3","lead":"Yaroslav steht früh auf. Er will in Ruhe seinen Kaffee trinken.","text":"Yaroslav steht früh auf, ___.","gaps":[["um in Ruhe seinen Kaffee zu trinken","um seinen Kaffee in Ruhe zu trinken"]],"solution":"Yaroslav steht früh auf, **um in Ruhe seinen Kaffee zu trinken**.","en":"Yaroslav 早起，为了安安静静地喝咖啡。","why":"同一个人，所以也可以用 *um … zu*：没有主语，也没有 *will*。","source":"g6865"},{"label":"B2","lead":"Yaroslav steht früh auf. Das Badezimmer soll dann für die Familie frei sein.","text":"Yaroslav steht früh auf, ___.","gaps":[["damit das Badezimmer dann für die Familie frei ist","damit das Badezimmer für die Familie frei ist"]],"solution":"Yaroslav steht früh auf, **damit das Badezimmer dann für die Familie frei ist**.","en":"Yaroslav 早起，这样之后浴室就能空出来给家人用。","why":"不同的主语（*das Badezimmer*）：只能用 *damit*。*soll* 要去掉：*damit … frei ist*。","source":"damit"}]},{"no":"11","tag":"B1","instruction":"Eine typische Woche von Marcello und seiner Familie. Schreiben Sie Sätze mit *damit* und *um … zu*, wenn möglich.","instruction_en":"Marcello（A）、他的妻子（B）和他们的孩子（C）典型的一周。把每两句合成一个句子。如果是同一个人，就用 *um … zu*，否则用 *damit*。两种都可以的地方，写哪一种都算对。","example":[{"label":"A1","lead":"Ich gehe am Morgen früh zur Arbeit. Ich möchte am Abend nicht so spät nach Hause kommen.","text":"Ich gehe am Morgen früh zur Arbeit, **damit ich am Abend nicht so spät nach Hause komme**. / Ich gehe am Morgen früh zur Arbeit, **um am Abend nicht so spät nach Hause zu kommen**."}],"items":[{"label":"A2","lead":"Marcello: Ich fahre einmal pro Woche zum Supermarkt. Meine Frau muss die schweren Einkäufe nicht machen.","text":"","accept":["Ich fahre einmal pro Woche zum Supermarkt, damit meine Frau die schweren Einkäufe nicht machen muss."],"solution":"**Ich fahre einmal pro Woche zum Supermarkt, damit meine Frau die schweren Einkäufe nicht machen muss.**","en":"我每周开车去一次超市，这样我妻子就不用去买那些重的东西。","why":"不同的人（*meine Frau*）：只能用 *damit*。这里 *muss* 保留，因为它承载着意思（*nicht machen muss* = 不必做）。","source":"damit"},{"label":"B1","lead":"Frau: Ich koche am Mittag zu Hause. Die Kinder sollen etwas Warmes zu essen haben, wenn sie von der Schule kommen.","text":"","accept":["Ich koche am Mittag zu Hause, damit die Kinder etwas Warmes zu essen haben, wenn sie von der Schule kommen."],"solution":"**Ich koche am Mittag zu Hause, damit die Kinder etwas Warmes zu essen haben, wenn sie von der Schule kommen.**","en":"我中午在家做饭，这样孩子们放学回家时就有热饭吃。","why":"不同的人（*die Kinder*）：用 *damit*；*sollen* 要去掉。","source":"damit"},{"label":"B2","lead":"Frau: Ich verbessere mein Deutsch in einem Sprachkurs. Ich will im Alltag gut zurechtkommen.","text":"","accept":["Ich verbessere mein Deutsch in einem Sprachkurs, um im Alltag gut zurechtzukommen.","Ich verbessere mein Deutsch in einem Sprachkurs, damit ich im Alltag gut zurechtkomme."],"solution":"**Ich verbessere mein Deutsch in einem Sprachkurs, um im Alltag gut zurechtzukommen.**","en":"我在语言班里提高德语，为了在日常生活中应付自如。","why":"同一个人：两种都可以。*zurechtkommen* 是可分动词：*zurecht**zu**kommen*。*will* 要去掉。","source":"g6865"},{"label":"C1","lead":"Kinder: Wir lernen nach der Schule viel am Nachmittag. Wir wollen gute Noten haben und einen guten Abschluss machen.","text":"","accept":["Wir lernen nach der Schule viel am Nachmittag, um gute Noten zu haben und einen guten Abschluss zu machen.","Wir lernen nach der Schule viel am Nachmittag, damit wir gute Noten haben und einen guten Abschluss machen."],"solution":"**Wir lernen nach der Schule viel am Nachmittag, um gute Noten zu haben und einen guten Abschluss zu machen.**","en":"我们放学后下午学习很多，为了取得好成绩、拿到好的毕业文凭。","why":"同一个人（*wir*）：两种都可以。有两个动词时，每个动词都有自己的 *zu*。","source":"g6865"},{"label":"C2","lead":"Kinder: Wir helfen im Haushalt. Mama soll nicht alles allein machen.","text":"","accept":["Wir helfen im Haushalt, damit Mama nicht alles allein macht.","Wir helfen im Haushalt, damit Mama nicht alles allein machen muss."],"solution":"**Wir helfen im Haushalt, damit Mama nicht alles allein macht.**","en":"我们帮忙做家务，这样妈妈就不用一个人做所有的事。","why":"不同的人（*Mama*）：只能用 *damit*；*soll* 要去掉。","source":"damit"}]}]},{"page":"AB 154","heading":"B  Ich will bei dem Geschäft sein, um dort zu warten.","heading_en":"我想到店门口去，好在那里等着。","exercises":[{"no":"12","tag":"B1","marker":"◇","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"哪个是对的？填 *um* 或 *damit*。看句子末尾：*zu* + 不定式要用 *um*；变位动词在句末要用 *damit*。","example":[{"label":"a","text":"Frau Alt betreut ihre Enkel zu Hause, **damit** ihre Tochter berufstätig sein kann."}],"items":[{"label":"b","text":"Jaime lernt und arbeitet viel, ___ sich bald selbstständig zu machen.","gaps":[["um"]],"solution":"Jaime lernt und arbeitet viel, **um** sich bald selbstständig zu machen.","en":"Jaime 学习和工作都很努力，为了不久后自己创业。","why":"末尾是 *zu machen* → *um*。","source":"g6865"},{"label":"c","text":"Said lernt neben Deutsch auch Englisch, ___ bessere Chancen auf dem Arbeitsmarkt zu haben.","gaps":[["um"]],"solution":"Said lernt neben Deutsch auch Englisch, **um** bessere Chancen auf dem Arbeitsmarkt zu haben.","en":"Said 除了德语还学英语，为了在就业市场上有更好的机会。","why":"末尾是 *zu haben* → *um*。","source":"g6865"},{"label":"d","text":"Irina arbeitet jetzt Vollzeit, ___ ihr Mann eine teure Weiterbildung machen kann.","gaps":[["damit"]],"solution":"Irina arbeitet jetzt Vollzeit, **damit** ihr Mann eine teure Weiterbildung machen kann.","en":"Irina 现在做全职工作，好让她丈夫能参加一个昂贵的进修课程。","why":"新的主语 *ihr Mann*，*kann* 在句末 → *damit*。","source":"damit"},{"label":"e","text":"Herr Pfister bezahlt viel Geld, ___ seine Eltern von einer privaten Pflegehelferin gepflegt werden.","gaps":[["damit"]],"solution":"Herr Pfister bezahlt viel Geld, **damit** seine Eltern von einer privaten Pflegehelferin gepflegt werden.","en":"Pfister 先生花很多钱，好让他的父母由一位私人护理员照顾。","why":"新的主语 *seine Eltern*，被动态 *gepflegt werden* 在句末 → *damit*。","source":"damit"}]},{"no":"13","tag":"B1","marker":"◆","instruction":"Wozu macht Marcello das?","instruction_en":"Marcello 为什么这样做？","part":"a","part_instruction":"Verbinden Sie.","part_instruction_en":"把 Marcello 做的每件事（1–6）和受益的人（*Er, Seine Frau, Sein Team*）以及目的（a–f）配对。先写人，再写字母。","phrases":["Er","Seine Frau","Sein Team","a soll abends etwas Ruhe haben.","b kann das gemeinsame Projekt pünktlich abschliessen.","c will wochentags früher gehen.","d kann tagsüber die Einkäufe mit dem Auto erledigen.","e kann ungestört seinen Arbeitstag planen.","f will fit bleiben."],"example":[{"label":"1","text":"Marcello geht dreimal pro Woche joggen. → **Er**, **f**"}],"items":[{"label":"2","text":"Er ist als Erster im Büro. → ___, ___","gaps":[["Er"],["e"]],"solution":"Er ist als Erster im Büro. → **Er**, **e**","en":"他第一个到办公室。→ 他，e（可以不受打扰地安排他的工作日）。","why":"办公室里没人，就不会被打扰。","source":"hueber"},{"label":"3","text":"Er lässt das Auto zu Hause. → ___, ___","gaps":[["Seine Frau"],["d"]],"solution":"Er lässt das Auto zu Hause. → **Seine Frau**, **d**","en":"他把车留在家里。→ 他的妻子，d（白天可以开车去购物）。","why":"他不开车，他的妻子就能用车。","source":"hueber"},{"label":"4","text":"Er macht manchmal Überstunden. → ___, ___","gaps":[["Sein Team"],["b"]],"solution":"Er macht manchmal Überstunden. → **Sein Team**, **b**","en":"他有时加班。→ 他的团队，b（可以按时完成共同的项目）。","why":"加班对共同的项目有帮助。","source":"hueber"},{"label":"5","text":"Er arbeitet auch mal am Samstag. → ___, ___","gaps":[["Er"],["c"]],"solution":"Er arbeitet auch mal am Samstag. → **Er**, **c**","en":"他有时星期六也上班。→ 他，c（想在工作日早点下班）。","why":"星期六上班，换来工作日早点下班。","source":"hueber"},{"label":"6","text":"Er bringt die Kinder ins Bett. → ___, ___","gaps":[["Seine Frau"],["a"]],"solution":"Er bringt die Kinder ins Bett. → **Seine Frau**, **a**","en":"他哄孩子们上床睡觉。→ 他的妻子，a（晚上应该能清静一下）。","why":"晚上她能清静一下。","source":"hueber"}]},{"no":"13","part":"b","part_instruction":"Schreiben Sie Sätze mit *damit* und *um … zu*, wenn möglich.","part_instruction_en":"用你在 a 中的答案写句子。同一个人（*Er*）：用 *um … zu* 或 *damit*。另一个人：只能用 *damit*。去掉 *will* 和 *soll*。","example":[{"label":"1","text":"Marcello geht dreimal pro Woche joggen, **damit er fit bleibt**. / Marcello geht dreimal pro Woche joggen, **um fit zu bleiben**."}],"items":[{"label":"2","lead":"Er ist als Erster im Büro. / Er kann ungestört seinen Arbeitstag planen.","text":"","accept":["Er ist als Erster im Büro, um ungestört seinen Arbeitstag zu planen.","Er ist als Erster im Büro, damit er ungestört seinen Arbeitstag planen kann.","Marcello ist als Erster im Büro, um ungestört seinen Arbeitstag zu planen."],"solution":"**Er ist als Erster im Büro, um ungestört seinen Arbeitstag zu planen.**","en":"他第一个到办公室，为了不受打扰地安排他的工作日。","why":"同一个人：两种都可以。","source":"g6865"},{"label":"3","lead":"Er lässt das Auto zu Hause. / Seine Frau kann tagsüber die Einkäufe mit dem Auto erledigen.","text":"","accept":["Er lässt das Auto zu Hause, damit seine Frau tagsüber die Einkäufe mit dem Auto erledigen kann."],"solution":"**Er lässt das Auto zu Hause, damit seine Frau tagsüber die Einkäufe mit dem Auto erledigen kann.**","en":"他把车留在家里，这样他的妻子白天就能开车去办事购物。","why":"另一个人：只能用 *damit*。","source":"damit"},{"label":"4","lead":"Er macht manchmal Überstunden. / Sein Team kann das gemeinsame Projekt pünktlich abschliessen.","text":"","accept":["Er macht manchmal Überstunden, damit sein Team das gemeinsame Projekt pünktlich abschliessen kann."],"solution":"**Er macht manchmal Überstunden, damit sein Team das gemeinsame Projekt pünktlich abschliessen kann.**","en":"他有时加班，这样他的团队就能按时完成共同的项目。","why":"另一个主语：只能用 *damit*。","source":"damit"},{"label":"5","lead":"Er arbeitet auch mal am Samstag. / Er will wochentags früher gehen.","text":"","accept":["Er arbeitet auch mal am Samstag, um wochentags früher zu gehen.","Er arbeitet auch mal am Samstag, damit er wochentags früher gehen kann."],"solution":"**Er arbeitet auch mal am Samstag, um wochentags früher zu gehen.**","en":"他有时星期六也上班，为了在工作日早点下班。","why":"同一个人：两种都可以；*will* 要去掉。","source":"g6865"},{"label":"6","lead":"Er bringt die Kinder ins Bett. / Seine Frau soll abends etwas Ruhe haben.","text":"","accept":["Er bringt die Kinder ins Bett, damit seine Frau abends etwas Ruhe hat."],"solution":"**Er bringt die Kinder ins Bett, damit seine Frau abends etwas Ruhe hat.**","en":"他哄孩子们上床睡觉，这样他的妻子晚上就能清静一下。","why":"另一个人：用 *damit*；*soll* 要去掉。","source":"damit"}]},{"no":"14","tag":"B3","instruction":"Beruf und Karriere – was ist wichtig, um Erfolg im Job zu haben? Markieren Sie noch fünf Wörter und ordnen Sie zu.","instruction_en":"职业与事业：在工作中取得成功，什么最重要？在字母格里再找出五个词，补全句子。*Kompetenzen* 是例子。形容词用小写。","reading":[{"label":"Buchstabengitter","text":"DLKJLDGDKJLKDLGKOMPETENZENLLSKOMMUNIKATIVEDJG\nLSKDENGAGEMENTJGKDÖLGÖGLLKGLKONFLIKTFÄHIGLÖFJA\nFLAGJSTEAMFÄHIGJGSLGJSLMOTIVATIONSLGSLKGDJAFJFLA"}],"example":[{"label":"a","text":"Personalfachleute sagen: Man braucht nicht nur fachliche, sondern auch soziale **Kompetenzen**, wenn man im Beruf erfolgreich sein will."}],"items":[{"label":"b","text":"Zum Beispiel ist es wichtig, dass eine Person gut im Team arbeiten kann und auch Kompromisse eingeht. Dann ist sie ___.","gaps":[["teamfähig"]],"solution":"Zum Beispiel ist es wichtig, dass eine Person gut im Team arbeiten kann und auch Kompromisse eingeht. Dann ist sie **teamfähig**.","en":"比如说，一个人能在团队里好好合作，也能做出妥协，这很重要。这样他就有团队精神。","why":"*teamfähig* = 能在团队中合作的。","source":"hueber"},{"label":"c","text":"Wenn sich Kollegen streiten, aber schliesslich gemeinsam eine gute Lösung für ihr Problem finden, dann sind sie ___.","gaps":[["konfliktfähig"]],"solution":"Wenn sich Kollegen streiten, aber schliesslich gemeinsam eine gute Lösung für ihr Problem finden, dann sind sie **konfliktfähig**.","en":"如果同事们发生争执，但最后一起为他们的问题找到一个好的解决办法，那他们就善于处理冲突。","why":"*konfliktfähig* = 善于处理冲突的。","source":"hueber"},{"label":"d","text":"Wer offen ist, sich gut mit Menschen unterhalten, aber auch gut zuhören kann, hat gute ___ Kompetenzen.","gaps":[["kommunikative"]],"solution":"Wer offen ist, sich gut mit Menschen unterhalten, aber auch gut zuhören kann, hat gute **kommunikative** Kompetenzen.","en":"一个人如果开朗，能和人好好交谈，也善于倾听，他就有良好的沟通能力。","why":"在 *gute* 后面、复数名词前面的形容词：*kommunikative Kompetenzen*。","source":"hueber"},{"label":"e","text":"Auf jeden Fall muss ein Mitarbeiter ___ und ___ zeigen, um im Beruf erfolgreich zu sein.","gaps":[["Motivation","Engagement"],["Engagement","Motivation"]],"solution":"Auf jeden Fall muss ein Mitarbeiter **Motivation** und **Engagement** zeigen, um im Beruf erfolgreich zu sein.","en":"无论如何，一名员工必须表现出积极性和投入，才能在工作中取得成功。","why":"*die Motivation* 和 *das Engagement*（投入）；顺序可以调换。","source":"hueber"}]}]},{"page":"AB 155","heading":"C  Etwas tun, statt nur zu träumen","heading_en":"做点什么，而不是只做梦","exercises":[{"no":"15","tag":"C1","instruction":"Unzufrieden im Job","instruction_en":"工作不开心","part":"a","part_instruction":"In welchem Satz steht *nicht/kein*? Markieren Sie.","part_instruction_en":"把两个短句和那个长句比较一下。在 *statt … zu* 或 *ohne … zu* 的说法里，哪个表示“不 / 没有”的词消失了？写出这个词。","example":[{"label":"1","text":"Ich bringe lieber meinen eigenen Laptop mit. Ich benütze **nicht** den alten Computer in der Firma. / Ich bringe lieber meinen eigenen Laptop mit, statt den alten Computer in der Firma zu benützen."}],"items":[{"label":"2","text":"Der Chef hat immer schlechte Laune. Er hat keinen Grund dafür. / Der Chef hat immer schlechte Laune, ohne einen Grund dafür zu haben. → ___","gaps":[["keinen","kein"]],"solution":"Der Chef hat immer schlechte Laune. Er hat keinen Grund dafür. / Der Chef hat immer schlechte Laune, ohne einen Grund dafür zu haben. → **keinen**","en":"老板总是心情不好。他没有理由。/ 老板总是心情不好，却没有任何理由。→ keinen","why":"*ohne* 本身已经是“不”的意思：在 *ohne* 后面，*keinen Grund* 变成 *einen Grund*。","source":"komma"}]},{"no":"15","part":"b","part_instruction":"Welche Sätze sind richtig? Vergleichen Sie mit a und kreuzen Sie an.","part_instruction_en":"哪个结尾是对的？两个选项写在每个句子的上方。写出正确的结尾。","items":[{"label":"1","lead":"statt mich weiter über die Arbeit zu ärgern / statt mich nicht weiter über die Arbeit zu ärgern","text":"Ich wechsle den Job, ___.","gaps":[["statt mich weiter über die Arbeit zu ärgern"]],"solution":"Ich wechsle den Job, **statt mich weiter über die Arbeit zu ärgern**.","en":"我要换工作，而不是继续为工作生气。","why":"*statt* 后面不用 *nicht*：*statt* 已经表示“不是这个”。","source":"komma"},{"label":"2","lead":"ohne den Chef nicht zu informieren / ohne den Chef zu informieren","text":"Ich suche eine neue Stelle, ___.","gaps":[["ohne den Chef zu informieren"]],"solution":"Ich suche eine neue Stelle, **ohne den Chef zu informieren**.","en":"我在找新工作，但不告诉老板。","why":"*ohne* 后面不用 *nicht*：*ohne den Chef nicht zu informieren* 的意思正好相反。","source":"komma"}]},{"no":"16","tag":"C1","instruction":"Homeoffice. Ergänzen Sie die Sätze mit *statt … zu*.","instruction_en":"在家办公。把第二部分（你不做的事）变成 *statt … zu* + 不定式。去掉 *nicht / keine*。","example":[{"label":"a","lead":"Sie können bei der Arbeit eine bequeme Sporthose tragen und müssen keine unbequeme Berufskleidung anziehen.","text":"Sie können bei der Arbeit eine bequeme Sporthose tragen, **statt unbequeme Berufskleidung anzuziehen**."}],"items":[{"label":"b","lead":"Sie haben flexible Arbeitszeiten und arbeiten nicht von 9 bis 17 Uhr.","text":"Sie haben flexible Arbeitszeiten, ___.","gaps":[["statt von 9 bis 17 Uhr zu arbeiten"]],"solution":"Sie haben flexible Arbeitszeiten, **statt von 9 bis 17 Uhr zu arbeiten**.","en":"您的工作时间很灵活，而不是从 9 点工作到 17 点。","why":"*nicht* 消失；*zu arbeiten* 放在最后。","source":"komma"},{"label":"c","lead":"Sie haben keine Fahrtkosten und geben nicht viel Geld für Benzin aus.","text":"Sie haben keine Fahrtkosten, ___.","gaps":[["statt viel Geld für Benzin auszugeben"]],"solution":"Sie haben keine Fahrtkosten, **statt viel Geld für Benzin auszugeben**.","en":"您没有交通费用，而不是花很多钱买汽油。","why":"*ausgeben* 是可分动词：*aus**zu**geben*。","source":"komma"},{"label":"d","lead":"Sie räumen die Wohnung auf und arbeiten nicht.","text":"Sie räumen die Wohnung auf, ___.","gaps":[["statt zu arbeiten"]],"solution":"Sie räumen die Wohnung auf, **statt zu arbeiten**.","en":"您在收拾房子，而不是在工作。","why":"没有其他成分属于 *arbeiten*，所以这个词组只是 *statt zu arbeiten*。","source":"komma"},{"label":"e","lead":"Sie müssen viele Probleme allein lösen und besprechen sie nicht mit Kollegen.","text":"Sie müssen viele Probleme allein lösen, ___.","gaps":[["statt sie mit Kollegen zu besprechen"]],"solution":"Sie müssen viele Probleme allein lösen, **statt sie mit Kollegen zu besprechen**.","en":"您必须一个人解决很多问题，而不是和同事们商量。","why":"*sie* = 这些问题；它留在词组里面。","source":"komma"}]},{"no":"17","tag":"C2","instruction":"Meine fleissige Arbeitskollegin Olga. Schreiben Sie Sätze mit *ohne … zu* und *statt … zu*.","instruction_en":"我勤奋的同事 Olga。把两个句子连起来。她做某件事*来代替*另一件事 → *statt … zu*。某件事*同时*没有发生 → *ohne … zu*。去掉 *nicht / kein*。","example":[{"label":"a","lead":"Sie steht jeden Tag um fünf Uhr auf. Sie beschwert sich nicht.","text":"Sie steht jeden Tag um fünf Uhr auf, **ohne sich zu beschweren**."}],"items":[{"label":"b","lead":"Sie kommt schon um 7 Uhr ins Büro. Sie fängt nicht erst um 9 Uhr an.","text":"","accept":["Sie kommt schon um 7 Uhr ins Büro, statt erst um 9 Uhr anzufangen."],"solution":"**Sie kommt schon um 7 Uhr ins Büro, statt erst um 9 Uhr anzufangen.**","en":"她 7 点就到办公室了，而不是 9 点才开始上班。","why":"7 点代替了 9 点 → *statt*。*anfangen*：*an**zu**fangen*。","source":"komma"},{"label":"c","lead":"Sie fährt immer mit dem Velo zur Arbeit. Sie nimmt nicht das Auto.","text":"","accept":["Sie fährt immer mit dem Velo zur Arbeit, statt das Auto zu nehmen."],"solution":"**Sie fährt immer mit dem Velo zur Arbeit, statt das Auto zu nehmen.**","en":"她总是骑自行车上班，而不是开车。","why":"自行车代替了汽车 → *statt*。（*das Velo* 是瑞士用语，即自行车。）","source":"komma"},{"label":"d","lead":"Sie geht in der Mittagszeit joggen. Sie isst nicht.","text":"","accept":["Sie geht in der Mittagszeit joggen, statt etwas zu essen.","Sie geht in der Mittagszeit joggen, statt zu essen.","Sie geht in der Mittagszeit joggen, ohne etwas zu essen.","Sie geht in der Mittagszeit joggen, ohne zu essen."],"solution":"**Sie geht in der Mittagszeit joggen, statt etwas zu essen.**","en":"她午休时去跑步，而不是吃点东西。","why":"跑步代替了吃午饭 → *statt*。","source":"komma","check":"官方答案是 *statt etwas zu essen*。*ohne etwas zu essen*（她去跑步，什么也不吃）也是正确的德语，在这里意思几乎一样。"},{"label":"e","lead":"Sie arbeitet viele Stunden am Stück. Sie macht keine Pause.","text":"","accept":["Sie arbeitet viele Stunden am Stück, ohne eine Pause zu machen.","Sie arbeitet viele Stunden am Stück, ohne Pause zu machen."],"solution":"**Sie arbeitet viele Stunden am Stück, ohne eine Pause zu machen.**","en":"她一连工作好几个小时，都不休息一下。","why":"她工作时没有休息 → *ohne*。*keine Pause* 变成 *eine Pause*。","source":"komma"},{"label":"f","lead":"Sie sollte sich mehr um sich selbst kümmern. Sie arbeitet so viel.","text":"","accept":["Sie sollte sich mehr um sich selbst kümmern, statt so viel zu arbeiten."],"solution":"**Sie sollte sich mehr um sich selbst kümmern, statt so viel zu arbeiten.**","en":"她应该多照顾自己，而不是工作这么多。","why":"应该用照顾自己来代替工作这么多 → *statt*。","source":"komma"}]}]},{"page":"AB 156","heading":"C  Etwas tun, statt nur zu träumen","heading_en":"做点什么，而不是只做梦","exercises":[{"no":"18","tag":"C2","marker":"◇","instruction":"Morgengewohnheiten. Was ist richtig? Kreuzen Sie an.","instruction_en":"早上的习惯。填 *ohne* 或 *statt*。*statt* = 而不是（一件事代替另一件事）；*ohne* = 没有（某件事同时没有发生）。","example":[{"label":"a","text":"Ich fahre zu jeder Jahreszeit mit dem Velo zur Arbeit, **statt** das Auto zu nehmen."}],"items":[{"label":"b","text":"Ich dusche am Morgen immer kalt, ___ warm zu baden.","gaps":[["statt"]],"solution":"Ich dusche am Morgen immer kalt, **statt** warm zu baden.","en":"我早上总是洗冷水澡，而不是泡热水澡。","why":"冷水澡代替了热水澡。","source":"komma"},{"label":"c","text":"Ich trinke nie Kaffee, ___ Zeitung zu lesen.","gaps":[["ohne"]],"solution":"Ich trinke nie Kaffee, **ohne** Zeitung zu lesen.","en":"我喝咖啡时从来都不会不看报纸。","why":"*nie … ohne* = 我每次喝咖啡都会看报纸。","source":"komma"},{"label":"d","text":"Ich gehe nie aus dem Haus, ___ meinen Regenschirm mitzunehmen.","gaps":[["ohne"]],"solution":"Ich gehe nie aus dem Haus, **ohne** meinen Regenschirm mitzunehmen.","en":"我出门从来不会不带雨伞。","why":"*nie … ohne* = 我总是带着它。","source":"komma"},{"label":"e","text":"Ich bleibe morgens nach dem Aufwachen immer noch eine halbe Stunde liegen, ___ sofort aufzustehen.","gaps":[["statt"]],"solution":"Ich bleibe morgens nach dem Aufwachen immer noch eine halbe Stunde liegen, **statt** sofort aufzustehen.","en":"我早上醒来后总是还要在床上再躺半个小时，而不是马上起床。","why":"躺在床上代替了起床。","source":"komma"}]},{"no":"19","tag":"C2","marker":"◆","instruction":"Was würden Sie in Ihrem Leben gern machen? Schreiben Sie Sätze mit *ohne … zu* und *statt … zu*.","instruction_en":"你这辈子想做什么？把方框左边的一个愿望和右边的一项内容组合起来，用 *ohne … zu* 或 *statt … zu*。划掉的词已用在例句中。参考答案只是一种可能。","box":["beruflich selbstständig sein","mehr Geld verdienen","kaputte Sachen reparieren","eine Wohnung kaufen","mit meiner Familie in der Heimat telefonieren","gut Deutsch sprechen","mit dem Velo fahren","mit meiner Familie zusammenwohnen","…","viele Sprachkurse machen","immer zu Fuss gehen","allein leben","viel Geld ausgeben","sie in den Abfall werfen","Heimweh haben","jeden Franken sparen müssen","ein finanzielles Risiko eingehen","…"],"box_used":[0,16],"example":[{"label":"Beispiel","text":"Ich wäre gern beruflich selbstständig, **ohne ein finanzielles Risiko einzugehen**. Ich würde gern …"}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich würde gern mehr Geld verdienen, statt jeden Franken sparen zu müssen. Ich würde gern kaputte Sachen reparieren, statt sie in den Abfall zu werfen. Ich würde gern mit meiner Familie in der Heimat telefonieren, ohne Heimweh zu haben. Ich würde gern mit dem Velo fahren, statt immer zu Fuss zu gehen. Ich würde gern gut Deutsch sprechen, ohne viele Sprachkurse zu machen. Ich würde gern mit meiner Familie zusammenwohnen, statt allein zu leben.","en":"我想多挣点钱，而不是每一法郎都得省着花。我想修理坏掉的东西，而不是把它们扔进垃圾桶。我想和家乡的家人通电话，又不会想家。我想骑自行车，而不是总是走路。我想说一口好德语，又不用上很多语言课。我想和家人住在一起，而不是一个人生活。","why":"用 *würde gern* / *wäre gern* 表达愿望，然后用 *statt … zu*（代替）或 *ohne … zu*（没有发生）。带情态动词时：*sparen **zu müssen***。","source":"hueber"}]},{"no":"20","tag":"C3","instruction":"Unglücklich im neuen Job – Ratschläge für eine Freundin","instruction_en":"在新工作里不开心：给朋友的建议","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"用方框里的用语补全建议。每个用语只用一次；*Wie wäre es, wenn* 已用在例句中。","box":["An deiner Stelle","Du könntest zum Beispiel","Ich kann dir nur raten","Wie wäre es, wenn","Wie findest du die Idee","solltest du vielleicht"],"box_used":[3],"box_exact":true,"example":[{"label":"1","text":"**Wie wäre es, wenn** du mit deinen Kollegen zusammen Mittagspause machen würdest, statt allein zu essen?"}],"items":[{"label":"2","text":"Wenn du Kollegen besser kennenlernen möchtest, ___ öfters am Tag kurz in die Kaffeeküche gehen. Da kannst du dich entspannt mit allen unterhalten, ohne sie bei der Arbeit zu stören.","gaps":[["solltest du vielleicht"]],"solution":"Wenn du Kollegen besser kennenlernen möchtest, **solltest du vielleicht** öfters am Tag kurz in die Kaffeeküche gehen. Da kannst du dich entspannt mit allen unterhalten, ohne sie bei der Arbeit zu stören.","en":"如果你想更好地认识同事，也许你应该白天多去几趟咖啡间。在那里你可以轻松地和大家聊天，又不会打扰他们工作。","why":"在 *wenn* 从句后面，动词放在最前面：*…, solltest du vielleicht …*；*gehen* 放在句末。","source":"hueber"},{"label":"3","text":"___, an einem Tag für die Kollegen in deiner Abteilung Kuchen mitzubringen und deinen ersten Monat in der neuen Firma zu feiern? Über einen Kuchen freuen sich alle.","gaps":[["Wie findest du die Idee"]],"solution":"**Wie findest du die Idee**, an einem Tag für die Kollegen in deiner Abteilung Kuchen mitzubringen und deinen ersten Monat in der neuen Firma zu feiern? Über einen Kuchen freuen sich alle.","en":"找一天给你部门的同事们带蛋糕去，庆祝你在新公司的第一个月，你觉得这个主意怎么样？大家都会为蛋糕高兴的。","why":"*Wie findest du die Idee, … zu …?* 是一个带 *zu* + 不定式的问句。","source":"g6865"},{"label":"4","text":"___ würde ich überallhin gehen, wo man Kollegen treffen kann. ___ am Firmensportprogramm teilnehmen. Da lernst du dann auch Leute aus anderen Abteilungen kennen.","gaps":[["An deiner Stelle"],["Du könntest zum Beispiel"]],"solution":"**An deiner Stelle** würde ich überallhin gehen, wo man Kollegen treffen kann. **Du könntest zum Beispiel** am Firmensportprogramm teilnehmen. Da lernst du dann auch Leute aus anderen Abteilungen kennen.","en":"如果我是你，我会去所有能遇到同事的地方。比如说，你可以参加公司的体育活动。这样你也能认识其他部门的人。","why":"*An deiner Stelle würde ich …*（如果我是你）；*Du könntest zum Beispiel …* + 句末的不定式。","source":"hueber"},{"label":"5","text":"___, offen zu sein und positiv zu denken. Du wirst sehen, in ein paar Wochen wird es dir schon besser gehen.","gaps":[["Ich kann dir nur raten"]],"solution":"**Ich kann dir nur raten**, offen zu sein und positiv zu denken. Du wirst sehen, in ein paar Wochen wird es dir schon besser gehen.","en":"我只能劝你保持开放、积极思考。你会看到的，几个星期后你就会感觉好多了。","why":"*Ich kann dir nur raten, … zu …*：建议用 *zu* + 不定式表达。","source":"g6865"}]},{"no":"20","part":"b","part_instruction":"Schreiben Sie zwei weitere Ratschläge.","part_instruction_en":"再给这位朋友写两条建议。参考答案只是一种可能。","example":[{"label":"Beispiel","text":"Ich kann dir nur raten, …"}],"items":[{"label":"1","lead":"Ihre Ratschläge","text":"","open":true,"solution":"Ich kann dir nur raten, mit deiner Chefin zu sprechen. Wie findest du die Idee, dich nach der Arbeit mit deinen Kollegen zu verabreden?","en":"我只能劝你和你的女老板谈一谈。下班后约同事们见面，你觉得这个主意怎么样？","why":"两个用语后面都在句末接 *zu* + 不定式；反身动词的代词留在词组里面：*dich … zu verabreden*。","source":"g6865"}]}]},{"page":"AB 157","heading":"D  Verkaufsgespräche","heading_en":"购物对话","exercises":[{"no":"21","tag":"D3","instruction":"Ich hätte gern …","instruction_en":"我想要……","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ergänzen Sie: Kundin (K), Verkäuferin (V).","part_instruction_en":"谁说什么？顾客（*Kundin*）写 *K*，售货员（*Verkäuferin*）写 *V*。","example":[{"label":"4 / c","text":"Vielen Dank für Ihre Hilfe. → **K** / Vielen Dank für Ihre Beratung. → **K**"}],"items":[{"label":"1","text":"Darf ich Ihnen … empfehlen? → ___","gaps":[["V","Verkäuferin"]],"solution":"Darf ich Ihnen … empfehlen? → **V**","en":"我可以向您推荐……吗？→ 售货员","why":"推荐是售货员的事。","source":"hueber"},{"label":"2","text":"Das muss ich mir noch überlegen. → ___","gaps":[["K","Kundin"]],"solution":"Das muss ich mir noch überlegen. → **K**","en":"这个我还得考虑一下。→ 顾客","why":"顾客还没有决定。","source":"hueber"},{"label":"3","text":"Brauchen Sie Hilfe? → ___","gaps":[["V","Verkäuferin"]],"solution":"Brauchen Sie Hilfe? → **V**","en":"您需要帮助吗？→ 售货员","why":"主动提供帮助。","source":"hueber"},{"label":"5","text":"Was wünschen Sie? → ___","gaps":[["V","Verkäuferin"]],"solution":"Was wünschen Sie? → **V**","en":"您想要点什么？→ 售货员","why":"售货员问你想要什么。","source":"hueber"},{"label":"6","text":"Entschuldigung, ist es möglich, …? → ___","gaps":[["K","Kundin"]],"solution":"Entschuldigung, ist es möglich, …? → **K**","en":"对不起，可以……吗？→ 顾客","why":"顾客请求某事。","source":"hueber"},{"label":"7","text":"Haben Sie noch einen Wunsch? → ___","gaps":[["V","Verkäuferin"]],"solution":"Haben Sie noch einen Wunsch? → **V**","en":"您还需要别的什么吗？→ 售货员","why":"在买卖快结束时问的。","source":"hueber"},{"label":"8","text":"Ich bin auf der Suche nach … → ___","gaps":[["K","Kundin"]],"solution":"Ich bin auf der Suche nach … → **K**","en":"我在找……→ 顾客","why":"顾客说自己需要什么。","source":"hueber"},{"label":"a","text":"Ich hätte gern … → ___","gaps":[["K","Kundin"]],"solution":"Ich hätte gern … → **K**","en":"我想要……→ 顾客","why":"礼貌地要东西（第二虚拟式）。","source":"hueber"},{"label":"b","text":"Wie kann ich Ihnen helfen? → ___","gaps":[["V","Verkäuferin"]],"solution":"Wie kann ich Ihnen helfen? → **V**","en":"我能怎么帮您？→ 售货员","why":"主动提供帮助。","source":"hueber"},{"label":"d","text":"Haben Sie einen bestimmten Wunsch? → ___","gaps":[["V","Verkäuferin"]],"solution":"Haben Sie einen bestimmten Wunsch? → **V**","en":"您有什么特别想要的吗？→ 售货员","why":"售货员问你想要什么。","source":"hueber"},{"label":"e","text":"Darf ich Ihnen … anbieten? → ___","gaps":[["V","Verkäuferin"]],"solution":"Darf ich Ihnen … anbieten? → **V**","en":"我可以给您拿……吗？→ 售货员","why":"向顾客提供某样东西。","source":"hueber"},{"label":"f","text":"Ich kann mich noch nicht entscheiden. → ___","gaps":[["K","Kundin"]],"solution":"Ich kann mich noch nicht entscheiden. → **K**","en":"我还决定不了。→ 顾客","why":"顾客还没有决定。","source":"hueber"},{"label":"g","text":"Dürfte ich Sie etwas fragen? Kann man … → ___","gaps":[["K","Kundin"]],"solution":"Dürfte ich Sie etwas fragen? Kann man … → **K**","en":"我可以问您一件事吗？能不能……？→ 顾客","why":"礼貌的提问（第二虚拟式 *dürfte*）。","source":"hueber"},{"label":"h","text":"Möchten Sie sonst noch etwas? → ___","gaps":[["V","Verkäuferin"]],"solution":"Möchten Sie sonst noch etwas? → **V**","en":"您还想要点别的吗？→ 售货员","why":"在买卖快结束时问的。","source":"hueber"}]},{"no":"21","part":"b","part_instruction":"Wie kann man auch sagen? Verbinden Sie die Sätze in a.","part_instruction_en":"右边哪个句子（a–h）和左边每个句子的意思相同？写出字母。","phrases":["a Ich hätte gern …","b Wie kann ich Ihnen helfen?","c Vielen Dank für Ihre Beratung.","d Haben Sie einen bestimmten Wunsch?","e Darf ich Ihnen … anbieten?","f Ich kann mich noch nicht entscheiden.","g Dürfte ich Sie etwas fragen? Kann man …","h Möchten Sie sonst noch etwas?"],"example":[{"label":"4","text":"Vielen Dank für Ihre Hilfe. → **c** Vielen Dank für Ihre Beratung."}],"items":[{"label":"1","text":"Darf ich Ihnen … empfehlen? → ___","gaps":[["e"]],"solution":"Darf ich Ihnen … empfehlen? → **e**","en":"我可以向您推荐……吗？→ e 我可以给您拿……吗？","why":"两句都是向顾客推荐东西。","source":"hueber"},{"label":"2","text":"Das muss ich mir noch überlegen. → ___","gaps":[["f"]],"solution":"Das muss ich mir noch überlegen. → **f**","en":"这个我还得考虑一下。→ f 我还决定不了。","why":"两句都是说：还没决定。","source":"hueber"},{"label":"3","text":"Brauchen Sie Hilfe? → ___","gaps":[["b"]],"solution":"Brauchen Sie Hilfe? → **b**","en":"您需要帮助吗？→ b 我能怎么帮您？","why":"两句都是主动提供帮助。","source":"hueber"},{"label":"5","text":"Was wünschen Sie? → ___","gaps":[["d"]],"solution":"Was wünschen Sie? → **d**","en":"您想要点什么？→ d 您有什么特别想要的吗？","why":"两句都是问顾客想要什么。","source":"hueber"},{"label":"6","text":"Entschuldigung, ist es möglich, …? → ___","gaps":[["g"]],"solution":"Entschuldigung, ist es möglich, …? → **g**","en":"对不起，可以……吗？→ g 我可以问您一件事吗？能不能……？","why":"两句都是顾客礼貌的提问。","source":"hueber"},{"label":"7","text":"Haben Sie noch einen Wunsch? → ___","gaps":[["h"]],"solution":"Haben Sie noch einen Wunsch? → **h**","en":"您还需要别的什么吗？→ h 您还想要点别的吗？","why":"两句都是问顾客还要不要别的。","source":"hueber"},{"label":"8","text":"Ich bin auf der Suche nach … → ___","gaps":[["a"]],"solution":"Ich bin auf der Suche nach … → **a**","en":"我在找……→ a 我想要……","why":"两句都是说顾客想要什么。","source":"hueber"}]}]},{"page":"AB 158","heading":"E  Reklamation","heading_en":"投诉","exercises":[{"no":"23","tag":"E2","instruction":"Ergänzen Sie.","instruction_en":"补全投诉信中的句子。课本给出了每个词的一些字母（写在句子上方）；写出完整的词。（练习 22 是听力练习，已略去。）","items":[{"label":"a","lead":"f _ _ _ _ _ _  …  _ _ _","text":"Ich ___ Sie jetzt zum letzten Mal ___, mir bis 31.03. zu antworten.","gaps":[["fordere"],["auf"]],"solution":"Ich **fordere** Sie jetzt zum letzten Mal **auf**, mir bis 31.03. zu antworten.","en":"我最后一次要求您在 3 月 31 日之前答复我。","why":"*jemanden auffordern, … zu …* = 要求某人做……；可分动词：*ich fordere … auf*。","source":"hueber"},{"label":"b","lead":"S _ _ _ _ _ _ _  /  E _ _ _ _ _  /  A _ s p _ _ _ _","text":"Leider funktioniert die Uhr, die ich gestern gekauft habe, nicht. ___ Sie mir bitte einen ___. Ich habe ___ auf eine neue Uhr.","gaps":[["Schicken"],["Ersatz"],["Anspruch"]],"solution":"Leider funktioniert die Uhr, die ich gestern gekauft habe, nicht. **Schicken** Sie mir bitte einen **Ersatz**. Ich habe **Anspruch** auf eine neue Uhr.","en":"遗憾的是，我昨天买的手表不能用。请给我寄一个替换品。我有权得到一块新手表。","why":"*der Ersatz* = 替换品；*Anspruch haben auf* + 第四格 = 有权得到。","source":"hueber"},{"label":"c","lead":"b _ _ _ _ ä _ _ _ t","text":"Als ich das Paket geöffnet habe, habe ich leider festgestellt, dass der/die … ___ ist.","gaps":[["beschädigt"]],"solution":"Als ich das Paket geöffnet habe, habe ich leider festgestellt, dass der/die … **beschädigt** ist.","en":"我打开包裹时，遗憾地发现……坏了。","why":"*beschädigt* = 损坏的。","source":"hueber"},{"label":"d","lead":"ä _ g _ _ l _ _ _","text":"Ich habe Ihnen jetzt schon zweimal geschrieben, ohne eine Antwort zu erhalten. Das ist wirklich sehr ___.","gaps":[["ärgerlich"]],"solution":"Ich habe Ihnen jetzt schon zweimal geschrieben, ohne eine Antwort zu erhalten. Das ist wirklich sehr **ärgerlich**.","en":"我已经给您写了两次信，却没有收到任何答复。这真的非常令人恼火。","why":"*ärgerlich* = 令人恼火的。","source":"hueber"},{"label":"e","lead":"u _ _ a _ _ _ _ _ _","text":"Der Pullover ist schön, jedoch passt er meinem Mann leider nicht. Ich möchte ihn daher gern in eine Nummer grösser ___.","gaps":[["umtauschen"]],"solution":"Der Pullover ist schön, jedoch passt er meinem Mann leider nicht. Ich möchte ihn daher gern in eine Nummer grösser **umtauschen**.","en":"这件毛衣很漂亮，可惜我丈夫穿着不合身。所以我想把它换成大一号的。","why":"*umtauschen* = （在商店里）调换。","source":"hueber"},{"label":"f","lead":"A _ _ _ o _ _","text":"Leider habe ich immer noch keine ___ erhalten.","gaps":[["Antwort"]],"solution":"Leider habe ich immer noch keine **Antwort** erhalten.","en":"遗憾的是，我仍然没有收到答复。","why":"*die Antwort* = 答复。","source":"hueber"},{"label":"g","lead":"B _ _ t _ _ _ _ e _","text":"___ Sie mir bitte schriftlich, dass Sie meine Reklamation erhalten haben.","gaps":[["Bestätigen"]],"solution":"**Bestätigen** Sie mir bitte schriftlich, dass Sie meine Reklamation erhalten haben.","en":"请您书面向我确认已收到我的投诉。","why":"*bestätigen* = 确认。","source":"hueber"},{"label":"h","lead":"v _ _ ä _ _ _ r _  /  e _ _ t _ _ _ _ _ _","text":"Ich bin sehr ___ und von Ihrem Service sehr ___.","gaps":[["verärgert"],["enttäuscht"]],"solution":"Ich bin sehr **verärgert** und von Ihrem Service sehr **enttäuscht**.","en":"我非常恼火，对你们的服务非常失望。","why":"*verärgert* = 恼火的；*enttäuscht von* = 对……失望。","source":"hueber"}]},{"no":"24","tag":"E2","instruction":"Eine schriftliche Reklamation","instruction_en":"一封书面投诉","part":"a","part_instruction":"Was bedeuten die Sätze? Ordnen Sie zu.","part_instruction_en":"左边的句子是投诉信里的写法；方框里是日常口语中的说法。写出意思相同的字母（a–g）。","phrases":["a Wenn ich bis … nichts gehört habe, dann will ich den/die … nicht mehr haben.","b Ich habe Ihnen schon zweimal geschrieben und gesagt, dass ich eine(n) neue(n) … möchte.","c Schade. Der/Die … ist kaputt.","d Ich sage es Ihnen jetzt noch ein letztes Mal: Bitte schicken Sie mir spätestens am … eine(n) neue(n) …","e Ich habe wirklich gedacht, dass Ihr Service viel besser ist.","f Ich bin enttäuscht, dass ich immer noch nichts von Ihnen gehört habe.","g Ich habe am 16. Februar von Ihnen … bekommen."],"example":[{"label":"2","text":"Leider ist … defekt. → **c** Schade. Der/Die … ist kaputt."}],"items":[{"label":"1","text":"Am 16.2. haben Sie mir … geliefert. → ___","gaps":[["g"]],"solution":"Am 16.2. haben Sie mir … geliefert. → **g**","en":"您在 2 月 16 日给我送来了……→ g","why":"两句都说明你收到了什么、什么时候收到的。","source":"hueber"},{"label":"3","text":"Ich habe Ihnen bereits zweimal ein E-Mail geschrieben und Sie gebeten, mir einen Ersatz zu schicken. → ___","gaps":[["b"]],"solution":"Ich habe Ihnen bereits zweimal ein E-Mail geschrieben und Sie gebeten, mir einen Ersatz zu schicken. → **b**","en":"我已经给您写了两封电子邮件，请您给我寄一个替换品。→ b","why":"*bereits* = *schon*；*Ersatz* = 一个新的。（*das E-Mail* 是瑞士用法。）","source":"hueber"},{"label":"4","text":"Leider habe ich immer noch keine Antwort erhalten. → ___","gaps":[["f"]],"solution":"Leider habe ich immer noch keine Antwort erhalten. → **f**","en":"遗憾的是，我仍然没有收到答复。→ f","why":"还没有答复 → 失望。","source":"hueber"},{"label":"5","text":"Ich muss sagen, Ihr Service hat mich sehr enttäuscht. → ___","gaps":[["e"]],"solution":"Ich muss sagen, Ihr Service hat mich sehr enttäuscht. → **e**","en":"我不得不说，你们的服务让我很失望。→ e","why":"你原本期待更好的服务。","source":"hueber"},{"label":"6","text":"Ich fordere Sie zum letzten Mal auf, mir bis … einen Ersatz zu schicken. → ___","gaps":[["d"]],"solution":"Ich fordere Sie zum letzten Mal auf, mir bis … einen Ersatz zu schicken. → **d**","en":"我最后一次要求您在……之前给我寄一个替换品。→ d","why":"*zum letzten Mal* = *ein letztes Mal*。","source":"hueber"},{"label":"7","text":"Wenn ich bis … nichts von Ihnen höre, dann verzichte ich auf die Bestellung. → ___","gaps":[["a"]],"solution":"Wenn ich bis … nichts von Ihnen höre, dann verzichte ich auf die Bestellung. → **a**","en":"如果到……我还没有收到您的消息，我就取消这份订单。→ a","why":"*auf etwas verzichten* = 不要、放弃某样东西。","source":"hueber"}]},{"no":"24","tag":"Schreibtraining","part":"b","part_instruction":"Wählen Sie eine Situation und schreiben Sie eine Reklamation wie in a. Die Sätze 1–7 helfen Ihnen.","part_instruction_en":"选一个情景，像 a 那样写一封投诉信。句子 1–7 可以帮助你。每个参考答案都只是一种可能。","reading":[{"label":"1","text":"Kopfhörer bestellt – funktioniert nicht – schon einmal geschrieben, aber keine Antwort erhalten – bitte Ersatz bis … senden – wenn wieder keine Antwort, auf Bestellung verzichten"},{"label":"2","text":"Laptoptasche bestellt – Trageriemen nach einer Woche gerissen – zurückschicken – umtauschen oder Ersatz – bitte Reklamation bestätigen"}],"example":[{"label":"Beispiel","text":"Sehr geehrte Damen und Herren / Am 12.3. … / Freundliche Grüsse"}],"items":[{"label":"1","lead":"Situation 1: Kopfhörer","text":"","open":true,"solution":"Sehr geehrte Damen und Herren / Am 12.3. haben Sie mir Kopfhörer geliefert. Leider funktionieren sie nicht. Ich habe Ihnen schon einmal geschrieben, aber keine Antwort erhalten. Ich fordere Sie zum letzten Mal auf, mir bis 12.4. einen Ersatz zu schicken. Wenn ich wieder keine Antwort von Ihnen erhalte, dann verzichte ich auf die Bestellung. / Freundliche Grüsse / Luca Carelli","en":"尊敬的女士们、先生们 / 您在 3 月 12 日给我送来了一副耳机。遗憾的是，它不能用。我已经给您写过一次信，但没有收到答复。我最后一次要求您在 4 月 12 日之前给我寄一个替换品。如果我还是收不到您的答复，我就取消这份订单。/ 此致敬礼 / Luca Carelli","why":"要点按顺序：你收到了什么、什么时候收到的，出了什么问题，你做了什么，公司必须做什么（*auffordern, … zu …*），否则你会怎么做。","source":"hueber"},{"label":"2","lead":"Situation 2: Laptoptasche","text":"","open":true,"solution":"Sehr geehrte Damen und Herren / Am 3.5. haben Sie mir eine Laptoptasche geliefert. Leider ist der Trageriemen schon nach einer Woche gerissen. Das ist sehr ärgerlich. Ich schicke Ihnen die Tasche heute zurück und bitte Sie, sie umzutauschen oder mir einen Ersatz zu schicken. Im Anhang finden Sie eine Kopie der Rechnung. Bestätigen Sie mir bitte schriftlich, dass Sie meine Reklamation erhalten haben. / Freundliche Grüsse / Maria Keller","en":"尊敬的女士们、先生们 / 您在 5 月 3 日给我送来了一个笔记本电脑包。遗憾的是，才用了一个星期背带就断了。这非常令人恼火。我今天把包寄回给您，请您给我换一个或寄一个替换品。附件中是发票的复印件。请您书面向我确认已收到我的投诉。/ 此致敬礼 / Maria Keller","why":"这是我们自己的范例（答案里没有情景 2 的答案）。*bitten, … zu …*：*umzutauschen*（可分动词）。","source":"g6865"}]}]},{"page":"AB 159","heading":"Test Lektion 6","heading_en":"第 6 课测试","exercises":[{"no":"1","instruction":"Ergänzen Sie.","instruction_en":"补全短文。课本给出了每个词的一些字母（写在句子上方）；写出完整的词。","example":[{"label":"a","text":"Ich war **jahrelang** angestellt, …"}],"items":[{"label":"b","lead":"b: e _ t _ _ _ _ l _ s _ _ n  /  c: K _ _ _ _ a _ _","text":"… aber irgendwann war ich unzufrieden und habe mich ___: Ich mache mich als ___ selbstständig und gründe eine Firma.","gaps":[["entschlossen"],["Kaufmann","Kauffrau"]],"solution":"… aber irgendwann war ich unzufrieden und habe mich **entschlossen**: Ich mache mich als **Kaufmann** selbstständig und gründe eine Firma.","en":"……但是有一天我不满意了，于是下定决心：我要作为商人自己创业，开一家公司。","why":"*sich entschliessen*（现在完成时：*hat sich entschlossen*）= 下决心。*der Kaufmann* = 商人。","source":"g6865","check":"给出的字母指向 *Kaufmann*；女性会写 *Kauffrau*，字母组合不一样。两者都算对。练习册的答案不包括本课测试；这个答案是我们自己的，已对照 grammis 核查。"},{"label":"d","lead":"G _ _ _ _ ä _ _ _ l _ _ _ e","text":"Ein paar Freunde, die gute ___ sind, helfen mir dabei.","gaps":[["Geschäftsleute"]],"solution":"Ein paar Freunde, die gute **Geschäftsleute** sind, helfen mir dabei.","en":"几个做生意很在行的朋友在帮我。","why":"*die Geschäftsleute* = 生意人（复数）。","source":"g6865","check":"练习册的答案不包括本课测试；这个答案是我们自己的，已对照 grammis 核查。"},{"label":"e","lead":"e: f _ _ _ _ z _ _ _ _ _ s  /  f: l _ _ _ t","text":"Ich glaube nicht, dass es ein ___ Risiko ist. Im Gegenteil, ich denke es ___ sich.","gaps":[["finanzielles"],["lohnt"]],"solution":"Ich glaube nicht, dass es ein **finanzielles** Risiko ist. Im Gegenteil, ich denke es **lohnt** sich.","en":"我不认为这是一种经济风险。恰恰相反，我觉得这是值得的。","why":"*ein finanzielles Risiko*（中性）；*es lohnt sich* = 值得。","source":"platzhalter","check":"练习册的答案不包括本课测试；这个答案是我们自己的，已对照 grammis 核查。"}]},{"no":"2","instruction":"Schreiben Sie Sätze mit *damit* oder – wenn möglich – *um … zu*.","instruction_en":"把两个句子连起来。如果是同一个人，就用 *um … zu*；否则用 *damit*。","example":[{"label":"a","lead":"Erika lernt Englisch. Sie möchte ausländische Kunden besser verstehen.","text":"Erika lernt Englisch, **um ausländische Kunden besser zu verstehen**."}],"items":[{"label":"b","lead":"Tomás macht eine Weiterbildung. Er möchte seine kommunikativen Kompetenzen verbessern.","text":"","accept":["Tomás macht eine Weiterbildung, um seine kommunikativen Kompetenzen zu verbessern."],"solution":"**Tomás macht eine Weiterbildung, um seine kommunikativen Kompetenzen zu verbessern.**","en":"Tomás 在参加进修，为了提高他的沟通能力。","why":"同一个人（Tomás）→ *um … zu*；*möchte* 要去掉。","source":"g6865","check":"练习册的答案不包括本课测试；这个答案是我们自己的，已对照 grammis 核查。"},{"label":"c","lead":"Frau Seil arbeitet nur halbtags. Die Kinder sollen nicht allein sein, wenn sie aus der Schule kommen.","text":"","accept":["Frau Seil arbeitet nur halbtags, damit die Kinder nicht allein sind, wenn sie aus der Schule kommen."],"solution":"**Frau Seil arbeitet nur halbtags, damit die Kinder nicht allein sind, wenn sie aus der Schule kommen.**","en":"Seil 女士只上半天班，这样孩子们放学回家时就不会一个人在家。","why":"另一个人（孩子们）→ *damit*；*sollen* 要去掉。","source":"damit","check":"练习册的答案不包括本课测试；这个答案是我们自己的，已对照 grammis 核查。"},{"label":"d","lead":"Rodolfo kümmert sich diese Woche um die Kinder. Seine Frau kann ihre kranke Mutter besuchen.","text":"","accept":["Rodolfo kümmert sich diese Woche um die Kinder, damit seine Frau ihre kranke Mutter besuchen kann."],"solution":"**Rodolfo kümmert sich diese Woche um die Kinder, damit seine Frau ihre kranke Mutter besuchen kann.**","en":"Rodolfo 这个星期照顾孩子们，好让他的妻子能去看望她生病的母亲。","why":"另一个人（他的妻子）→ *damit*；*kann* 放在最后。","source":"damit","check":"练习册的答案不包括本课测试；这个答案是我们自己的，已对照 grammis 核查。"}]},{"no":"3","instruction":"Ergänzen Sie: *ohne … zu* oder *statt … zu*.","instruction_en":"在第一个空里填 *ohne* 或 *statt*，在第二个空里填 *zu*。","example":[{"label":"a","text":"Wenn man streiten kann, **ohne** alles persönlich **zu** nehmen, dann ist man konfliktfähig."}],"items":[{"label":"b","text":"Man ist kompromissfähig, wenn man sich in Streitfragen mit jemandem einigt, ___ ergebnislos ___ streiten.","gaps":[["statt"],["zu"]],"solution":"Man ist kompromissfähig, wenn man sich in Streitfragen mit jemandem einigt, **statt** ergebnislos **zu** streiten.","en":"如果一个人在有争议的问题上和别人达成一致，而不是毫无结果地争吵，他就善于妥协。","why":"达成一致代替了争吵 → *statt*。","source":"komma","check":"练习册的答案不包括本课测试；这个答案是我们自己的，已对照 grammis 核查。"},{"label":"c","text":"Ein guter Chef ist jemand, der seine Mitarbeiter führt, ___ sich selbst zu wichtig ___ nehmen.","gaps":[["ohne"],["zu"]],"solution":"Ein guter Chef ist jemand, der seine Mitarbeiter führt, **ohne** sich selbst zu wichtig **zu** nehmen.","en":"好老板是这样的人：他领导员工，却不把自己看得太重要。","why":"他领导员工，同时不把自己看得太重要 → *ohne*。第一个 *zu* 的意思是“太”。","source":"komma","check":"练习册的答案不包括本课测试；这个答案是我们自己的，已对照 grammis 核查。"},{"label":"d","text":"Wer teamfähig ist, arbeitet gern mit Kollegen zusammen, ___ immer nur alles allein ___ machen.","gaps":[["statt"],["zu"]],"solution":"Wer teamfähig ist, arbeitet gern mit Kollegen zusammen, **statt** immer nur alles allein **zu** machen.","en":"有团队精神的人喜欢和同事们一起工作，而不是总是什么都自己一个人做。","why":"团队合作代替了单独工作 → *statt*。","source":"komma","check":"练习册的答案不包括本课测试；这个答案是我们自己的，已对照 grammis 核查。"},{"label":"e","text":"Flexibel ist jemand, der sich schnell und ohne Probleme an neue Situationen gewöhnen kann, ___ gestresst ___ sein.","gaps":[["ohne"],["zu"]],"solution":"Flexibel ist jemand, der sich schnell und ohne Probleme an neue Situationen gewöhnen kann, **ohne** gestresst **zu** sein.","en":"灵活的意思是：一个人能迅速而顺利地适应新情况，而不会感到有压力。","why":"没有出现压力 → *ohne*。","source":"komma","check":"练习册的答案不包括本课测试；这个答案是我们自己的，已对照 grammis 核查。"}]},{"no":"4","instruction":"Vor dem Bewerbungsgespräch. Was ist richtig? Kreuzen Sie an.","instruction_en":"面试之前：给朋友的建议。填上和句子其余部分相配的用语。两个选项写在每个句子的上方。","example":[{"label":"a","text":"**An deiner Stelle würde** ich heute noch ein bisschen über die Firma im Internet recherchieren."}],"items":[{"label":"b","lead":"Wie wäre es, wenn / Ich kann dir nur raten,","text":"___ du dir ein paar Fragen überlegst, die du morgen stellen kannst?","gaps":[["Wie wäre es, wenn","Wie wäre es wenn"]],"solution":"**Wie wäre es, wenn** du dir ein paar Fragen überlegst, die du morgen stellen kannst?","en":"你先想好几个明天可以提的问题，怎么样？","why":"*du … überlegst* 动词在句末，需要用 *wenn*：*Wie wäre es, wenn …?*","source":"g6865","check":"练习册的答案不包括本课测试；这个答案是我们自己的，已对照 grammis 核查。"},{"label":"c","lead":"Was hältst du davon, / Du könntest zum Beispiel","text":"___ fragen, wie gross das Team ist oder was deine Aufgaben sein werden.","gaps":[["Du könntest zum Beispiel"]],"solution":"**Du könntest zum Beispiel** fragen, wie gross das Team ist oder was deine Aufgaben sein werden.","en":"比如说，你可以问团队有多大，或者你的工作任务会是什么。","why":"情态动词后面接不带 zu 的不定式（*fragen*）：*Du könntest … fragen*。","source":"g6865","check":"练习册的答案不包括本课测试；这个答案是我们自己的，已对照 grammis 核查。"},{"label":"d","lead":"An deiner Stelle würde ich / Ich kann dir nur raten,","text":"___ du selbst zu sein. Das ist das Allerwichtigste.","gaps":[["Ich kann dir nur raten,","Ich kann dir nur raten"]],"solution":"**Ich kann dir nur raten,** du selbst zu sein. Das ist das Allerwichtigste.","en":"我只能劝你做你自己。这是最最重要的。","why":"*zu sein* 需要一个接 *zu* + 不定式的用语：*Ich kann dir nur raten, …*","source":"g6865","check":"练习册的答案不包括本课测试；这个答案是我们自己的，已对照 grammis 核查。"},{"label":"e","lead":"Wie wäre es, wenn / Was hältst du davon,","text":"___ heute Abend essen zu gehen? Das bringt dich auf andere Gedanken.","gaps":[["Was hältst du davon,","Was hältst du davon"]],"solution":"**Was hältst du davon,** heute Abend essen zu gehen? Das bringt dich auf andere Gedanken.","en":"今天晚上出去吃饭，你觉得怎么样？这会让你换换心情。","why":"*essen zu gehen*（zu + 不定式）适合 *Was hältst du davon, … zu …?*","source":"g6865","check":"练习册的答案不包括本课测试；这个答案是我们自己的，已对照 grammis 核查。"}]}]},{"page":"AB 160","heading":"Fokus Beruf: Kundenwünsche","heading_en":"职场聚焦：客户的要求","exercises":[{"no":"3","instruction":"Arbeiten Sie zu dritt. Wählen Sie je eine Rolle und spielen Sie drei Telefongespräche.","instruction_en":"三人一组：每人担任一个角色，表演三个电话。用写或说的方式练习；范例对话只是一种可能。（练习 1 和 2 是听力练习，已略去。）","reading":[{"label":"A  Kundin/Kunde","text":"Sie machen heute eine Grillparty. Sie haben beim Getränkeservice *Getränkeblitz* drei Harasse Mineralwasser und vier Harasse Süssmost bestellt."},{"label":"B  Angestellte/Angestellter","text":"Sie arbeiten bei der Firma *Getränkeblitz* und bekommen einen Beschwerdeanruf von einer Kundin. Sie können nicht direkt helfen. Sie müssen zuerst mit dem Fahrer sprechen und rufen die Kundin dann zurück."},{"label":"C  Fahrerin/Fahrer","text":"Sie arbeiten als Fahrer/in für die Firma *Getränkeblitz*. Sie haben für die Grillparty sieben Harasse Mineralwasser geliefert."}],"phrases":["Gespräch 1 – Kunde: Ich habe bei Ihnen … bestellt. | Jetzt ist die Lieferung gekommen, aber … | Sie haben wohl einen Fehler gemacht. | Ich habe … bestellt und nicht …","Gespräch 1 – Angestellte: Oh, das tut mir leid. | Da ist wohl ein Fehler/ein Irrtum passiert. | Ich rufe sofort meine Kollegin/meinen Kollegen an. | Bitte geben Sie mir Ihre Handynummer, ich rufe Sie sofort zurück.","Gespräch 2 – Angestellte: Frau/Herr … hat angerufen. | Du hast ihm/ihr … statt … geliefert. | Wir machen Folgendes: … | Ich rufe an und frage nach, ob das okay ist.","Gespräch 2 – Fahrer: Oh je, da habe ich wohl einen Fehler gemacht. | Da habe ich wohl etwas verwechselt. | Was machen wir denn jetzt? | Ich könnte …","Gespräch 3 – Angestellte: Es tut mir wahnsinnig leid. | Meine Kollegin/Mein Kollege hat einen Fehler gemacht. | Wir könnten Ihnen … | Selbstverständlich geben wir Ihnen einen Rabatt.","Gespräch 3 – Kunde: Ja, damit bin ich einverstanden. | Nein, tut mir leid. Das war doch Ihr Fehler, nicht meiner. | Ich mache Ihnen einen anderen Vorschlag: …"],"items":[{"label":"1","lead":"Gespräch 1: Kundin und Angestellter","text":"","open":true,"solution":"Kundin: Grüezi, hier ist Meier. Ich habe bei Ihnen drei Harasse Mineralwasser und vier Harasse Süssmost bestellt. Jetzt ist die Lieferung gekommen, aber es sind sieben Harasse Mineralwasser. Ich habe Süssmost bestellt und nicht nur Wasser! / Angestellter: Oh, das tut mir leid. Da ist wohl ein Fehler passiert. Ich rufe sofort meinen Kollegen an. Bitte geben Sie mir Ihre Handynummer, ich rufe Sie sofort zurück.","en":"女顾客：您好，我是 Meier。我在你们那里订了三箱矿泉水和四箱苹果汁。现在货送到了，但是来的是七箱矿泉水。我订的是苹果汁，不只是水！/ 员工：哦，真抱歉。大概是出了差错。我马上给我的同事打电话。请把您的手机号码给我，我马上给您回电话。","why":"投诉：说明你订了什么、送来的是什么（*bestellt … und nicht …*）。员工道歉并答应回电话。（*der Harass* 是瑞士用语，即饮料箱；*der Süssmost* 是瑞士的苹果汁。）","source":"hueber"},{"label":"2","lead":"Gespräch 2: Angestellter und Fahrer","text":"","open":true,"solution":"Angestellter: Hallo Marco, Frau Meier hat angerufen. Du hast ihr sieben Harasse Mineralwasser statt drei Harasse Wasser und vier Harasse Süssmost geliefert. / Fahrer: Oh je, da habe ich wohl etwas verwechselt. Was machen wir denn jetzt? Ich könnte heute Nachmittag noch einmal hinfahren. / Angestellter: Gut, wir machen Folgendes: Du bringst ihr vier Harasse Süssmost und holst vier Harasse Wasser wieder ab. Ich rufe an und frage nach, ob das okay ist.","en":"员工：你好，Marco，Meier 女士打电话来了。你给她送了七箱矿泉水，而不是三箱水和四箱苹果汁。/ 司机：哎呀，我大概是弄混了。那我们现在怎么办？我今天下午可以再送一趟。/ 员工：好，我们这样办：你给她送去四箱苹果汁，再把四箱水拿回来。我打电话问问她这样行不行。","why":"同事之间用 *du*。这里是 *statt* + 名词（*statt drei Harasse Wasser*）：和 *statt … zu* 意思相同，只是接的是东西。","source":"hueber"},{"label":"3","lead":"Gespräch 3: Angestellter und Kundin","text":"","open":true,"solution":"Angestellter: Frau Meier, es tut mir wahnsinnig leid. Mein Kollege hat einen Fehler gemacht. Wir könnten Ihnen den Süssmost noch heute bis 17 Uhr bringen. Selbstverständlich geben wir Ihnen einen Rabatt von 20 Prozent. / Kundin: Ja, damit bin ich einverstanden. Die Party fängt erst um 18 Uhr an. Vielen Dank!","en":"员工：Meier 女士，我真是非常抱歉。我的同事弄错了。我们今天 17 点之前就可以把苹果汁给您送去。当然，我们会给您 20% 的折扣。/ 女顾客：好，我同意。聚会 18 点才开始。非常感谢！","why":"用 *Wir könnten Ihnen …*（第二虚拟式 = 礼貌）提出解决办法。顾客接受：*damit bin ich einverstanden*（这里 *damit* = 对此，而不是 *以便*）。","source":"hueber"}]}]}],"sources":[{"id":"hueber","title":"Hueber：Schritte plus Neu 5 Schweiz, Lösungen Arbeitsbuch（官方练习册答案，Lektion 6）","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Loesungen_AB.pdf"},{"id":"g6865","title":"grammis：Vertiefung: Infinitivsätze（um … zu 没有自己的主语；主语来自主句）","url":"https://grammis.ids-mannheim.de/progr@mm/6865"},{"id":"damit","title":"grammis 连词词典：damit（从属连词，动词在句末；也可以作副词，表示“以此、对此”）","url":"https://grammis.ids-mannheim.de/konnektoren/407001"},{"id":"komma","title":"grammis：Komma bei Nebensätzen（带 um, ohne, (an)statt 的不定式句要用逗号隔开）","url":"https://grammis.ids-mannheim.de/rechtschreibung/6203"},{"id":"platzhalter","title":"grammis：Platzhalter（第 1 位上的 es；天气动词的形式主语 es 保留：Heute schneit es）","url":"https://grammis.ids-mannheim.de/vggf/2284"},{"id":"korrelat","title":"grammis：Korrelat（指向后面从句的 es：Ich kann es nicht erwarten, euch zu sehen）","url":"https://grammis.ids-mannheim.de/vggf/2283"}]},{"id":"06-lektion-6-zusatzblaetter","no":6,"title":"Lektion 6 Homework – extra exercises from printed sheets","title_en":"而不是（*anstatt … zu / anstatt dass*）、没有（*ohne … zu / ohne dass*）、目的（*um … zu / damit*）","added":"2026-11-20","book":"Printed grammar sheets 48, 49 and 52 (extra homework for Schritte plus Neu 5, Lektion 6)","pages":[{"page":"Blatt 48 · S. 100","heading":"48  Ich lade gerne Freunde ein, anstatt allein zu essen.","heading_en":"我喜欢请朋友来家里，而不是一个人吃饭。（主句 + 不定式句 / 方式从句：*anstatt … zu, anstatt dass*）","exercises":[{"no":"A","instruction":"Welches Foto passt? Kreuzen Sie an.","instruction_en":"哪张照片和句子相符？照片 A：朋友们围坐在一张大桌子旁一起吃饭。照片 B：一个男人独自吃饭。填 A 或 B。练习纸上的规则框 B 和 C 显示在下面。","reading":[{"label":"B  Lesen Sie.","text":"Infinitiv mit anstatt … zu: Ich lade gerne Freunde ein, | anstatt immer allein zu essen.\nNebensatz mit anstatt dass: Ich lade gerne Freunde ein, | anstatt dass ich immer allein esse.\nDie Subjekte in Haupt- und Nebensatz sind gleich: anstatt … zu oder anstatt dass\nIch lade gerne Freunde ein, | anstatt immer allein zu essen. / anstatt dass ich immer allein esse.\nDie Subjekte in Hauptsatz und Nebensatz sind nicht gleich: immer anstatt dass\nEr lädt gerne Freunde ein, | anstatt dass wir immer allein essen."},{"label":"C  Lesen Sie.","text":"• *anstatt … zu* und *anstatt dass* signalisieren, dass eine Alternative möglich ist.\n• Im Infinitivsatz mit *anstatt … zu* steht kein Subjekt. Das Subjekt aus dem Hauptsatz ist auch Subjekt im Infinitivsatz.\n• Man kann *anstatt* oder *statt* benutzen, es gibt keinen Unterschied: Wir lachen anstatt zu weinen. = Wir lachen statt zu weinen."}],"items":[{"label":"1","text":"Ich lade gerne Freunde ein, anstatt immer allein zu essen. → Foto ___","gaps":[["A"]],"solution":"Ich lade gerne Freunde ein, anstatt immer allein zu essen. → Foto **A**","en":"我喜欢请朋友来家里，而不是总是一个人吃饭。→ 照片 A","why":"照片 A 显示朋友们坐在桌旁，这是他选择的做法；照片 B 显示他*不*做的事。","source":"anstattdass"}]},{"no":"1","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"哪些句子是对的？填 *richtig* 或 *falsch*。提示：*anstatt* 本身已经表示“不是这个”，所以后面不再接 *nicht* 或 *kein*。","example":[{"label":"1","text":"Ich verabrede mich mit Freunden, anstatt allein fernzusehen. → **richtig**"}],"items":[{"label":"2","text":"Ich verabrede mich mit Freunden, anstatt nicht allein fernzusehen. → ___","gaps":[["falsch"]],"solution":"Ich verabrede mich mit Freunden, anstatt nicht allein fernzusehen. → **falsch**","en":"我和朋友约好见面，而不是不一个人看电视。→ 错误","why":"*anstatt* 本身已经表示否定：*anstatt nicht …* 说的正好和想表达的意思相反。","source":"anstattdass"},{"label":"3","text":"Ich veröffentliche mein Buch bei Amazon, anstatt keinen Verlag zu suchen. → ___","gaps":[["falsch"]],"solution":"Ich veröffentliche mein Buch bei Amazon, anstatt keinen Verlag zu suchen. → **falsch**","en":"我在 Amazon 上出版我的书，而不是不找出版社。→ 错误","why":"*anstatt* 后面不用 *kein*：被代替的动作是 *einen Verlag suchen*。","source":"anstattdass"},{"label":"4","text":"Ich veröffentliche mein Buch bei Amazon, anstatt einen Verlag zu suchen. → ___","gaps":[["richtig"]],"solution":"Ich veröffentliche mein Buch bei Amazon, anstatt einen Verlag zu suchen. → **richtig**","en":"我在 Amazon 上出版我的书，而不是找出版社。→ 正确","why":"*anstatt* 后面接肯定的动作，*zu* + 不定式放在句末。","source":"g6865"}]}]},{"page":"Blatt 48 · S. 101","heading":"48  Ich lade gerne Freunde ein, anstatt allein zu essen.","heading_en":"我喜欢请朋友来家里，而不是一个人吃饭。","exercises":[{"no":"2","instruction":"Vereine. Verbinden Sie die Sätze mit *anstatt … zu*. Schreiben Sie in Ihr Heft.","instruction_en":"协会。用 *anstatt … zu* 把两个句子连起来。第二个句子说的是*没有*发生的事：去掉它的 *nicht* 和主语，把 *zu* + 不定式放在句末。","example":[{"label":"1","lead":"Ich werde Mitglied in einem Fussballverein. Ich mache nicht allein Sport.","text":"Ich werde Mitglied in einem Fussballverein, **anstatt allein Sport zu machen**."}],"items":[{"label":"2","lead":"Sie können den Mitgliedsbeitrag auch monatlich überweisen. Sie zahlen nicht sofort fürs ganze Jahr.","text":"","accept":["Sie können den Mitgliedsbeitrag auch monatlich überweisen, anstatt sofort fürs ganze Jahr zu zahlen.","Sie können den Mitgliedsbeitrag auch monatlich überweisen, statt sofort fürs ganze Jahr zu zahlen."],"solution":"**Sie können den Mitgliedsbeitrag auch monatlich überweisen, anstatt sofort fürs ganze Jahr zu zahlen.**","en":"您也可以按月转账缴纳会费，而不是马上付清全年的费用。","why":"去掉 *nicht*；*zu zahlen* 放在句末。","source":"g6865"},{"label":"3","lead":"Wir nehmen Tom in unseren Verein auf. Wir sagen ihm nicht wieder ab.","text":"","accept":["Wir nehmen Tom in unseren Verein auf, anstatt ihm wieder abzusagen.","Wir nehmen Tom in unseren Verein auf, statt ihm wieder abzusagen."],"solution":"**Wir nehmen Tom in unseren Verein auf, anstatt ihm wieder abzusagen.**","en":"我们接纳 Tom 加入我们的协会，而不是再次拒绝他。","why":"可分动词：*zu* 放在前缀和动词之间：*abzusagen*（ab + zu + sagen）。","source":"g6865"},{"label":"4","lead":"Sie können auch erst einmal einfach so zu unseren Veranstaltungen kommen. Sie werden nicht sofort Mitglied.","text":"","accept":["Sie können auch erst einmal einfach so zu unseren Veranstaltungen kommen, anstatt sofort Mitglied zu werden.","Sie können auch erst einmal einfach so zu unseren Veranstaltungen kommen, statt sofort Mitglied zu werden."],"solution":"**Sie können auch erst einmal einfach so zu unseren Veranstaltungen kommen, anstatt sofort Mitglied zu werden.**","en":"您也可以先随便来参加我们的活动，而不是马上成为会员。","why":"主语相同，都是 *Sie*：*anstatt … Mitglied zu werden*。","source":"g6865"}]},{"no":"3","instruction":"Unterstreichen Sie die Subjekte. Welche sind gleich? Kreuzen Sie an.","instruction_en":"找出每个句子的主语（做这个动作的人或事物），然后说出它们是不是同一个人或事物。写出两个主语，再写 *gleich*（相同）或 *nicht gleich*（不相同）。注意：主语不一定在第 1 位。","example":[{"label":"1","text":"Sie möchte Bücher schreiben. Sie arbeitet nicht weiter im Büro. → **Sie** / **Sie** → **gleich**"}],"items":[{"label":"2","text":"Der Verlag möchte nur noch Apps entwickeln. Die Autoren schreiben keine Bücher. → ___ / ___ → ___","gaps":[["Der Verlag"],["Die Autoren"],["nicht gleich"]],"solution":"Der Verlag möchte nur noch Apps entwickeln. Die Autoren schreiben keine Bücher. → **Der Verlag** / **Die Autoren** → **nicht gleich**","en":"出版社现在只想开发应用程序。作者们不写书。→ 不相同","why":"两个不同的主语：*der Verlag* 和 *die Autoren*。","source":"anstattdass"},{"label":"3","text":"Sie veröffentlicht den Roman im Selbstverlag. Das Manuskript schickt sie nicht an einen Verlag. → ___ / ___ → ___","gaps":[["Sie"],["sie"],["gleich"]],"solution":"Sie veröffentlicht den Roman im Selbstverlag. Das Manuskript schickt sie nicht an einen Verlag. → **Sie** / **sie** → **gleich**","en":"她自费出版这部小说。她不把手稿寄给出版社。→ 相同","why":"*Das Manuskript* 是宾语（它被寄出）；主语 *sie* 在动词后面。","source":"g6865"},{"label":"4","text":"Der Verlag veröffentlicht nur noch online. Er druckt keine Bücher. → ___ / ___ → ___","gaps":[["Der Verlag"],["Er"],["gleich"]],"solution":"Der Verlag veröffentlicht nur noch online. Er druckt keine Bücher. → **Der Verlag** / **Er** → **gleich**","en":"出版社现在只在网上出版。它不印书。→ 相同","why":"*Er* 指的是前面的 *der Verlag*。","source":"g6865"}]},{"no":"4","instruction":"Verbinden Sie die Sätze aus 4 mit *anstatt … zu* und / oder *anstatt dass*.","instruction_en":"把练习 3 中的句子连起来（练习纸上误写成了“aus 4”）。主语相同：两种形式都可以。主语不同：只能用 *anstatt dass*。去掉 *nicht* / 把 *kein* 变成 *ein* 或者直接去掉。","example":[{"label":"1","text":"anstatt … zu: Sie möchte Bücher schreiben, **anstatt weiter im Büro zu arbeiten**.\nanstatt dass: Sie möchte Bücher schreiben, **anstatt dass sie weiter im Büro arbeitet**."}],"items":[{"label":"2 · anstatt dass","lead":"Der Verlag möchte nur noch Apps entwickeln. Die Autoren schreiben keine Bücher.","text":"","accept":["Der Verlag möchte nur noch Apps entwickeln, anstatt dass die Autoren Bücher schreiben.","Der Verlag möchte nur noch Apps entwickeln, statt dass die Autoren Bücher schreiben."],"solution":"**Der Verlag möchte nur noch Apps entwickeln, anstatt dass die Autoren Bücher schreiben.**","en":"出版社现在只想开发应用程序，而不是让作者们写书。","why":"主语不同 → 只能用 *anstatt dass*；*keine Bücher* → *Bücher*；动词放在句末。","source":"anstattdass"},{"label":"3 · anstatt … zu","lead":"Sie veröffentlicht den Roman im Selbstverlag. Das Manuskript schickt sie nicht an einen Verlag.","text":"","accept":["Sie veröffentlicht den Roman im Selbstverlag, anstatt das Manuskript an einen Verlag zu schicken.","Sie veröffentlicht den Roman im Selbstverlag, statt das Manuskript an einen Verlag zu schicken."],"solution":"**Sie veröffentlicht den Roman im Selbstverlag, anstatt das Manuskript an einen Verlag zu schicken.**","en":"她自费出版这部小说，而不是把手稿寄给出版社。","why":"主语相同：不定式句里没有 *sie*，*zu* 前面不加逗号。","source":"g6865"},{"label":"3 · anstatt dass","lead":"Sie veröffentlicht den Roman im Selbstverlag. Das Manuskript schickt sie nicht an einen Verlag.","text":"","accept":["Sie veröffentlicht den Roman im Selbstverlag, anstatt dass sie das Manuskript an einen Verlag schickt.","Sie veröffentlicht den Roman im Selbstverlag, statt dass sie das Manuskript an einen Verlag schickt."],"solution":"**Sie veröffentlicht den Roman im Selbstverlag, anstatt dass sie das Manuskript an einen Verlag schickt.**","en":"她自费出版这部小说，而不是把手稿寄给出版社。","why":"*anstatt dass* 需要自己的主语 *sie*；动词 *schickt* 放在句末。","source":"anstattdass"},{"label":"4 · anstatt … zu","lead":"Der Verlag veröffentlicht nur noch online. Er druckt keine Bücher.","text":"","accept":["Der Verlag veröffentlicht nur noch online, anstatt Bücher zu drucken.","Der Verlag veröffentlicht nur noch online, statt Bücher zu drucken."],"solution":"**Der Verlag veröffentlicht nur noch online, anstatt Bücher zu drucken.**","en":"出版社现在只在网上出版，而不是印书。","why":"*keine Bücher* → *Bücher*；*zu drucken* 放在句末。","source":"g6865"},{"label":"4 · anstatt dass","lead":"Der Verlag veröffentlicht nur noch online. Er druckt keine Bücher.","text":"","accept":["Der Verlag veröffentlicht nur noch online, anstatt dass er Bücher druckt.","Der Verlag veröffentlicht nur noch online, statt dass er Bücher druckt."],"solution":"**Der Verlag veröffentlicht nur noch online, anstatt dass er Bücher druckt.**","en":"出版社现在只在网上出版，而不是印书。","why":"主语 *er* + 动词 *druckt* 放在句末。","source":"anstattdass"}]},{"no":"5","instruction":"Was würden Sie gerne machen? Schreiben Sie Sätze mit *anstatt … zu*.","instruction_en":"你想做什么？把方框第一部分里的一个愿望（*Ich würde gerne …*）和第二部分里的一项内容（*anstatt … zu*）组合起来。划掉的短语已用在例句中。参考答案只是一种可能。","box":["Sport in einem Verein machen","an einem Tag Homeoffice machen","öfter an die frische Luft gehen","schöne Dinge kaufen","etwas mit meiner Familie unternehmen","immer nur sparen","jeden Tag ins Büro fahren","immer allein joggen","am Wochenende arbeiten","immer im klimatisierten Büro sitzen"],"box_used":[0,7],"example":[{"label":"Beispiel","text":"Ich würde gerne Sport in einem Verein machen, **anstatt immer allein zu joggen**."}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich würde gerne an einem Tag Homeoffice machen, anstatt jeden Tag ins Büro zu fahren. Ich würde gerne öfter an die frische Luft gehen, anstatt immer im klimatisierten Büro zu sitzen. Ich würde gerne schöne Dinge kaufen, anstatt immer nur zu sparen. Ich würde gerne etwas mit meiner Familie unternehmen, anstatt am Wochenende zu arbeiten.","en":"我想每周有一天在家办公，而不是每天去办公室。我想更常到户外呼吸新鲜空气，而不是总坐在开着空调的办公室里。我想买些好东西，而不是总是只存钱。我想和家人一起做点什么，而不是周末还工作。","why":"用 *würde gerne* + 不定式表达愿望，然后用 *anstatt … zu*，不定式放在句末；*nur* 留在 *zu sparen* 前面。","source":"g6865"}]}]},{"page":"Blatt 49 · Seite 1","heading":"49  Ich arbeite hier, ohne Stress zu haben.","heading_en":"我在这里工作，没有压力。（主句 + 不定式句 / 方式从句：*ohne … zu, ohne dass*）","exercises":[{"no":"A","instruction":"Lesen Sie und unterstreichen Sie *ohne … zu*.","instruction_en":"阅读对话气泡，写出带 *ohne … zu* 的部分。练习纸上的规则框 B 和 C 显示在下面。","reading":[{"label":"Sprechblase","text":"Homeoffice! Ja, cool! Ich arbeite hier, ohne Stress zu haben."},{"label":"B  Lesen Sie.","text":"Infinitiv mit ohne zu: Ich arbeite hier, | ohne Stress zu haben.\nNebensatz mit ohne dass: Ich arbeite hier, | ohne dass ich Stress habe.\nDie Subjekte in Haupt- und Nebensatz sind gleich: ohne zu oder ohne dass\nIch arbeite hier, | ohne Stress zu haben. / ohne dass ich Stress habe.\nDie Subjekte in Haupt- und Nebensatz sind verschieden: immer ohne dass\nIch arbeite hier, | ohne dass mein Chef Stress macht."},{"label":"C  Lesen Sie.","text":"• *ohne … zu* und *ohne dass* drücken aus, dass etwas nicht ist oder nicht passiert.\n• Im Infinitivsatz mit *ohne … zu* steht kein Subjekt. Das Subjekt aus dem Hauptsatz ist auch Subjekt im Infinitivsatz."}],"items":[{"label":"1","text":"Homeoffice! Ja, cool! Ich arbeite hier, ___.","gaps":[["ohne Stress zu haben"]],"solution":"Homeoffice! Ja, cool! Ich arbeite hier, **ohne Stress zu haben**.","en":"在家办公！对，太棒了！我在这里工作，没有压力。","why":"*ohne* 开启从句，*zu* + 不定式结束从句。","source":"g6865"}]},{"no":"1","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"哪些句子是对的？填 *richtig* 或 *falsch*。提示：*ohne* 本身已经表示“不”，所以后面不再接 *nicht* 或 *kein*。","example":[{"label":"1","text":"Ich kann hier gut Klavier spielen, ohne die Nachbarn zu stören. → **richtig**"}],"items":[{"label":"2","text":"Ich kann hier gut Klavier spielen, ohne die Nachbarn nicht zu stören. → ___","gaps":[["falsch"]],"solution":"Ich kann hier gut Klavier spielen, ohne die Nachbarn nicht zu stören. → **falsch**","en":"我在这里可以好好弹钢琴，而不会不打扰邻居。→ 错误","why":"*ohne … nicht* 是双重否定：意思会变成你*确实*打扰了他们。","source":"ohnedass"},{"label":"3","text":"Er bekommt mehr Lohn, ohne eine Stunde mehr dafür zu arbeiten. → ___","gaps":[["richtig"]],"solution":"Er bekommt mehr Lohn, ohne eine Stunde mehr dafür zu arbeiten. → **richtig**","en":"他拿到更多工资，而不用为此多工作一个小时。→ 正确","why":"*ohne* + 肯定的词组（*eine Stunde*）+ *zu arbeiten*。","source":"g6865"},{"label":"4","text":"Er bekommt mehr Lohn, ohne keine Stunde mehr dafür zu arbeiten. → ___","gaps":[["falsch"]],"solution":"Er bekommt mehr Lohn, ohne keine Stunde mehr dafür zu arbeiten. → **falsch**","en":"他拿到更多工资，而不用为此不多工作一个小时。→ 错误","why":"*ohne* 后面不用 *kein*：*keine Stunde* 变成 *eine Stunde*。","source":"ohnedass"}]}]},{"page":"Blatt 49 · Seite 2","heading":"49  Ich arbeite hier, ohne Stress zu haben.","heading_en":"我在这里工作，没有压力。","exercises":[{"no":"2","instruction":"Der Alltag eines Bloggers. Schreiben Sie Sätze mit *ohne … zu* in Ihr Heft.","instruction_en":"一位博主的日常生活。用 *ohne … zu* 把两个句子连起来。去掉 *nicht*；把 *kein* 变成 *ein*（在复数前面就直接去掉）。","example":[{"label":"1","lead":"Ich arbeite bequem von zu Hause. Ich fahre nicht ins Büro.","text":"Ich arbeite bequem von zu Hause, **ohne ins Büro zu fahren**."}],"items":[{"label":"2","lead":"Ich arbeite selbstständig. Ich habe keinen Vertrag.","text":"","accept":["Ich arbeite selbstständig, ohne einen Vertrag zu haben."],"solution":"**Ich arbeite selbstständig, ohne einen Vertrag zu haben.**","en":"我做自由职业，没有合同。","why":"*keinen Vertrag* → *einen Vertrag*：*ohne* 本身已经表示“没有”。","source":"ohnedass"},{"label":"3","lead":"Ich mache Pausen und gehe auch mal zum Sport. Ich informiere meine Kollegen nicht.","text":"","accept":["Ich mache Pausen und gehe auch mal zum Sport, ohne meine Kollegen zu informieren."],"solution":"**Ich mache Pausen und gehe auch mal zum Sport, ohne meine Kollegen zu informieren.**","en":"我会休息，有时也去运动，而不通知我的同事。","why":"去掉 *nicht*；*zu informieren* 放在句末。","source":"g6865"},{"label":"4","lead":"Ich wähle die Themen für meinen Blog. Ich frage den Chef nicht.","text":"","accept":["Ich wähle die Themen für meinen Blog, ohne den Chef zu fragen."],"solution":"**Ich wähle die Themen für meinen Blog, ohne den Chef zu fragen.**","en":"我自己选择博客的主题，而不问老板。","why":"去掉 *nicht*；宾语 *den Chef* 放在 *zu fragen* 前面。","source":"g6865"},{"label":"5","lead":"Ich habe viel Zeit für mein Kind. Ich mache mir keine Sorgen um meine Karriere.","text":"","accept":["Ich habe viel Zeit für mein Kind, ohne mir Sorgen um meine Karriere zu machen."],"solution":"**Ich habe viel Zeit für mein Kind, ohne mir Sorgen um meine Karriere zu machen.**","en":"我有很多时间陪孩子，而不用为我的事业担心。","why":"*keine Sorgen* → *Sorgen*（复数：不加冠词）；反身代词 *mir* 保留。","source":"ohnedass"}]},{"no":"3","instruction":"Mein Leben. *ohne dass* oder *ohne*? Unterstreichen Sie.","instruction_en":"我的生活。填 *ohne dass* 或 *ohne*。看句末：*zu* + 不定式 → *ohne*；有新的主语，变位动词在句末 → *ohne dass*。","example":[{"label":"1","text":"Ich möchte abends Musik hören, **ohne dass** sich meine Nachbarn beschweren."}],"items":[{"label":"2","text":"Ich trinke nie Kaffee, ___ dabei Zeitung zu lesen.","gaps":[["ohne"]],"solution":"Ich trinke nie Kaffee, **ohne** dabei Zeitung zu lesen.","en":"我从来不会不看报纸就喝咖啡。","why":"*zu lesen* 在句末，没有新的主语 → *ohne*。","source":"g6865"},{"label":"3","text":"Ich gehe nie ins Theater, ___ mich vorher über das Stück zu informieren.","gaps":[["ohne"]],"solution":"Ich gehe nie ins Theater, **ohne** mich vorher über das Stück zu informieren.","en":"我从不去剧院而不事先了解那出戏。","why":"*zu informieren* 在句末 → *ohne*；*mich* 是反身代词，不是主语。","source":"g6865"},{"label":"4","text":"Meine Kinder gehen nie aus, ___ ich etwas davon weiss.","gaps":[["ohne dass"]],"solution":"Meine Kinder gehen nie aus, **ohne dass** ich etwas davon weiss.","en":"我的孩子们从不在我不知道的情况下出去。","why":"新的主语 *ich*，*weiss* 在句末 → *ohne dass*。","source":"ohnedass"}]},{"no":"4","instruction":"Computer. Unterstreichen Sie die Subjekte. Sind sie (nicht) gleich? Kreuzen Sie an.","instruction_en":"电脑。找出每个句子的主语，写出两个主语，再写 *gleich*（相同）或 *nicht gleich*（不相同）。大写的 *Sie* = 礼貌的“您”。","example":[{"label":"1","text":"Sie verlässt einfach das Büro. Sie sichert die Daten im Computer nicht. → **Sie** / **Sie** → **gleich**"}],"items":[{"label":"2","text":"Die Firma speichert unsere Daten. Wir haben keine Ahnung. → ___ / ___ → ___","gaps":[["Die Firma"],["Wir"],["nicht gleich"]],"solution":"Die Firma speichert unsere Daten. Wir haben keine Ahnung. → **Die Firma** / **Wir** → **nicht gleich**","en":"这家公司存储我们的数据。我们一点也不知道。→ 不相同","why":"两个不同的主语：*die Firma* 和 *wir*。","source":"ohnedass"},{"label":"3","text":"Wir sollten die Daten elektronisch verarbeiten. Wir warten nicht lange. → ___ / ___ → ___","gaps":[["Wir"],["Wir"],["gleich"]],"solution":"Wir sollten die Daten elektronisch verarbeiten. Wir warten nicht lange. → **Wir** / **Wir** → **gleich**","en":"我们应该用电子方式处理数据。我们不等很久。→ 相同","why":"两个句子都是 *wir*。","source":"g6865"},{"label":"4","text":"Sie können die Software installieren. Der Techniker hilft Ihnen nicht. → ___ / ___ → ___","gaps":[["Sie"],["Der Techniker"],["nicht gleich"]],"solution":"Sie können die Software installieren. Der Techniker hilft Ihnen nicht. → **Sie** / **Der Techniker** → **nicht gleich**","en":"您可以安装这个软件。技术员不帮您。→ 不相同","why":"*Ihnen* 是第三格宾语；第二个句子的主语是 *der Techniker*。","source":"ohnedass"},{"label":"5","text":"Ich schliesse den Computer an. Ich frage die IT-Abteilung nicht. → ___ / ___ → ___","gaps":[["Ich"],["Ich"],["gleich"]],"solution":"Ich schliesse den Computer an. Ich frage die IT-Abteilung nicht. → **Ich** / **Ich** → **gleich**","en":"我连接电脑。我不问 IT 部门。→ 相同","why":"两个句子都是 *ich*。","source":"g6865"}]},{"no":"5","instruction":"Verbinden Sie die Sätze aus 4 mit *ohne dass* und, wo möglich, mit *ohne zu*. Schreiben Sie in Ihr Heft.","instruction_en":"用 *ohne dass* 把练习 4 中的句子连起来；主语相同时，也用 *ohne … zu* 连。去掉 *nicht*；把 *keine* 变成 *eine*。","example":[{"label":"1","text":"Sie verlässt einfach das Büro, **ohne die Daten im Computer zu sichern**.\nSie verlässt einfach das Büro, **ohne dass sie die Daten im Computer sichert**."}],"items":[{"label":"2 · ohne dass","lead":"Die Firma speichert unsere Daten. Wir haben keine Ahnung.","text":"","accept":["Die Firma speichert unsere Daten, ohne dass wir eine Ahnung haben.","Die Firma speichert unsere Daten, ohne dass wir eine Ahnung davon haben."],"solution":"**Die Firma speichert unsere Daten, ohne dass wir eine Ahnung haben.**","en":"这家公司存储我们的数据，而我们对此毫不知情。","why":"主语不同 → 只能用 *ohne dass*；*keine Ahnung* → *eine Ahnung*。","source":"ohnedass"},{"label":"3 · ohne … zu","lead":"Wir sollten die Daten elektronisch verarbeiten. Wir warten nicht lange.","text":"","accept":["Wir sollten die Daten elektronisch verarbeiten, ohne lange zu warten."],"solution":"**Wir sollten die Daten elektronisch verarbeiten, ohne lange zu warten.**","en":"我们应该用电子方式处理数据，而不用等很久。","why":"主语相同：去掉 *nicht*，*zu warten* 放在句末。","source":"g6865"},{"label":"3 · ohne dass","lead":"Wir sollten die Daten elektronisch verarbeiten. Wir warten nicht lange.","text":"","accept":["Wir sollten die Daten elektronisch verarbeiten, ohne dass wir lange warten."],"solution":"**Wir sollten die Daten elektronisch verarbeiten, ohne dass wir lange warten.**","en":"我们应该用电子方式处理数据，而不用等很久。","why":"重复主语 *wir*，*warten* 放在句末。","source":"ohnedass"},{"label":"4 · ohne dass","lead":"Sie können die Software installieren. Der Techniker hilft Ihnen nicht.","text":"","accept":["Sie können die Software installieren, ohne dass der Techniker Ihnen hilft.","Sie können die Software installieren, ohne dass Ihnen der Techniker hilft."],"solution":"**Sie können die Software installieren, ohne dass der Techniker Ihnen hilft.**","en":"您可以安装这个软件，而不需要技术员帮您。","why":"主语不同 → 只能用 *ohne dass*；*hilft* 放在句末。","source":"ohnedass"},{"label":"5 · ohne … zu","lead":"Ich schliesse den Computer an. Ich frage die IT-Abteilung nicht.","text":"","accept":["Ich schliesse den Computer an, ohne die IT-Abteilung zu fragen."],"solution":"**Ich schliesse den Computer an, ohne die IT-Abteilung zu fragen.**","en":"我连接电脑，而不问 IT 部门。","why":"主语相同：*ohne die IT-Abteilung zu fragen*。","source":"g6865"},{"label":"5 · ohne dass","lead":"Ich schliesse den Computer an. Ich frage die IT-Abteilung nicht.","text":"","accept":["Ich schliesse den Computer an, ohne dass ich die IT-Abteilung frage."],"solution":"**Ich schliesse den Computer an, ohne dass ich die IT-Abteilung frage.**","en":"我连接电脑，而不问 IT 部门。","why":"重复主语 *ich*，*frage* 放在句末。","source":"ohnedass"}]},{"no":"6","instruction":"Was würden Sie gerne machen? Schreiben Sie Sätze mit *ohne … zu* in Ihr Heft.","instruction_en":"你想做什么？把方框第一部分里的一个愿望和第二部分里的一项内容组合起来，用 *ohne … zu*。划掉的短语已用在例句中。参考答案只是一种可能。","box":["viel Geld verdienen","eine eigene Firma gründen","fliessend Deutsch sprechen","mehrmals im Jahr verreisen","immer sparen","noch mehr arbeiten","Sprachkurse besuchen","die Risiken tragen"],"box_used":[0,5],"example":[{"label":"Beispiel","text":"Ich würde gerne viel Geld verdienen, **ohne noch mehr zu arbeiten**."}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich würde gerne eine eigene Firma gründen, ohne die Risiken zu tragen. Ich würde gerne fliessend Deutsch sprechen, ohne Sprachkurse zu besuchen. Ich würde gerne mehrmals im Jahr verreisen, ohne immer zu sparen.","en":"我想自己开一家公司，而不承担风险。我想说一口流利的德语，而不用上语言课。我想一年出去旅行好几次，而不用总是省钱。","why":"用 *würde gerne* + 不定式表达愿望，然后用 *ohne … zu*，不定式放在句末。","source":"g6865"}]}]},{"page":"Blatt 52 · S. 108","heading":"52  Ich fahre langsam, um Benzin zu sparen.","heading_en":"我开车开得慢，为了省油。（主句 + 目的从句：*um … zu, damit*）","exercises":[{"no":"A","instruction":"Lesen Sie und ordnen Sie zu.","instruction_en":"阅读句子，把每个句子和一张照片配对。照片 A：一个男人在拧暖气片的旋钮。照片 B：握着方向盘的双手。填 A 或 B。练习纸上的规则框 B 和 C 显示在下面。","reading":[{"label":"Alles, um die Umwelt zu schützen","text":"1 Ich fahre langsam, um Benzin zu sparen.\n2 Um Energie zu sparen, schalten wir die Heizung nachts aus."},{"label":"B  Lesen Sie.","text":"Infinitiv mit um zu: Ich fahre langsam, | um Benzin zu sparen.\nNebensatz mit damit: Ich fahre langsam, | damit ich Benzin spare.\nDie Subjekte in Haupt- und Nebensatz sind gleich: um zu oder damit\nIch fahre langsam, | um Benzin zu sparen. / damit ich Benzin spare.\nDie Subjekte in Haupt- und Nebensatz sind nicht gleich: immer damit\nMeine Eltern sparen, | damit ich studieren kann."},{"label":"C  Lesen Sie.","text":"• *um … zu* und *damit* drücken einen Zweck oder eine Absicht aus.\n• Der Satz mit *um … zu* ist ein Infinitivsatz. Am Ende steht der Infinitiv."}],"items":[{"label":"1","text":"Foto ___: Ich fahre langsam, um Benzin zu sparen.","gaps":[["B"]],"solution":"Foto **B**: Ich fahre langsam, um Benzin zu sparen.","en":"照片 B：我开车开得慢，为了省油。","why":"开车 → 方向盘。","source":"adverbial"},{"label":"2","text":"Foto ___: Um Energie zu sparen, schalten wir die Heizung nachts aus.","gaps":[["A"]],"solution":"Foto **A**: Um Energie zu sparen, schalten wir die Heizung nachts aus.","en":"照片 A：为了节约能源，我们晚上把暖气关掉。","why":"暖气 → 暖气片。*um … zu* 放在前面时，主句以动词开头：*schalten wir*。","source":"g6865"}]},{"no":"1","instruction":"Wozu das? Verbinden Sie die Sätze mit *um … zu* und schreiben Sie in Ihr Heft.","instruction_en":"为了什么？用 *um … zu* 把每个句子和括号里的目的连起来：*um* 放在逗号后面，*zu* + 不定式放在句末。","example":[{"label":"1","lead":"Wir fahren in die Berge. (→ wandern und ein Picknick machen)","text":"Wir fahren in die Berge, **um zu wandern und ein Picknick zu machen**."}],"items":[{"label":"2","lead":"Wir fahren an den See. (→ dort spazieren gehen)","text":"","accept":["Wir fahren an den See, um dort spazieren zu gehen."],"solution":"**Wir fahren an den See, um dort spazieren zu gehen.**","en":"我们去湖边，为了在那里散步。","why":"两个动词：*zu* 放在最后一个动词前面：*spazieren zu gehen*。","source":"g6865"},{"label":"3","lead":"Wir haben lange gespart. (→ die Wohnung kaufen)","text":"","accept":["Wir haben lange gespart, um die Wohnung zu kaufen."],"solution":"**Wir haben lange gespart, um die Wohnung zu kaufen.**","en":"我们攒了很长时间的钱，为了买下这套公寓。","why":"*um die Wohnung zu kaufen*：宾语放在 *um* 和 *zu* 之间。","source":"g6865"},{"label":"4","lead":"Ich muss in die Klinik. (→ meinen kranken Onkel besuchen)","text":"","accept":["Ich muss in die Klinik, um meinen kranken Onkel zu besuchen."],"solution":"**Ich muss in die Klinik, um meinen kranken Onkel zu besuchen.**","en":"我得去医院，为了看望我生病的叔叔。","why":"*um … zu besuchen*。","source":"g6865"},{"label":"5","lead":"Ihr müsst mehr trainieren. (→ am Marathon teilnehmen können)","text":"","accept":["Ihr müsst mehr trainieren, um am Marathon teilnehmen zu können."],"solution":"**Ihr müsst mehr trainieren, um am Marathon teilnehmen zu können.**","en":"你们得多训练，为了能参加马拉松。","why":"有情态动词时，*zu* 放在情态动词前面：*teilnehmen zu können*。","source":"g6865"},{"label":"6","lead":"Du musst Sport machen. (→ gesund bleiben)","text":"","accept":["Du musst Sport machen, um gesund zu bleiben."],"solution":"**Du musst Sport machen, um gesund zu bleiben.**","en":"你得做运动，为了保持健康。","why":"*um gesund zu bleiben*。","source":"g6865"}]}]},{"page":"Blatt 52 · S. 109","heading":"52  Ich fahre langsam, um Benzin zu sparen.","heading_en":"我开车开得慢，为了省油。","exercises":[{"no":"2","instruction":"Ordnen Sie zu und verbinden Sie Sätze mit *damit*. Beginnen Sie die Sätze auch mit *damit*. Schreiben Sie in Ihr Heft.","instruction_en":"把每个问题和一个目的（a–c）配对，然后回答两次：一次把 *damit* 放在主句后面，一次以 *Damit* 开头。在 *damit* 从句里动词放在句末；*Damit* 从句放在前面时，主句以动词开头。","phrases":["a  Wir prüfen endlich die Rechnung.","b  Meine Frau wartet nicht so lange.","c  Ich repariere ihr Fahrrad.","d  Du verstehst mich gut. (Beispiel)"],"example":[{"label":"1","lead":"Wozu übst du die Aussprache? → d","text":"Ich übe die Aussprache, **damit du mich gut verstehst**.\n**Damit du mich gut verstehst**, übe ich die Aussprache."}],"items":[{"label":"2","text":"Wozu holt Paul den Taschenrechner? → ___","gaps":[["a"]],"solution":"Wozu holt Paul den Taschenrechner? → **a**","en":"Paul 去拿计算器，好让我们终于能核对账单。","why":"找出和问题相符的目的。","source":"damit"},{"label":"2 · damit am Ende","lead":"Wozu holt Paul den Taschenrechner? → a","text":"","accept":["Paul holt den Taschenrechner, damit wir endlich die Rechnung prüfen.","Paul holt den Taschenrechner, damit wir endlich die Rechnung prüfen können."],"solution":"**Paul holt den Taschenrechner, damit wir endlich die Rechnung prüfen.**","en":"Paul 去拿计算器，好让我们终于能核对账单。","why":"新的主语 *wir* → *damit*；*prüfen* 放在句末。","source":"damit"},{"label":"2 · Damit am Anfang","lead":"Wozu holt Paul den Taschenrechner? → a","text":"","accept":["Damit wir endlich die Rechnung prüfen, holt Paul den Taschenrechner.","Damit wir endlich die Rechnung prüfen können, holt Paul den Taschenrechner."],"solution":"**Damit wir endlich die Rechnung prüfen, holt Paul den Taschenrechner.**","en":"Paul 去拿计算器，好让我们终于能核对账单。","why":"*Damit* 从句放在前面，后面接动词：*holt Paul*。","source":"damit"},{"label":"3","text":"Wozu fahren Sie so schnell? → ___","gaps":[["b"]],"solution":"Wozu fahren Sie so schnell? → **b**","en":"我开这么快，是为了让我妻子不用等那么久。","why":"找出和问题相符的目的。","source":"damit"},{"label":"3 · damit am Ende","lead":"Wozu fahren Sie so schnell? → b","text":"","accept":["Ich fahre so schnell, damit meine Frau nicht so lange wartet.","Ich fahre so schnell, damit meine Frau nicht so lange warten muss."],"solution":"**Ich fahre so schnell, damit meine Frau nicht so lange wartet.**","en":"我开这么快，是为了让我妻子不用等那么久。","why":"问题里用 *Sie*，回答里用 *ich*。这里保留 *nicht*：*damit* 不表示否定。","source":"damit"},{"label":"3 · Damit am Anfang","lead":"Wozu fahren Sie so schnell? → b","text":"","accept":["Damit meine Frau nicht so lange wartet, fahre ich so schnell.","Damit meine Frau nicht so lange warten muss, fahre ich so schnell."],"solution":"**Damit meine Frau nicht so lange wartet, fahre ich so schnell.**","en":"我开这么快，是为了让我妻子不用等那么久。","why":"*Damit* 从句放在前面，然后是 *fahre ich*。","source":"damit"},{"label":"4","text":"Wozu hat Emilia eine Zange mitgenommen? → ___","gaps":[["c"]],"solution":"Wozu hat Emilia eine Zange mitgenommen? → **c**","en":"Emilia 带了一把钳子，好让我能修她的自行车。","why":"找出和问题相符的目的。","source":"damit"},{"label":"4 · damit am Ende","lead":"Wozu hat Emilia eine Zange mitgenommen? → c","text":"","accept":["Emilia hat eine Zange mitgenommen, damit ich ihr Fahrrad repariere.","Emilia hat eine Zange mitgenommen, damit ich ihr Fahrrad reparieren kann."],"solution":"**Emilia hat eine Zange mitgenommen, damit ich ihr Fahrrad repariere.**","en":"Emilia 带了一把钳子，好让我能修她的自行车。","why":"*ihr Fahrrad* = Emilia 的自行车；新的主语 *ich* → *damit*。","source":"damit"},{"label":"4 · Damit am Anfang","lead":"Wozu hat Emilia eine Zange mitgenommen? → c","text":"","accept":["Damit ich ihr Fahrrad repariere, hat Emilia eine Zange mitgenommen.","Damit ich ihr Fahrrad reparieren kann, hat Emilia eine Zange mitgenommen."],"solution":"**Damit ich ihr Fahrrad repariere, hat Emilia eine Zange mitgenommen.**","en":"Emilia 带了一把钳子，好让我能修她的自行车。","why":"*Damit* 从句放在前面，然后是 *hat Emilia … mitgenommen*。","source":"damit"}]},{"no":"3","instruction":"Welche Sätze kann man mit *um … zu* verbinden? Kreuzen Sie an.","instruction_en":"哪些句子对可以用 *um … zu* 连起来？只有两个句子主语相同时才可以。填 *ja* 或 *nein*。","example":[{"label":"1","text":"Ich mache eine Zusatzqualifikation. Ich möchte die Teamleitung bekommen. → **ja**"}],"items":[{"label":"2","text":"Betty macht einen Sommerkurs in Paris. Ihre Noten in Französisch werden besser. → ___","gaps":[["nein"]],"solution":"Betty macht einen Sommerkurs in Paris. Ihre Noten in Französisch werden besser. → **nein**","en":"Betty 在巴黎上暑期课程。她的法语成绩越来越好。→ 否","why":"主语 *Betty* 和 *ihre Noten* 不同。","source":"g6865"},{"label":"3","text":"Wir brauchen Ihre Zustimmung. Wir möchten Ihnen Werbung zuschicken. → ___","gaps":[["ja"]],"solution":"Wir brauchen Ihre Zustimmung. Wir möchten Ihnen Werbung zuschicken. → **ja**","en":"我们需要您的同意。我们想给您寄广告。→ 是","why":"两句都是 *wir*。","source":"g6865"},{"label":"4","text":"David hat auch abends noch genügend Energie. Er möchte Sport machen. → ___","gaps":[["ja"]],"solution":"David hat auch abends noch genügend Energie. Er möchte Sport machen. → **ja**","en":"David 晚上也还有足够的精力。他想做运动。→ 是","why":"*Er* = David。","source":"g6865"},{"label":"5","text":"Ich bereite heute Abend schon alles vor. Ihr könnt morgen ganz früh losfahren. → ___","gaps":[["nein"]],"solution":"Ich bereite heute Abend schon alles vor. Ihr könnt morgen ganz früh losfahren. → **nein**","en":"我今天晚上就把一切准备好。你们明天可以很早出发。→ 否","why":"主语 *ich* 和 *ihr* 不同。","source":"g6865"},{"label":"6","text":"Wir kaufen immer öfter Bio-Qualität. Unsere Kinder können gesund essen. → ___","gaps":[["nein"]],"solution":"Wir kaufen immer öfter Bio-Qualität. Unsere Kinder können gesund essen. → **nein**","en":"我们越来越常买有机产品。我们的孩子可以吃得健康。→ 否","why":"主语 *wir* 和 *unsere Kinder* 不同。","source":"g6865"},{"label":"7","text":"Emma und Pia treffen sich in der Stadt. Sie möchten zusammen einkaufen. → ___","gaps":[["ja"]],"solution":"Emma und Pia treffen sich in der Stadt. Sie möchten zusammen einkaufen. → **ja**","en":"Emma 和 Pia 在城里见面。她们想一起去购物。→ 是","why":"*Sie* = Emma 和 Pia。","source":"g6865"},{"label":"8","text":"Du brauchst eine gute Arbeitstechnik. Du möchtest die Aufgaben schnell lösen. → ___","gaps":[["ja"]],"solution":"Du brauchst eine gute Arbeitstechnik. Du möchtest die Aufgaben schnell lösen. → **ja**","en":"你需要一种好的工作方法。你想快速解答这些题目。→ 是","why":"两句都是 *du*。","source":"g6865"}]},{"no":"4","instruction":"Verbinden Sie die Sätze in 3 mit *damit* und, wo möglich, mit *um … zu*. Schreiben Sie in Ihr Heft.","instruction_en":"用 *damit* 把练习 3 中的句子对连起来；主语相同时，也用 *um … zu* 连。去掉 *möchte(n)*：表示目的的词本身已经有“想要”的意思。","example":[{"label":"1","text":"Ich mache eine Zusatzqualifikation, **um die Teamleitung zu bekommen**.\nIch mache eine Zusatzqualifikation, **damit ich die Teamleitung bekomme**."}],"items":[{"label":"2 · damit","lead":"Betty macht einen Sommerkurs in Paris. Ihre Noten in Französisch werden besser.","text":"","accept":["Betty macht einen Sommerkurs in Paris, damit ihre Noten in Französisch besser werden.","Betty macht einen Sommerkurs in Paris, damit ihre Französischnoten besser werden."],"solution":"**Betty macht einen Sommerkurs in Paris, damit ihre Noten in Französisch besser werden.**","en":"Betty 在巴黎上暑期课程，好让她的法语成绩变好。","why":"主语不同 → 只能用 *damit*；*werden* 放在句末。","source":"damit"},{"label":"3 · um … zu","lead":"Wir brauchen Ihre Zustimmung. Wir möchten Ihnen Werbung zuschicken.","text":"","accept":["Wir brauchen Ihre Zustimmung, um Ihnen Werbung zuzuschicken."],"solution":"**Wir brauchen Ihre Zustimmung, um Ihnen Werbung zuzuschicken.**","en":"我们需要您的同意，以便给您寄广告。","why":"可分动词：*zuzuschicken*（zu + zu + schicken）；去掉 *möchten*。","source":"g6865"},{"label":"3 · damit","lead":"Wir brauchen Ihre Zustimmung. Wir möchten Ihnen Werbung zuschicken.","text":"","accept":["Wir brauchen Ihre Zustimmung, damit wir Ihnen Werbung zuschicken dürfen.","Wir brauchen Ihre Zustimmung, damit wir Ihnen Werbung zuschicken können.","Wir brauchen Ihre Zustimmung, damit wir Ihnen Werbung zuschicken."],"solution":"**Wir brauchen Ihre Zustimmung, damit wir Ihnen Werbung zuschicken dürfen.**","en":"我们需要您的同意，这样我们才可以给您寄广告。","why":"*damit wir … zuschicken dürfen*：同意就是给予许可，所以 *dürfen* 最合适。","source":"damit","check":"练习纸没有答案：这里用 *dürfen*、*können* 或不用情态动词都可以；问问老师想要哪一种。"},{"label":"4 · um … zu","lead":"David hat auch abends noch genügend Energie. Er möchte Sport machen.","text":"","accept":["David hat auch abends noch genügend Energie, um Sport zu machen."],"solution":"**David hat auch abends noch genügend Energie, um Sport zu machen.**","en":"David 晚上也还有足够的精力，用来做运动。","why":"主语相同：*um Sport zu machen*。","source":"g6865"},{"label":"4 · damit","lead":"David hat auch abends noch genügend Energie. Er möchte Sport machen.","text":"","accept":["David hat auch abends noch genügend Energie, damit er Sport machen kann.","David hat auch abends noch genügend Energie, damit er Sport macht."],"solution":"**David hat auch abends noch genügend Energie, damit er Sport machen kann.**","en":"David 晚上也还有足够的精力，这样他就能做运动。","why":"重复主语 *er*，动词放在句末。","source":"damit"},{"label":"5 · damit","lead":"Ich bereite heute Abend schon alles vor. Ihr könnt morgen ganz früh losfahren.","text":"","accept":["Ich bereite heute Abend schon alles vor, damit ihr morgen ganz früh losfahren könnt."],"solution":"**Ich bereite heute Abend schon alles vor, damit ihr morgen ganz früh losfahren könnt.**","en":"我今天晚上就把一切准备好，好让你们明天可以很早出发。","why":"主语不同 → 只能用 *damit*；*könnt* 放在最末尾。","source":"damit"},{"label":"6 · damit","lead":"Wir kaufen immer öfter Bio-Qualität. Unsere Kinder können gesund essen.","text":"","accept":["Wir kaufen immer öfter Bio-Qualität, damit unsere Kinder gesund essen können."],"solution":"**Wir kaufen immer öfter Bio-Qualität, damit unsere Kinder gesund essen können.**","en":"我们越来越常买有机产品，好让我们的孩子能吃得健康。","why":"主语不同 → 只能用 *damit*。","source":"damit"},{"label":"7 · um … zu","lead":"Emma und Pia treffen sich in der Stadt. Sie möchten zusammen einkaufen.","text":"","accept":["Emma und Pia treffen sich in der Stadt, um zusammen einzukaufen."],"solution":"**Emma und Pia treffen sich in der Stadt, um zusammen einzukaufen.**","en":"Emma 和 Pia 在城里见面，为了一起去购物。","why":"可分动词：*einzukaufen*（ein + zu + kaufen）。","source":"g6865"},{"label":"7 · damit","lead":"Emma und Pia treffen sich in der Stadt. Sie möchten zusammen einkaufen.","text":"","accept":["Emma und Pia treffen sich in der Stadt, damit sie zusammen einkaufen können.","Emma und Pia treffen sich in der Stadt, damit sie zusammen einkaufen."],"solution":"**Emma und Pia treffen sich in der Stadt, damit sie zusammen einkaufen können.**","en":"Emma 和 Pia 在城里见面，好让她们能一起去购物。","why":"重复主语 *sie*，动词放在句末。","source":"damit"},{"label":"8 · um … zu","lead":"Du brauchst eine gute Arbeitstechnik. Du möchtest die Aufgaben schnell lösen.","text":"","accept":["Du brauchst eine gute Arbeitstechnik, um die Aufgaben schnell zu lösen."],"solution":"**Du brauchst eine gute Arbeitstechnik, um die Aufgaben schnell zu lösen.**","en":"你需要一种好的工作方法，为了快速解答这些题目。","why":"主语相同：*um … zu lösen*。","source":"g6865"},{"label":"8 · damit","lead":"Du brauchst eine gute Arbeitstechnik. Du möchtest die Aufgaben schnell lösen.","text":"","accept":["Du brauchst eine gute Arbeitstechnik, damit du die Aufgaben schnell lösen kannst.","Du brauchst eine gute Arbeitstechnik, damit du die Aufgaben schnell löst."],"solution":"**Du brauchst eine gute Arbeitstechnik, damit du die Aufgaben schnell lösen kannst.**","en":"你需要一种好的工作方法，这样你才能快速解答这些题目。","why":"重复主语 *du*，动词放在句末。","source":"damit"}]},{"no":"5","instruction":"Lesen Sie Frau Deckers Blog und verbinden Sie die Sätze mit *um … zu* oder *damit*.","instruction_en":"阅读 Decker 女士的博客，把每对句子连起来：主语相同 → *um … zu*（最好）；主语不同 → *damit*。去掉 *möchte*。","reading":[{"label":"www.mein-tag.de","text":"1 Ich stehe morgens früh auf. Ich möchte noch vor dem Frühstück joggen.\n2 Ich fahre oft mit dem Auto ins Büro. Ich möchte pünktlich sein.\n3 Am Vormittag arbeite ich schnell und konzentriert. Meine Kunden sind zufrieden.\n4 Ich fahre in der Mittagspause in den Supermarkt. Ich kaufe schnell etwas fürs Abendessen ein.\n5 Ich verlasse die Firma um drei. Meine Kinder sind nicht zu lange allein."}],"example":[{"label":"1","text":"Ich stehe morgens früh auf, **um noch vor dem Frühstück zu joggen**."}],"items":[{"label":"2","lead":"Ich fahre oft mit dem Auto ins Büro. Ich möchte pünktlich sein.","text":"","accept":["Ich fahre oft mit dem Auto ins Büro, um pünktlich zu sein.","Ich fahre oft mit dem Auto ins Büro, damit ich pünktlich bin."],"solution":"**Ich fahre oft mit dem Auto ins Büro, um pünktlich zu sein.**","en":"我经常开车去办公室，好准时到达。","why":"主语相同，都是 *ich* → *um pünktlich zu sein*。","source":"g6865"},{"label":"3","lead":"Am Vormittag arbeite ich schnell und konzentriert. Meine Kunden sind zufrieden.","text":"","accept":["Am Vormittag arbeite ich schnell und konzentriert, damit meine Kunden zufrieden sind."],"solution":"**Am Vormittag arbeite ich schnell und konzentriert, damit meine Kunden zufrieden sind.**","en":"上午我工作又快又专注，好让我的客户满意。","why":"新的主语 *meine Kunden* → *damit*；*sind* 放在句末。","source":"damit"},{"label":"4","lead":"Ich fahre in der Mittagspause in den Supermarkt. Ich kaufe schnell etwas fürs Abendessen ein.","text":"","accept":["Ich fahre in der Mittagspause in den Supermarkt, um schnell etwas fürs Abendessen einzukaufen.","Ich fahre in der Mittagspause in den Supermarkt, damit ich schnell etwas fürs Abendessen einkaufe."],"solution":"**Ich fahre in der Mittagspause in den Supermarkt, um schnell etwas fürs Abendessen einzukaufen.**","en":"我午休时开车去超市，为了快速买点晚饭要用的东西。","why":"主语相同；可分动词：*einzukaufen*（ein + zu + kaufen）。","source":"g6865"},{"label":"5","lead":"Ich verlasse die Firma um drei. Meine Kinder sind nicht zu lange allein.","text":"","accept":["Ich verlasse die Firma um drei, damit meine Kinder nicht zu lange allein sind."],"solution":"**Ich verlasse die Firma um drei, damit meine Kinder nicht zu lange allein sind.**","en":"我三点离开公司，好让我的孩子们不会独自待太久。","why":"新的主语 *meine Kinder* → *damit*；保留 *nicht*（只有 *ohne* 和 *anstatt* 会把它“吞掉”）。","source":"damit"}]},{"no":"6","instruction":"Wozu machen Sie was? Schreiben Sie 3 Sätze über Ihren Tag in Ihr Heft und nennen Sie den Zweck.","instruction_en":"你做什么，为了什么？写 3 个关于你一天的句子，用 *um … zu* 或 *damit* 说明目的。参考答案只是一种可能。","example":[{"label":"Beispiel","text":"Ich gehe schon um drei aus dem Büro, **um früh bei den Kindern zu sein**."}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich stehe um halb sieben auf, um den Zug nach Zürich zu erreichen. Ich nehme mein Mittagessen von zu Hause mit, um Geld zu sparen. Am Abend lerne ich eine halbe Stunde Deutsch, damit meine Chancen im Job besser werden.","en":"我六点半起床，为了赶上去苏黎世的火车。我从家里带午饭，为了省钱。晚上我学半个小时德语，好让我在工作中的机会变得更好。","why":"主语相同 → *um … zu*；新的主语（*meine Chancen*）→ *damit*。","source":"adverbial"}]}]}],"sources":[{"id":"g6865","title":"grammis：Vertiefung: Infinitivsätze（um / ohne / anstatt … zu 没有自己的主语；主语来自主句）","url":"https://grammis.ids-mannheim.de/progr@mm/6865"},{"id":"damit","title":"grammis 连词词典：damit（从属连词，动词在句末）","url":"https://grammis.ids-mannheim.de/konnektoren/407001"},{"id":"adverbial","title":"grammis：Adverbial（um … zu 和 damit 从句是表示目的的状语）","url":"https://grammis.ids-mannheim.de/vggf/2280"},{"id":"ohnedass","title":"grammis 连词词典：ohne dass（从属连词，动词在句末；带否定含义：从句说的是没有发生的事）","url":"https://grammis.ids-mannheim.de/konnektoren/406910"},{"id":"anstattdass","title":"grammis 连词词典：anstatt dass（从属连词，动词在句末；表示替代并带否定含义；也可以说 statt dass）","url":"https://grammis.ids-mannheim.de/konnektoren/406953"}]}];
